fn cvtss2si_rounding_mode(mxcsr: u32) -> RationalRoundingMode {
    match (mxcsr >> 13) & 3 {
        0 => RationalRoundingMode::NearestTiesEven,
        1 => RationalRoundingMode::TowardNegative,
        2 => RationalRoundingMode::TowardPositive,
        _ => RationalRoundingMode::TowardZero,
    }
}

/// Maximum successful string iterations processed by one instruction invocation.
pub const REP_ITERATION_WORK_LIMIT: u64 = 1024;

const MIN_MAX_MXCSR_EXCEPTION_MASKS: u32 = 0x0000_1f80;
const MIN_MAX_MXCSR_DAZ_FTZ: u32 = 0x0000_8040;

const fn min_max_mxcsr_supported(mxcsr: u32) -> bool {
    mxcsr & 0xffff_0000 == 0
        && mxcsr & MIN_MAX_MXCSR_EXCEPTION_MASKS == MIN_MAX_MXCSR_EXCEPTION_MASKS
        && mxcsr & MIN_MAX_MXCSR_DAZ_FTZ == 0
}

const fn minss_invalid_mxcsr_supported(mxcsr: u32) -> bool {
    mxcsr & 0xffff_0000 == 0
        && mxcsr & 0x0000_1f00 == 0x0000_1f00
        && mxcsr & MIN_MAX_MXCSR_DAZ_FTZ == 0
}

const fn minss_unmasked_denormal_mxcsr_supported(mxcsr: u32) -> bool {
    mxcsr & 0xffff_0000 == 0
        && mxcsr & 0x0000_1e00 == 0x0000_1e00
        && mxcsr & MIN_MAX_MXCSR_DAZ_FTZ == 0
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum StepOutcome {
    Advanced,
    Branched,
    Halted,
    RepIterationBudgetExhausted,
    StopRequested,
    Fault(ArchitecturalFault),
    Unsupported { opcode: u8 },
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum RunExit {
    StopAddress,
    Halted,
    InstructionBudgetExhausted,
    RepIterationBudgetExhausted,
    StopRequested,
    Fault(ArchitecturalFault),
    Unsupported { opcode: u8 },
    MemoryError(MemoryError),
}

