/// The only CR0 contract selected by this bounded FP initialization slice.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Cr0Profile {
    FpInitLong64V1,
    EferReadOnlyLong64V1,
}

impl Cr0Profile {
    pub const BASE: u64 = 0x0000_0000_8001_0033;

    pub const fn accepts(self, value: u64) -> bool {
        value & !0xcu64 == Self::BASE
    }
}

/// The bounded mutable CR4 contract used by the S2-25b FP-init composition.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Cr4Profile {
    FpInitLong64V1,
    EferReadOnlyLong64V1,
    FpInitThenFxsave64Long64V1,
    FpInitThenFxrstor64Long64V1,
    FpInitThenFxrstor64MinssLong64V1,
}

impl Cr4Profile {
    pub const BASE: u64 = 1 << 5;

    pub const fn accepts(self, value: u64) -> bool {
        value & !((1 << 9) | (1 << 10)) == Self::BASE
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FxCr0GateControls {
    Save(Fxsave64Cr0Controls),
    Restore(Fxrstor64Cr0Controls),
}

