#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RunResult {
    pub exit: RunExit,
    pub instructions_executed: u64,
    /// Architectural definedness of the admitted integer-profile RFLAGS bits.
    /// Concrete undefined flag values in `state` are not comparison promises.
    pub rflags_defined: u64,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum RunInputError {
    InvalidRflagsDefined { value: u64 },
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum MaskableRequestRunInputError {
    InvalidRflagsDefined { value: u64 },
    IncompatibleEntryFlags { value: u64 },
    Cr0StateOutsideSelectedProfile,
    InterruptInhibitionActive,
    InvalidHaltedState,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum MaskableRequestRunResult {
    InterruptEligible { vector: u8, rip: u64 },
    Run(RunResult),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum StiSequenceProgress {
    StartIfClear,
    StartIfSet,
    AfterSti,
    AfterCli,
    AfterCliSti,
    AfterShadow,
    Done,
}

impl StiSequenceProgress {
    fn new(state: &LongModeState) -> Self {
        if state.sti_shadow == Some(crate::StiShadow::Blocking) {
            Self::AfterShadow
        } else if state.rflags & (1 << 9) == 0 {
            Self::StartIfClear
        } else {
            Self::StartIfSet
        }
    }

    fn admit(&mut self, instruction: &long_decode::Instruction, hlt_profile: bool) -> bool {
        let operation = instruction.operation;
        let sti = operation == Operation::Sti;
        let cli = operation == Operation::Cli;
        let hlt = operation == Operation::Hlt
            && instruction.length == 1
            && instruction.prefixes == Prefixes::default();
        if hlt_profile {
            let next = match self {
                Self::StartIfClear if hlt => Some(Self::Done),
                Self::StartIfClear if sti => Some(Self::AfterSti),
                Self::StartIfClear if cli => Some(Self::AfterCli),
                Self::StartIfSet if hlt => Some(Self::Done),
                Self::StartIfSet if sti => Some(Self::AfterSti),
                Self::StartIfSet if cli => Some(Self::AfterCli),
                Self::AfterSti if hlt => Some(Self::Done),
                Self::AfterCli if hlt => Some(Self::Done),
                Self::AfterCli if sti => Some(Self::AfterCliSti),
                Self::AfterCliSti if hlt => Some(Self::Done),
                Self::AfterShadow if hlt => Some(Self::Done),
                _ => None,
            };
            let Some(next) = next else {
                return false;
            };
            *self = next;
            return true;
        }
        let nop = operation == Operation::Nop
            && instruction.length == 1
            && instruction.prefixes == Prefixes::default();
        let next = match self {
            Self::StartIfClear if sti => Some(Self::AfterSti),
            Self::StartIfClear if cli => Some(Self::AfterCli),
            Self::StartIfSet if sti => Some(Self::Done),
            Self::AfterSti if nop || sti || cli => Some(Self::Done),
            Self::AfterCli if sti => Some(Self::AfterCliSti),
            Self::AfterCliSti if nop => Some(Self::Done),
            Self::AfterShadow if nop || sti || cli => Some(Self::Done),
            _ => None,
        };
        let Some(next) = next else {
            return false;
        };
        *self = next;
        true
    }
}

/// Explicit in-memory restart state for bounded address-size-32 REPNE strings.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RepContinuation {
    rip: u64,
    operand_size: OperandSize,
    address_size: OperandSize,
    instruction_length: u8,
    entry_rflags: u64,
    entry_defined: u64,
    operand: RepContinuationOperand,
    expected_rcx: u64,
    expected_rdi: u64,
    expected_rflags: u64,
    expected_defined: u64,
    context: AccessContext,
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum RepContinuationOperand {
    Scas { rax: u64, size: OperandSize },
    Cmps { rsi: u64, size: OperandSize },
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum RepRunInputError {
    InvalidRflagsDefined { value: u64 },
    InterruptInhibitionActive,
    Cr0StateOutsideSelectedProfile,
    ContinuationStateMismatch,
    ContinuationInstructionMismatch,
}

/// Execute with explicit restart metadata for bounded addr32 REPNE SCAS/CMPS.
/// Passing `None` starts a new execution boundary; a partial snapshot alone is
/// not enough to reconstruct an in-progress token.
pub fn run_with_rep_continuation(
    state: &mut LongModeState,
    memory: &mut impl GuestMemory,
    config: RunConfig,
    initial_rflags_defined: u64,
    continuation: &mut Option<RepContinuation>,
    mut stop_requested: impl FnMut() -> bool,
) -> Result<RunResult, RepRunInputError> {
    if state.cr0.is_some() || state.cr4.is_some() {
        return Err(RepRunInputError::Cr0StateOutsideSelectedProfile);
    }
    if state.sti_shadow == Some(crate::StiShadow::Blocking) {
        return Err(RepRunInputError::InterruptInhibitionActive);
    }
    if initial_rflags_defined & !crate::INTEGER_FLAGS != 0 {
        return Err(RepRunInputError::InvalidRflagsDefined {
            value: initial_rflags_defined,
        });
    }
    if let Some(token) = continuation.as_ref() {
        if token.rip != state.rip
            || token.expected_rcx != state.gpr[Register::Rcx as usize]
            || token.expected_rdi != state.gpr[Register::Rdi as usize]
            || token.expected_rflags != state.rflags
            || token.expected_defined != initial_rflags_defined
            || token.context != config.context
            || !rep_continuation_operand_matches(token, state)
        {
            return Err(RepRunInputError::ContinuationStateMismatch);
        }
    }
    let mut defined = initial_rflags_defined;
    let mut retired = 0;
    loop {
        if config.stop_rip == Some(state.rip) {
            return Ok(rep_run_result(RunExit::StopAddress, retired, defined));
        }
        if stop_requested() {
            return Ok(rep_run_result(RunExit::StopRequested, retired, defined));
        }
        if retired == config.instruction_budget {
            return Ok(rep_run_result(
                RunExit::InstructionBudgetExhausted,
                retired,
                defined,
            ));
        }
        if state.activity == Some(crate::CpuActivity::Halted) {
            return Ok(rep_run_result(RunExit::Halted, retired, defined));
        }
        let target_instruction;
        if continuation.is_some() {
            let instruction = match long_decode::decode(memory, state.rip, config.context) {
                Ok(instruction) => instruction,
                Err(DecodeError::Memory(MemoryError::Architectural(fault))) => {
                    let token = continuation.take().expect("validated continuation");
                    state.rflags = token.entry_rflags;
                    defined = token.entry_defined;
                    return Ok(rep_run_result(RunExit::Fault(fault), retired, defined));
                }
                Err(DecodeError::Memory(error)) => {
                    return Ok(rep_run_result(
                        RunExit::MemoryError(error),
                        retired,
                        defined,
                    ));
                }
                Err(_) => return Err(RepRunInputError::ContinuationInstructionMismatch),
            };
            let token = continuation.as_ref().expect("validated continuation");
            if !matches!(instruction.opcode.byte, 0xae | 0xaf | 0xa6 | 0xa7)
                || instruction.address_size != OperandSize::Dword
                || token_instruction_identity(token, &instruction).is_err()
            {
                return Err(RepRunInputError::ContinuationInstructionMismatch);
            }
            target_instruction = Some(instruction);
        } else {
            match step_tracked_with_stop(
                state,
                memory,
                config.context,
                &mut defined,
                &mut stop_requested,
            ) {
                Ok(StepOutcome::Advanced | StepOutcome::Branched) => {
                    retired += 1;
                    continue;
                }
                Ok(StepOutcome::Fault(fault)) => {
                    return Ok(rep_run_result(RunExit::Fault(fault), retired, defined));
                }
                Ok(StepOutcome::RepIterationBudgetExhausted) => {
                    return Ok(rep_run_result(
                        RunExit::RepIterationBudgetExhausted,
                        retired,
                        defined,
                    ));
                }
                Ok(StepOutcome::StopRequested) => {
                    return Ok(rep_run_result(RunExit::StopRequested, retired, defined));
                }
                Ok(StepOutcome::Halted) => {
                    return Ok(rep_run_result(RunExit::Halted, retired, defined));
                }
                Ok(StepOutcome::Unsupported { opcode })
                    if matches!(opcode, 0xae | 0xaf | 0xa6 | 0xa7) =>
                {
                    match long_decode::decode(memory, state.rip, config.context) {
                        Ok(instruction)
                            if matches!(
                                instruction.operation,
                                Operation::RepneScasbAddr32
                                    | Operation::RepneScasWdqAddr32 { .. }
                                    | Operation::RepneCmpsbAddr32
                                    | Operation::RepneCmpsWdqAddr32 { .. }
                            ) && instruction.address_size == OperandSize::Dword =>
                        {
                            target_instruction = Some(instruction);
                        }
                        Ok(_) => {
                            return Ok(rep_run_result(
                                RunExit::Unsupported { opcode },
                                retired,
                                defined,
                            ));
                        }
                        Err(DecodeError::Memory(MemoryError::Architectural(fault))) => {
                            return Ok(rep_run_result(RunExit::Fault(fault), retired, defined));
                        }
                        Err(DecodeError::Memory(error)) => {
                            return Ok(rep_run_result(
                                RunExit::MemoryError(error),
                                retired,
                                defined,
                            ));
                        }
                        Err(_) => {
                            return Ok(rep_run_result(
                                RunExit::Unsupported { opcode },
                                retired,
                                defined,
                            ));
                        }
                    }
                }
                Ok(StepOutcome::Unsupported { opcode }) => {
                    return Ok(rep_run_result(
                        RunExit::Unsupported { opcode },
                        retired,
                        defined,
                    ));
                }
                Err(error) => {
                    return Ok(rep_run_result(
                        RunExit::MemoryError(error),
                        retired,
                        defined,
                    ));
                }
            }
        }
        if let Some(instruction) = target_instruction {
            match execute_repne_addr32(
                state,
                memory,
                config.context,
                &instruction,
                &mut defined,
                continuation,
                &mut stop_requested,
            ) {
                Ok(RepSpecialExit::Complete) => retired += 1,
                Ok(RepSpecialExit::Unsupported(opcode)) => {
                    return Ok(rep_run_result(
                        RunExit::Unsupported { opcode },
                        retired,
                        defined,
                    ));
                }
                Ok(RepSpecialExit::Stopped) => {
                    return Ok(rep_run_result(RunExit::StopRequested, retired, defined));
                }
                Ok(RepSpecialExit::Limited) => {
                    return Ok(rep_run_result(
                        RunExit::RepIterationBudgetExhausted,
                        retired,
                        defined,
                    ));
                }
                Ok(RepSpecialExit::Fault(fault)) => {
                    return Ok(rep_run_result(RunExit::Fault(fault), retired, defined));
                }
                Err(error) => {
                    return Ok(rep_run_result(
                        RunExit::MemoryError(error),
                        retired,
                        defined,
                    ));
                }
            }
        } else {
            match step_tracked_with_stop(
                state,
                memory,
                config.context,
                &mut defined,
                &mut stop_requested,
            ) {
                Ok(StepOutcome::Advanced | StepOutcome::Branched) => retired += 1,
                Ok(StepOutcome::Fault(fault)) => {
                    return Ok(rep_run_result(RunExit::Fault(fault), retired, defined));
                }
                Ok(StepOutcome::RepIterationBudgetExhausted) => {
                    return Ok(rep_run_result(
                        RunExit::RepIterationBudgetExhausted,
                        retired,
                        defined,
                    ));
                }
                Ok(StepOutcome::StopRequested) => {
                    return Ok(rep_run_result(RunExit::StopRequested, retired, defined));
                }
                Ok(StepOutcome::Halted) => {
                    return Ok(rep_run_result(RunExit::Halted, retired, defined));
                }
                Ok(StepOutcome::Unsupported { opcode }) => {
                    return Ok(rep_run_result(
                        RunExit::Unsupported { opcode },
                        retired,
                        defined,
                    ));
                }
                Err(error) => {
                    return Ok(rep_run_result(
                        RunExit::MemoryError(error),
                        retired,
                        defined,
                    ));
                }
            }
        }
    }
}

fn rep_continuation_operand_matches(token: &RepContinuation, state: &LongModeState) -> bool {
    match token.operand {
        RepContinuationOperand::Scas { rax, .. } => rax == state.gpr[Register::Rax as usize],
        RepContinuationOperand::Cmps { rsi, .. } => rsi == state.gpr[Register::Rsi as usize],
    }
}

fn token_instruction_identity(
    token: &RepContinuation,
    instruction: &long_decode::Instruction,
) -> Result<(), ()> {
    let expected_size = match token.operand {
        RepContinuationOperand::Scas { size, .. } => size,
        RepContinuationOperand::Cmps { size, .. } => size,
    };
    let matches_kind = match (&token.operand, &instruction.operation) {
        (
            RepContinuationOperand::Scas { size, .. },
            Operation::RepneScasWdqAddr32 { size: decoded },
        ) => size == decoded,
        (
            RepContinuationOperand::Scas {
                size: OperandSize::Byte,
                ..
            },
            Operation::RepneScasbAddr32,
        ) => true,
        (RepContinuationOperand::Cmps { size, .. }, Operation::RepneCmpsbAddr32) => {
            *size == OperandSize::Byte
        }
        (
            RepContinuationOperand::Cmps { size, .. },
            Operation::RepneCmpsWdqAddr32 { size: decoded },
        ) => size == decoded,
        _ => false,
    };
    if matches_kind
        && token.operand_size == expected_size
        && token.address_size == OperandSize::Dword
        && instruction.operand_size == token.operand_size
        && instruction.address_size == token.address_size
        && instruction.length == token.instruction_length
    {
        Ok(())
    } else {
        Err(())
    }
}

fn rep_run_result(exit: RunExit, instructions_executed: u64, rflags_defined: u64) -> RunResult {
    RunResult {
        exit,
        instructions_executed,
        rflags_defined,
    }
}

enum RepSpecialExit {
    Complete,
    Stopped,
    Limited,
    Fault(ArchitecturalFault),
    Unsupported(u8),
}

fn execute_repne_addr32(
    state: &mut LongModeState,
    memory: &mut impl GuestMemory,
    context: AccessContext,
    instruction: &long_decode::Instruction,
    defined: &mut u64,
    continuation: &mut Option<RepContinuation>,
    stop_requested: &mut impl FnMut() -> bool,
) -> Result<RepSpecialExit, MemoryError> {
    let cmps = matches!(
        instruction.operation,
        Operation::RepneCmpsbAddr32 | Operation::RepneCmpsWdqAddr32 { .. }
    );
    let size = match instruction.operation {
        Operation::RepneScasWdqAddr32 { size } | Operation::RepneCmpsWdqAddr32 { size } => size,
        Operation::RepneScasbAddr32 | Operation::RepneCmpsbAddr32 => OperandSize::Byte,
        _ => unreachable!("bounded REPNE executor receives an admitted operation"),
    };
    if *defined & crate::ARITHMETIC_FLAGS != crate::ARITHMETIC_FLAGS {
        return Ok(RepSpecialExit::Unsupported(instruction.opcode.byte));
    }
    let next_rip = state.rip.wrapping_add(u64::from(instruction.length));
    let fresh = continuation.is_none();
    if fresh && state.gpr[Register::Rcx as usize] as u32 == 0 {
        state.rip = next_rip;
        return Ok(RepSpecialExit::Complete);
    }
    if fresh {
        *continuation = Some(RepContinuation {
            rip: state.rip,
            operand_size: size,
            address_size: instruction.address_size,
            instruction_length: instruction.length,
            entry_rflags: state.rflags,
            entry_defined: *defined,
            operand: if cmps {
                RepContinuationOperand::Cmps {
                    rsi: state.gpr[Register::Rsi as usize],
                    size,
                }
            } else {
                RepContinuationOperand::Scas {
                    rax: state.gpr[Register::Rax as usize],
                    size,
                }
            },
            expected_rcx: state.gpr[Register::Rcx as usize],
            expected_rdi: state.gpr[Register::Rdi as usize],
            expected_rflags: state.rflags,
            expected_defined: *defined,
            context,
        });
    }
    for _ in 0..REP_ITERATION_WORK_LIMIT {
        let observed = if cmps {
            let source = Operand::Memory(MemoryOperand {
                base: AddressBase::Register(Register::Rsi),
                index: None,
                scale: 1,
                displacement: 0,
                address_size: OperandSize::Dword,
                size,
            });
            let source_value = match read_operand(state, memory, context, next_rip, source) {
                Ok(value) => value,
                Err(MemoryError::Architectural(fault)) => {
                    restore_rep_entry_flags(state, defined, continuation);
                    return Ok(RepSpecialExit::Fault(fault));
                }
                Err(error) => return Err(error),
            };
            let destination = Operand::Memory(MemoryOperand {
                base: AddressBase::Register(Register::Rdi),
                index: None,
                scale: 1,
                displacement: 0,
                address_size: OperandSize::Dword,
                size,
            });
            let destination_value =
                match read_operand(state, memory, context, next_rip, destination) {
                    Ok(value) => value,
                    Err(MemoryError::Architectural(fault)) => {
                        restore_rep_entry_flags(state, defined, continuation);
                        return Ok(RepSpecialExit::Fault(fault));
                    }
                    Err(error) => return Err(error),
                };
            (source_value, destination_value)
        } else {
            let destination = Operand::Memory(MemoryOperand {
                base: AddressBase::Register(Register::Rdi),
                index: None,
                scale: 1,
                displacement: 0,
                address_size: OperandSize::Dword,
                size,
            });
            let observed = match read_operand(state, memory, context, next_rip, destination) {
                Ok(value) => value,
                Err(MemoryError::Architectural(fault)) => {
                    restore_rep_entry_flags(state, defined, continuation);
                    return Ok(RepSpecialExit::Fault(fault));
                }
                Err(error) => return Err(error),
            };
            (state.gpr[Register::Rax as usize] & size.mask(), observed)
        };
        let (_, flags) = arithmetic_result(
            size,
            ArithmeticKind::Cmp,
            observed.0,
            observed.1,
            state.rflags,
        );
        state.rflags = flags;
        *defined |= crate::ARITHMETIC_FLAGS;
        let index = state.gpr[Register::Rdi as usize] as u32;
        let index = if state.rflags & crate::DF == 0 {
            index.wrapping_add(size.bytes() as u32)
        } else {
            index.wrapping_sub(size.bytes() as u32)
        };
        state.gpr[Register::Rdi as usize] = u64::from(index);
        if cmps {
            let index = state.gpr[Register::Rsi as usize] as u32;
            let index = if state.rflags & crate::DF == 0 {
                index.wrapping_add(size.bytes() as u32)
            } else {
                index.wrapping_sub(size.bytes() as u32)
            };
            state.gpr[Register::Rsi as usize] = u64::from(index);
        }
        let count = (state.gpr[Register::Rcx as usize] as u32).wrapping_sub(1);
        state.gpr[Register::Rcx as usize] = u64::from(count);
        if count == 0 || state.rflags & crate::ZF != 0 {
            state.rip = next_rip;
            *continuation = None;
            return Ok(RepSpecialExit::Complete);
        }
        checkpoint_rep(state, *defined, continuation);
        if stop_requested() {
            return Ok(RepSpecialExit::Stopped);
        }
    }
    checkpoint_rep(state, *defined, continuation);
    Ok(RepSpecialExit::Limited)
}

fn checkpoint_rep(state: &LongModeState, defined: u64, continuation: &mut Option<RepContinuation>) {
    if let Some(token) = continuation {
        match &mut token.operand {
            RepContinuationOperand::Scas { rax, .. } => *rax = state.gpr[Register::Rax as usize],
            RepContinuationOperand::Cmps { rsi, .. } => *rsi = state.gpr[Register::Rsi as usize],
        }
        token.expected_rcx = state.gpr[Register::Rcx as usize];
        token.expected_rdi = state.gpr[Register::Rdi as usize];
        token.expected_rflags = state.rflags;
        token.expected_defined = defined;
    }
}

fn restore_rep_entry_flags(
    state: &mut LongModeState,
    defined: &mut u64,
    continuation: &mut Option<RepContinuation>,
) {
    if let Some(token) = continuation.take() {
        state.rflags = token.entry_rflags;
        *defined = token.entry_defined;
    }
}

pub fn run(
    state: &mut LongModeState,
    memory: &mut impl GuestMemory,
    config: RunConfig,
    mut stop_requested: impl FnMut() -> bool,
) -> RunResult {
    // Preserve the historical fresh-entry behavior. Callers that resume a
    // tracked execution can pass the preceding result's mask explicitly.
    run_execution_loop(
        state,
        memory,
        config,
        crate::INTEGER_FLAGS,
        &mut stop_requested,
    )
}

