fn run_configured(
    state: &mut LongModeState,
    memory: &mut impl GuestMemory,
    config: RunConfig,
    mut rflags_defined: u64,
    profiles: ExecutionProfiles<'_>,
    mut runtime: StepRuntime<'_, '_, '_>,
) -> RunResult {
    let sti_profile = profiles.sti;
    let halt_profile = profiles.halt;
    let rdtsc_source = &mut runtime.rdtsc_source;
    let stop_requested = &mut runtime.stop_requested;
    if (state.cr0.is_some() && profiles.cr0.is_none())
        || (state.cr4.is_some() && profiles.cr4.is_none())
    {
        return RunResult {
            exit: RunExit::Unsupported { opcode: 0x0f },
            instructions_executed: 0,
            rflags_defined,
        };
    }
    if let Some(profile) = profiles.cr0
        && (config.context.mode != InstructionMode::Long64
            || !state.cr0.is_some_and(|value| profile.accepts(value))
            || (profile != Cr0Profile::EferReadOnlyLong64V1
                && state.x87.as_ref().is_none_or(|x87| {
                    x87.instruction_selector.is_some() || x87.data_selector.is_some()
                }))
            || (profile != Cr0Profile::EferReadOnlyLong64V1
                && (state.activity != Some(crate::CpuActivity::Running)
                    || state.sti_shadow != Some(crate::StiShadow::Clear))))
    {
        return RunResult {
            exit: RunExit::Unsupported { opcode: 0x0f },
            instructions_executed: 0,
            rflags_defined,
        };
    }
    if let Some(profile) = profiles.cr4
        && (config.context.mode != InstructionMode::Long64
            || !state.cr4.is_some_and(|value| profile.accepts(value))
            || !state
                .cr0
                .is_some_and(|value| Cr0Profile::FpInitLong64V1.accepts(value))
            || (profile != Cr4Profile::EferReadOnlyLong64V1
                && state.x87.as_ref().is_none_or(|x87| {
                    x87.instruction_selector.is_some() || x87.data_selector.is_some()
                }))
            || (profile != Cr4Profile::EferReadOnlyLong64V1
                && (state.activity != Some(crate::CpuActivity::Running)
                    || state.sti_shadow != Some(crate::StiShadow::Clear))))
    {
        return RunResult {
            exit: RunExit::Unsupported { opcode: 0x0f },
            instructions_executed: 0,
            rflags_defined,
        };
    }
    if halt_profile.is_some()
        && (config.context.mode != InstructionMode::Long64
            || state.activity.is_none()
            || state.sti_shadow.is_none()
            || (state.activity == Some(crate::CpuActivity::Halted)
                && state.sti_shadow == Some(crate::StiShadow::Blocking)))
    {
        return RunResult {
            exit: RunExit::Unsupported { opcode: 0xf4 },
            instructions_executed: 0,
            rflags_defined,
        };
    }
    if sti_profile.is_some() && state.sti_shadow.is_none() {
        return RunResult {
            exit: RunExit::Unsupported { opcode: 0xfb },
            instructions_executed: 0,
            rflags_defined,
        };
    }
    if sti_profile.is_some()
        && state.sti_shadow == Some(crate::StiShadow::Blocking)
        && state.rflags & (1 << 9) == 0
    {
        return RunResult {
            exit: RunExit::Unsupported { opcode: 0xfb },
            instructions_executed: 0,
            rflags_defined,
        };
    }
    if sti_profile.is_none() && state.sti_shadow == Some(crate::StiShadow::Blocking) {
        return RunResult {
            exit: RunExit::Unsupported { opcode: 0xfb },
            instructions_executed: 0,
            rflags_defined,
        };
    }
    let mut sti_sequence = sti_profile.map(|_| StiSequenceProgress::new(state));
    let mut retired = 0;
    loop {
        // The harness address is checked first; STOP then budget are checked
        // before fetch at every instruction boundary. A fault does not retire.
        let exit = if config.stop_rip == Some(state.rip) {
            Some(RunExit::StopAddress)
        } else if stop_requested() {
            Some(RunExit::StopRequested)
        } else if retired == config.instruction_budget {
            Some(RunExit::InstructionBudgetExhausted)
        } else if state.activity == Some(crate::CpuActivity::Halted) {
            Some(RunExit::Halted)
        } else {
            let old_shadow = state.sti_shadow;
            let outcome = if let Some(source) = rdtsc_source.take() {
                let outcome = step_configured(
                    state,
                    memory,
                    config.context,
                    &mut rflags_defined,
                    profiles,
                    StepRuntime {
                        rdtsc_source: Some(&mut *source),
                        sti_sequence: sti_sequence.as_mut(),
                        exact_hlt_only: false,
                        stop_requested: &mut **stop_requested,
                    },
                );
                *rdtsc_source = Some(source);
                outcome
            } else {
                step_configured(
                    state,
                    memory,
                    config.context,
                    &mut rflags_defined,
                    profiles,
                    StepRuntime {
                        rdtsc_source: None,
                        sti_sequence: sti_sequence.as_mut(),
                        exact_hlt_only: false,
                        stop_requested: &mut **stop_requested,
                    },
                )
            };
            match outcome {
                Ok(StepOutcome::Advanced | StepOutcome::Branched) => {
                    if sti_profile.is_some() && old_shadow == Some(crate::StiShadow::Blocking) {
                        state.sti_shadow = Some(crate::StiShadow::Clear);
                    }
                    retired += 1;
                    if state.activity == Some(crate::CpuActivity::Halted) {
                        return RunResult {
                            exit: RunExit::Halted,
                            instructions_executed: retired,
                            rflags_defined,
                        };
                    }
                    None
                }
                Ok(StepOutcome::Halted) => Some(RunExit::Halted),
                Ok(StepOutcome::Fault(fault)) => Some(RunExit::Fault(fault)),
                Ok(StepOutcome::RepIterationBudgetExhausted) => {
                    Some(RunExit::RepIterationBudgetExhausted)
                }
                Ok(StepOutcome::StopRequested) => Some(RunExit::StopRequested),
                Ok(StepOutcome::Unsupported { opcode }) => Some(RunExit::Unsupported { opcode }),
                Err(error) => Some(RunExit::MemoryError(error)),
            }
        };
        if let Some(exit) = exit {
            return RunResult {
                exit,
                instructions_executed: retired,
                rflags_defined,
            };
        }
    }
}

pub fn step(
    state: &mut LongModeState,
    memory: &mut impl GuestMemory,
    context: AccessContext,
) -> Result<StepOutcome, MemoryError> {
    let mut rflags_defined = crate::INTEGER_FLAGS;
    step_tracked(state, memory, context, &mut rflags_defined)
}

