/// Execute one instruction with an explicitly selected CPUID profile. The
/// legacy [`step`] entry point remains closed to CPUID.
pub fn step_with_cpuid_profile(
    state: &mut LongModeState,
    memory: &mut impl GuestMemory,
    context: AccessContext,
    profile: &CpuidProfile,
) -> Result<StepOutcome, MemoryError> {
    let mut rflags_defined = crate::INTEGER_FLAGS;
    step_tracked_with_cpuid_profile(
        state,
        memory,
        context,
        &mut rflags_defined,
        Some(profile),
        &mut || false,
    )
}

/// Execute one instruction with an explicitly selected MSR probe policy.
/// CPUID remains fail closed through this entry point.
pub fn step_with_msr_profile(
    state: &mut LongModeState,
    memory: &mut impl GuestMemory,
    context: AccessContext,
    profile: &MsrProfile,
) -> Result<StepOutcome, MemoryError> {
    let mut rflags_defined = crate::INTEGER_FLAGS;
    step_tracked_with_profiles(
        state,
        memory,
        context,
        &mut rflags_defined,
        None,
        Some(profile),
        None,
        None,
        None,
        None,
        false,
        &mut || false,
    )
}

/// Execute one instruction with an explicitly selected local SEP policy.
/// Legacy [`step`] remains closed to SYSENTER/SYSEXIT policy decisions.
pub fn step_with_sep_profile(
    state: &mut LongModeState,
    memory: &mut impl GuestMemory,
    context: AccessContext,
    profile: &SepProfile,
) -> Result<StepOutcome, MemoryError> {
    let mut rflags_defined = crate::INTEGER_FLAGS;
    step_tracked_with_profiles(
        state,
        memory,
        context,
        &mut rflags_defined,
        None,
        None,
        Some(profile),
        None,
        None,
        None,
        false,
        &mut || false,
    )
}

/// Execute one instruction with the explicit exact SWAPGS profile.
pub fn step_with_swapgs_profile(
    state: &mut LongModeState,
    memory: &mut impl GuestMemory,
    context: AccessContext,
    profile: &SwapgsProfile,
) -> Result<StepOutcome, MemoryError> {
    let mut rflags_defined = crate::INTEGER_FLAGS;
    step_tracked_with_profiles_and_rdtsc(
        state,
        memory,
        context,
        &mut rflags_defined,
        None,
        None,
        None,
        None,
        None,
        None,
        false,
        None,
        None,
        Some(profile),
        None,
        None,
        None,
        None,
        false,
        &mut || false,
    )
}

/// Execute one instruction with the explicit exact Long64 bare-HLT profile.
/// The caller certifies the same bounded machine assumptions as
/// [`run_with_halt_profile`].
pub fn step_with_halt_profile(
    state: &mut LongModeState,
    memory: &mut impl GuestMemory,
    context: AccessContext,
    profile: &crate::HaltProfile,
) -> Result<StepOutcome, MemoryError> {
    let mut rflags_defined = crate::INTEGER_FLAGS;
    step_tracked_with_profiles_and_rdtsc(
        state,
        memory,
        context,
        &mut rflags_defined,
        None,
        None,
        None,
        None,
        None,
        None,
        false,
        None,
        None,
        None,
        None,
        None,
        Some(profile),
        None,
        true,
        &mut || false,
    )
}

fn step_tracked(
    state: &mut LongModeState,
    memory: &mut impl GuestMemory,
    context: AccessContext,
    rflags_defined: &mut u64,
) -> Result<StepOutcome, MemoryError> {
    step_tracked_with_stop(state, memory, context, rflags_defined, &mut || false)
}

