/// Execute the bounded canonical Long64 register-register COMISS/UCOMISS profile.

fn cmpss_binary32_predicate(lhs: u32, rhs: u32, predicate: u8) -> (bool, bool, bool) {
    let classify = |bits: u32| -> u8 {
        let exponent = (bits >> 23) & 0xff;
        let fraction = bits & 0x007f_ffff;
        if exponent == 0xff && fraction != 0 {
            if fraction & (1 << 22) != 0 { 3 } else { 4 }
        } else if exponent == 0 && fraction != 0 {
            2
        } else {
            0
        }
    };
    let lhs_class = classify(lhs);
    let rhs_class = classify(rhs);
    let has_nan = matches!(lhs_class, 3 | 4) || matches!(rhs_class, 3 | 4);
    let signaling = matches!(predicate, 1 | 2 | 5 | 6);
    let new_ie =
        lhs_class == 4 || rhs_class == 4 || (signaling && (lhs_class == 3 || rhs_class == 3));
    // Rev. 093 §4.9.2 gives NaN handling precedence over denormal for CMPSS.
    let new_de = !has_nan && (lhs_class == 2 || rhs_class == 2);
    let ordering = if lhs & 0x7fff_ffff == 0 && rhs & 0x7fff_ffff == 0 {
        core::cmp::Ordering::Equal
    } else if lhs >> 31 != rhs >> 31 {
        if lhs >> 31 != 0 {
            core::cmp::Ordering::Less
        } else {
            core::cmp::Ordering::Greater
        }
    } else if lhs >> 31 == 0 {
        (lhs & 0x7fff_ffff).cmp(&(rhs & 0x7fff_ffff))
    } else {
        (rhs & 0x7fff_ffff).cmp(&(lhs & 0x7fff_ffff))
    };
    let result = match predicate {
        0 => !has_nan && ordering == core::cmp::Ordering::Equal,
        1 => !has_nan && ordering == core::cmp::Ordering::Less,
        2 => {
            !has_nan
                && matches!(
                    ordering,
                    core::cmp::Ordering::Less | core::cmp::Ordering::Equal
                )
        }
        3 => has_nan,
        4 => has_nan || ordering != core::cmp::Ordering::Equal,
        5 => has_nan || ordering != core::cmp::Ordering::Less,
        6 => has_nan || ordering == core::cmp::Ordering::Greater,
        7 => !has_nan,
        _ => unreachable!("CMPSS predicate was prevalidated"),
    };
    (result, new_ie, new_de)
}

fn cmpsd_binary64_predicate(lhs: u64, rhs: u64, predicate: u8) -> (bool, bool, bool) {
    let classify = |bits: u64| -> u8 {
        let exponent = (bits >> 52) & 0x7ff;
        let fraction = bits & 0x000f_ffff_ffff_ffff;
        if exponent == 0x7ff && fraction != 0 {
            if fraction & (1 << 51) != 0 { 2 } else { 3 }
        } else if exponent == 0 && fraction != 0 {
            1
        } else {
            0
        }
    };
    let lhs_class = classify(lhs);
    let rhs_class = classify(rhs);
    let has_nan = matches!(lhs_class, 2 | 3) || matches!(rhs_class, 2 | 3);
    let signaling = matches!(predicate, 1 | 2 | 5 | 6);
    let new_ie =
        lhs_class == 3 || rhs_class == 3 || (signaling && (lhs_class == 2 || rhs_class == 2));
    // Rev. 093 §4.9.2 gives NaN handling precedence over denormal for CMPSD.
    let new_de = !has_nan && (lhs_class == 1 || rhs_class == 1);
    let ordering = if lhs & 0x7fff_ffff_ffff_ffff == 0 && rhs & 0x7fff_ffff_ffff_ffff == 0 {
        core::cmp::Ordering::Equal
    } else if lhs >> 63 != rhs >> 63 {
        if lhs >> 63 != 0 {
            core::cmp::Ordering::Less
        } else {
            core::cmp::Ordering::Greater
        }
    } else if lhs >> 63 == 0 {
        (lhs & 0x7fff_ffff_ffff_ffff).cmp(&(rhs & 0x7fff_ffff_ffff_ffff))
    } else {
        (rhs & 0x7fff_ffff_ffff_ffff).cmp(&(lhs & 0x7fff_ffff_ffff_ffff))
    };
    let result = match predicate {
        0 => !has_nan && ordering == core::cmp::Ordering::Equal,
        1 => !has_nan && ordering == core::cmp::Ordering::Less,
        2 => {
            !has_nan
                && matches!(
                    ordering,
                    core::cmp::Ordering::Less | core::cmp::Ordering::Equal
                )
        }
        3 => has_nan,
        4 => has_nan || ordering != core::cmp::Ordering::Equal,
        5 => has_nan || ordering != core::cmp::Ordering::Less,
        6 => has_nan || ordering == core::cmp::Ordering::Greater,
        7 => !has_nan,
        _ => false,
    };
    (result, new_ie, new_de)
}

fn cmppd_binary64_lanes(lhs: &[u8; 16], rhs: &[u8; 16], predicate: u8) -> ([u8; 16], bool, bool) {
    let classify = |bits: u64| -> u8 {
        let exponent = (bits >> 52) & 0x7ff;
        let fraction = bits & 0x000f_ffff_ffff_ffff;
        if exponent == 0x7ff && fraction != 0 {
            if fraction & (1u64 << 51) != 0 { 3 } else { 4 }
        } else if exponent == 0 && fraction != 0 {
            2
        } else {
            0
        }
    };
    let mut results = [0u8; 16];
    let mut new_ie = false;
    let mut new_de = false;
    for lane in 0..2 {
        let offset = lane * 8;
        let left = u64::from_le_bytes(lhs[offset..offset + 8].try_into().expect("lane qword"));
        let right = u64::from_le_bytes(rhs[offset..offset + 8].try_into().expect("lane qword"));
        let left_class = classify(left);
        let right_class = classify(right);
        let has_nan = matches!(left_class, 3 | 4) || matches!(right_class, 3 | 4);
        let signaling = matches!(predicate, 1 | 2 | 5 | 6);
        new_ie |= left_class == 4
            || right_class == 4
            || (signaling && (left_class == 3 || right_class == 3));
        // Packed lanes accumulate exceptions independently: a NaN in one lane
        // does not suppress a denormal operand in the other lane.
        new_de |= !has_nan && (left_class == 2 || right_class == 2);
        let ordering = if left & 0x7fff_ffff_ffff_ffff == 0 && right & 0x7fff_ffff_ffff_ffff == 0 {
            core::cmp::Ordering::Equal
        } else if left >> 63 != right >> 63 {
            if left >> 63 != 0 {
                core::cmp::Ordering::Less
            } else {
                core::cmp::Ordering::Greater
            }
        } else if left >> 63 == 0 {
            (left & 0x7fff_ffff_ffff_ffff).cmp(&(right & 0x7fff_ffff_ffff_ffff))
        } else {
            (right & 0x7fff_ffff_ffff_ffff).cmp(&(left & 0x7fff_ffff_ffff_ffff))
        };
        let result = match predicate {
            0 => !has_nan && ordering == core::cmp::Ordering::Equal,
            1 => !has_nan && ordering == core::cmp::Ordering::Less,
            2 => {
                !has_nan
                    && matches!(
                        ordering,
                        core::cmp::Ordering::Less | core::cmp::Ordering::Equal
                    )
            }
            3 => has_nan,
            4 => has_nan || ordering != core::cmp::Ordering::Equal,
            5 => has_nan || ordering != core::cmp::Ordering::Less,
            6 => has_nan || ordering == core::cmp::Ordering::Greater,
            7 => !has_nan,
            _ => unreachable!("CMPPD predicate was prevalidated"),
        };
        results[offset..offset + 8].fill(if result { 0xff } else { 0 });
    }
    (results, new_ie, new_de)
}

