        let old_top = x87.top();
        let new_top = old_top.wrapping_add(7) & 7;
        x87.registers[destination] = raw;
        x87.set_tag(destination as u8, tag);
        x87.status_word = (x87.status_word & !((7 << 11) | (1 << 9))) | (u16::from(new_top) << 11);
