                let any_denormal = lane_denormal.into_iter().any(|flag| flag);
                let unmasked_invalid = any_invalid && old_mxcsr & (1 << 7) == 0;
                let unmasked_denormal = any_denormal && old_mxcsr & (1 << 8) == 0;
