                    let controls = configured_minpd_controls.expect("MINPD controls selected");
                    return Ok(StepOutcome::Fault(ArchitecturalFault {
                        vector: if controls.cr4_osxmmexcpt { 19 } else { 6 },
                        error_code: None,
                        linear_address: None,
                    }));
