            let address = state.gpr[Register::Rax as usize];
            let Some(last) = address.checked_add(7) else {
                return Ok(StepOutcome::Fault(ArchitecturalFault {
                    vector: 13,
                    error_code: Some(0),
                    linear_address: None,
                }));
            };
