    #[test]
    fn mov_gs_ax_checks_type_privilege_presence_and_accessed_in_order() {
        for (access, vector, error_code) in [
            (0x02, 13, 0x08), // system descriptor, even though not present
            (0x18, 13, 0x08), // execute-only code, even though not present
            (0x52, 13, 0x08), // CPL3/RPL3 exceeds DPL2, even though not present
            (0x93, 13, 0x08), // CPL3/RPL0 still exceeds DPL0
            (0x73, 11, 0x08), // otherwise valid, not present
        ] {
            let mut state = gs_load_state(0x0b, 15);
            let before = state.clone();
            let mut memory = Memory::new(&[0x8e, 0xe8]);
            memory.bytes[8..16].copy_from_slice(&gs_descriptor(0x1000, 0xffff, access, 0));
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Fault(ArchitecturalFault {
                    vector,
                    error_code: Some(error_code),
                    linear_address: None,
                }))
            );
            assert_eq!(state, before);
            assert_eq!(memory.accesses, vec![(AccessKind::Read, 0x1008, 8)]);
        }
    }

    #[test]
    fn mov_gs_ax_bounds_and_unsupported_selectors_do_not_read_or_commit() {
        let mut short = gs_load_state(0x0b, 14);
        let before = short.clone();
        let mut memory = Memory::new(&[0x8e, 0xe8]);
        assert_eq!(
            step(&mut short, &mut memory, AccessContext::default()),
            Ok(StepOutcome::Fault(ArchitecturalFault {
                vector: 13,
                error_code: Some(8),
                linear_address: None,
            }))
        );
        assert_eq!(short, before);
        assert!(memory.accesses.is_empty());

        let mut truncated = gs_load_state(0x0b, 15);
        let before = truncated.clone();
        let mut truncated_memory = Memory::new(&[0x8e]);
        assert_eq!(
            step(
                &mut truncated,
                &mut truncated_memory,
                AccessContext::default()
            ),
            Err(MemoryError::Unmapped {
                address: 1,
                access: AccessKind::Fetch,
            })
        );
        assert_eq!(truncated, before);

        for (selector, context) in [
            (0x03, AccessContext::default()), // null selector
            (0x0c, AccessContext::default()), // LDT selector
            (
                0x0b,
                AccessContext {
                    privilege: PrivilegeLevel::Ring2,
                    ..AccessContext::default()
                },
            ),
        ] {
            let mut state = gs_load_state(selector, 15);
            let before = state.clone();
            let mut memory = Memory::new(&[0x8e, 0xe8]);
            assert_eq!(
                step(&mut state, &mut memory, context),
                Ok(StepOutcome::Unsupported { opcode: 0x8e })
            );
            assert_eq!(state, before);
            assert!(memory.accesses.is_empty());
        }

        for missing in ["gdtr", "gs_cache"] {
            let mut state = gs_load_state(0x0b, 15);
            if missing == "gdtr" {
                state.gdtr = None;
            } else {
                state.gs_cache = None;
            }
            let before = state.clone();
            let mut memory = Memory::new(&[0x8e, 0xe8]);
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { opcode: 0x8e })
            );
            assert_eq!(state, before);
            assert!(memory.accesses.is_empty());
        }
    }

    #[test]
    fn mov_gs_ax_descriptor_fault_propagates_without_state_or_retirement_commit() {
        let fault = MemoryError::Architectural(ArchitecturalFault {
            vector: 14,
            error_code: Some(0),
            linear_address: Some(0x1008),
        });
        let mut state = gs_load_state(0x0b, 15);
        let before = state.clone();
        let mut memory = Memory::new(&[0x8e, 0xe8]);
        memory.error = Some(fault.clone());
        memory.error_kind = Some(AccessKind::Read);
        let result = run(
            &mut state,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: None,
                context: AccessContext::default(),
            },
            || false,
        );
        assert_eq!(result.instructions_executed, 0);
        assert_eq!(
            result.exit,
            RunExit::Fault(match fault {
                MemoryError::Architectural(fault) => fault,
                _ => unreachable!(),
            })
        );
        assert_eq!(state, before);
        assert_eq!(memory.accesses, vec![(AccessKind::Read, 0x1008, 8)]);
    }

    #[test]
    fn fninit_resets_only_x87_environment_and_commits_on_success() {
        let mut state = LongModeState::default();
        state.rip = 0x1000;
        state.gpr = std::array::from_fn(|index| 0x1111_2222_3333_4444u64 ^ index as u64);
        state.rflags = 0xa55a_1234_5678_9abc;
        let mut x87 = crate::state::X87State::fixture_seed();
        // Seed pending and unmasked status/control bits to verify they are
        // cleared without making them an FNINIT exception or delivery path.
        x87.control_word = 0;
        x87.status_word = 0xffff;
        x87.registers = std::array::from_fn(|register| {
            std::array::from_fn(|byte| (register as u8).wrapping_mul(29).wrapping_add(byte as u8))
        });
        let payloads = x87.registers;
        state.x87 = Some(x87);
        let before = state.clone();
        let mut memory = Memory::at(&[0xdb, 0xe3], 0x1000);
        let result = run(
            &mut state,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: Some(0x1002),
                context: AccessContext::default(),
            },
            || false,
        );
        assert_eq!(result.exit, RunExit::StopAddress);
        assert_eq!(result.instructions_executed, 1);
        assert_eq!(state.rip, 0x1002);
        assert_eq!(state.gpr, before.gpr);
        assert_eq!(state.rflags, before.rflags);
        let x87 = state.x87.as_ref().unwrap();
        assert_eq!(x87.registers, payloads);
        assert_eq!(x87.control_word, 0x037f);
        assert_eq!(x87.status_word, 0);
        assert_eq!(x87.tag_word, 0xffff);
        assert_eq!(x87.instruction_pointer, 0);
        assert_eq!(x87.data_pointer, 0);
        assert_eq!(x87.last_opcode, 0);
    }

    fn binary80_normal(significand: u64, exponent: u16, negative: bool) -> [u8; 10] {
        let mut bytes = [0; 10];
        bytes[..8].copy_from_slice(&significand.to_le_bytes());
        let sign_exponent = exponent | if negative { 0x8000 } else { 0 };
        bytes[8..].copy_from_slice(&sign_exponent.to_le_bytes());
        bytes
    }

    #[test]
    fn fsubp_sti_st0_commits_destination_then_pops_for_every_top_and_index() {
        let vectors = [
            // ST(i)=1.5, ST(0)=1 -> +0.5
            (
                0xc000_0000_0000_0000,
                false,
                0x8000_0000_0000_0000,
                false,
                0x8000_0000_0000_0000,
                0x3ffe,
                false,
            ),
            // ST(i)=1, ST(0)=1.5 -> -0.5
            (
                0x8000_0000_0000_0000,
                false,
                0xc000_0000_0000_0000,
                false,
                0x8000_0000_0000_0000,
                0x3ffe,
                true,
            ),
            // Negative permutations and opposite signs.
            (
                0xc000_0000_0000_0000,
                true,
                0x8000_0000_0000_0000,
                true,
                0x8000_0000_0000_0000,
                0x3ffe,
                true,
            ),
            (
                0x8000_0000_0000_0000,
                true,
                0xc000_0000_0000_0000,
                true,
                0x8000_0000_0000_0000,
                0x3ffe,
                false,
            ),
            (
                0x8000_0000_0000_0000,
                false,
                0x8000_0000_0000_0000,
                true,
                0x8000_0000_0000_0000,
                0x4000,
                false,
            ),
            (
                0x8000_0000_0000_0000,
                true,
                0x8000_0000_0000_0000,
                false,
                0x8000_0000_0000_0000,
                0x4000,
                true,
            ),
        ];
        for (dest_sig, dest_neg, src_sig, src_neg, out_sig, out_exp, out_neg) in vectors {
            for top in 0u8..8 {
                for index in 1u8..8 {
                    let old_top = usize::from(top);
                    let physical_destination = usize::from((top + index) & 7);
                    let mut state = LongModeState::default();
                    state.rip = 0x2000;
                    state.gpr = std::array::from_fn(|i| 0x1122_3344_5566_7788 ^ i as u64);
                    state.rflags = 0xa55a_1234_5678_9abc;
                    let mut x87 = crate::state::X87State::fixture_seed();
                    x87.control_word = 0x037f;
                    x87.status_word = (u16::from(top) << 11) | 0x4700;
                    x87.tag_word =
                        u16::MAX & !(3 << (old_top * 2)) & !(3 << (physical_destination * 2));
                    x87.registers = std::array::from_fn(|p| {
                        std::array::from_fn(|b| 0x60u8.wrapping_add((p * 13 + b) as u8))
                    });
                    x87.registers[physical_destination] =
                        binary80_normal(dest_sig, 0x3fff, dest_neg);
                    x87.registers[old_top] = binary80_normal(src_sig, 0x3fff, src_neg);
                    x87.instruction_pointer = 0x0123_4567_89ab_cdef;
                    x87.data_pointer = 0xfedc_ba98_7654_3210;
                    x87.last_opcode = 0x05aa;
                    state.x87 = Some(x87);
                    let before = state.clone();
                    let mut memory = Memory::at(&[0xde, 0xe8 | index], 0x2000);
                    assert_eq!(
                        step(&mut state, &mut memory, AccessContext::default()),
                        Ok(StepOutcome::Advanced),
                        "TOP={top}, i={index}"
                    );
                    assert_eq!(state.rip, 0x2002);
                    assert_eq!(state.gpr, before.gpr);
                    assert_eq!(state.rflags, before.rflags);
                    let after = state.x87.as_ref().unwrap();
                    assert_eq!(
                        after.registers[physical_destination],
                        binary80_normal(out_sig, out_exp, out_neg)
                    );
                    for physical in 0..8 {
                        if physical != physical_destination {
                            assert_eq!(
                                after.registers[physical],
                                before.x87.as_ref().unwrap().registers[physical]
                            );
                        }
                    }
                    let mut expected_tags = before.x87.as_ref().unwrap().tag_word;
                    expected_tags |= 3 << (old_top * 2);
                    assert_eq!(after.tag_word, expected_tags);
                    assert_eq!(after.top(), top.wrapping_add(1) & 7);
                    assert_eq!(
                        after.status_word,
                        (before.x87.as_ref().unwrap().status_word & !((7 << 11) | (1 << 9)))
                            | (u16::from(top.wrapping_add(1) & 7) << 11)
                    );
                    assert_eq!(
                        after.control_word,
                        before.x87.as_ref().unwrap().control_word
                    );
                    assert_eq!(after.instruction_pointer, 0x2000);
                    assert_eq!(
                        after.data_pointer,
                        before.x87.as_ref().unwrap().data_pointer
                    );
                    assert_eq!(after.last_opcode, before.x87.as_ref().unwrap().last_opcode);
                }
            }
        }
    }

    #[test]
    fn fsubp_sti_st0_rounds_all_fcws_and_commits_pop_flags_atomically() {
        const CONTROL_WORDS: [u16; 12] = [
            0x007f, 0x047f, 0x087f, 0x0c7f, 0x027f, 0x067f, 0x0a7f, 0x0e7f, 0x037f, 0x077f, 0x0b7f,
            0x0f7f,
        ];
        for control_word in CONTROL_WORDS {
            for top in 0u8..8 {
                for destination_index in 1u8..8 {
                    for (destination_negative, source_negative) in
                        [(false, false), (false, true), (true, false), (true, true)]
                    {
                        for old_pe in [false, true] {
                            for old_c1 in [false, true] {
                                let physical_top = usize::from(top);
                                let physical_destination =
                                    usize::from((top + destination_index) & 7);
                                let mut state = LongModeState::default();
                                state.rip = 0x6000;
                                state.gpr =
                                    std::array::from_fn(|n| 0x1020_3040_5060_7080 ^ n as u64);
                                state.rflags = 0xa55a_1234_5678_9abc;
                                let mut x87 = crate::state::X87State::fixture_seed();
                                x87.control_word = control_word;
                                x87.status_word = (u16::from(top) << 11)
                                    | 0x4500
                                    | (u16::from(old_pe) << 5)
                                    | (u16::from(old_c1) << 9);
                                x87.tag_word = u16::MAX;
                                x87.registers[physical_destination] = binary80_normal(
                                    0x8000_0000_0000_0000,
                                    0x3fff,
                                    destination_negative,
                                );
                                x87.registers[physical_top] =
                                    binary80_normal(0x8000_0000_0000_0000, 0x3fe6, source_negative);
                                x87.set_tag(physical_destination as u8, X87Tag::Valid);
                                x87.set_tag(top, X87Tag::Valid);
                                state.x87 = Some(x87);
                                let before = state.clone();
                                let (result, inexact, incremented) =
                                    bounded_x87_fsub_sti_st0_result(&before, destination_index)
                                        .expect("bounded FSUBP test operands must be supported");
                                let mut expected = before.clone();
                                let expected_x87 = expected.x87.as_mut().unwrap();
                                expected_x87.registers[physical_destination] = result;
                                expected_x87.set_tag(top, X87Tag::Empty);
                                let new_top = top.wrapping_add(1) & 7;
                                expected_x87.status_word = (expected_x87.status_word
                                    & !((7 << 11) | (1 << 9) | (1 << 5)))
                                    | (u16::from(new_top) << 11)
                                    | (u16::from(old_pe || inexact) << 5)
                                    | (u16::from(incremented) << 9);
                                expected_x87.instruction_pointer = before.rip;
                                expected.rip += 2;

                                let mut memory =
                                    Memory::at(&[0xde, 0xe8 | destination_index], state.rip);
                                assert_eq!(
                                    step(&mut state, &mut memory, AccessContext::default()),
                                    Ok(StepOutcome::Advanced),
                                    "FCW={control_word:#06x}, TOP={top}, i={destination_index}"
                                );
                                assert_eq!(state, expected);
                                assert!(memory.accesses.is_empty());
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn fsubp_sti_st0_rounds_odd_65_bit_coefficient_for_all_fcws_and_stack_pairs() {
        const CONTROL_WORDS: [u16; 12] = [
            0x007f, 0x047f, 0x087f, 0x0c7f, 0x027f, 0x067f, 0x0a7f, 0x0e7f, 0x037f, 0x077f, 0x0b7f,
            0x0f7f,
        ];
        for control_word in CONTROL_WORDS {
            let precision = match control_word & 0x0300 {
                0x0000 => 24,
                0x0200 => 53,
                _ => 64,
            };
            let incremented = (control_word & 0x0c00) == 0x0800;
            let expected_significand = 0x8000_0000_0000_0000
                | if incremented {
                    1u64 << (64 - precision)
                } else {
                    0
                };
            let expected_result = binary80_normal(expected_significand, 0x4000, false);

            for top in 0u8..8 {
                for destination_index in 1u8..8 {
                    for old_pe in [false, true] {
                        for old_c1 in [false, true] {
                            let physical_top = usize::from(top);
                            let physical_destination = usize::from((top + destination_index) & 7);
                            let mut state = LongModeState::default();
                            state.rip = 0x6800;
                            state.gpr = std::array::from_fn(|n| 0x1020_3040_5060_7080 ^ n as u64);
                            state.rflags = 0xa55a_1234_5678_9abc;
                            let mut x87 = crate::state::X87State::fixture_seed();
                            x87.control_word = control_word;
                            x87.status_word = (u16::from(top) << 11)
                                | 0x4500
                                | (u16::from(old_pe) << 5)
                                | (u16::from(old_c1) << 9);
                            x87.tag_word = u16::MAX;
                            x87.registers[physical_destination] =
                                binary80_normal(0x8000_0000_0000_0001, 0x3fff, false);
                            x87.registers[physical_top] =
                                binary80_normal(0x8000_0000_0000_0000, 0x3fff, true);
                            x87.set_tag(physical_destination as u8, X87Tag::Valid);
                            x87.set_tag(top, X87Tag::Valid);
                            state.x87 = Some(x87);
                            let before = state.clone();

                            let mut expected = before.clone();
                            let expected_x87 = expected.x87.as_mut().unwrap();
                            expected_x87.registers[physical_destination] = expected_result;
                            expected_x87.set_tag(top, X87Tag::Empty);
                            let new_top = top.wrapping_add(1) & 7;
                            expected_x87.status_word = (expected_x87.status_word
                                & !((7 << 11) | (1 << 9) | (1 << 5)))
                                | (u16::from(new_top) << 11)
                                | (1 << 5)
                                | (u16::from(incremented) << 9);
                            expected_x87.instruction_pointer = before.rip;
                            expected.rip += 2;

                            let mut memory =
                                Memory::at(&[0xde, 0xe8 | destination_index], state.rip);
                            assert_eq!(
                                step(&mut state, &mut memory, AccessContext::default()),
                                Ok(StepOutcome::Advanced),
                                "FCW={control_word:#06x}, TOP={top}, i={destination_index}"
                            );
                            assert_eq!(state, expected);
                            assert!(memory.accesses.is_empty());
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn fsubp_sti_st0_large_gaps_match_independent_integer_oracle_and_pop_atomically() {
        const CONTROL_WORDS: [u16; 12] = [
            0x007f, 0x047f, 0x087f, 0x0c7f, 0x027f, 0x067f, 0x0a7f, 0x0e7f, 0x037f, 0x077f, 0x0b7f,
            0x0f7f,
        ];

        // For power-of-two operands this oracle is exact signed-magnitude
        // arithmetic followed by integer threshold rounding. It does not call
        // any production binary80 arithmetic or rounding helper.
        for gap in [64u16, 65, 66, 32_765] {
            let high_exponent = if gap == 32_765 { 0x7ffe } else { 0x3fff };
            for control_word in CONTROL_WORDS {
                let precision = match control_word & 0x0300 {
                    0 => 24,
                    0x0200 => 53,
                    _ => 64,
                };
                let rounding = (control_word >> 10) & 3;
                let unit = 1u64 << (64 - precision);
                for high_negative in [false, true] {
                    for opposite_sign in [false, true] {
                        for high_at_destination in [false, true] {
                            let result_negative = if high_at_destination {
                                high_negative
                            } else {
                                !high_negative
                            };
                            let (expected_significand, expected_exponent, inexact, incremented) =
                                if opposite_sign {
                                    // Opposite signs add magnitudes. Nearest
                                    // increments only past the exact half-ulp
                                    // tie; directed modes use the result sign.
                                    let incremented = match rounding {
                                        0 => gap < precision as u16,
                                        1 => result_negative,
                                        2 => !result_negative,
                                        3 => false,
                                        _ => unreachable!(),
                                    };
                                    (
                                        0x8000_0000_0000_0000 + u64::from(incremented) * unit,
                                        high_exponent,
                                        true,
                                        incremented,
                                    )
                                } else if gap == precision as u16 {
                                    // 1 - 2^-p is the exact predecessor on
                                    // the p-bit precision grid.
                                    (0u64.wrapping_sub(unit), high_exponent - 1, false, false)
                                } else {
                                    let round_to_high = match rounding {
                                        0 => gap >= precision as u16 + 1,
                                        1 => result_negative,
                                        2 => !result_negative,
                                        3 => false,
                                        _ => unreachable!(),
                                    };
                                    if round_to_high {
                                        (0x8000_0000_0000_0000, high_exponent, true, true)
                                    } else {
                                        (0u64.wrapping_sub(unit), high_exponent - 1, true, false)
                                    }
                                };
                            let expected_result = binary80_normal(
                                expected_significand,
                                expected_exponent,
                                result_negative,
                            );
                            let low_negative = high_negative ^ opposite_sign;
                            let high = binary80_normal(1u64 << 63, high_exponent, high_negative);
                            let low =
                                binary80_normal(1u64 << 63, high_exponent - gap, low_negative);

                            for top in 0u8..8 {
                                for destination_index in 1u8..8 {
                                    for old_pe in [false, true] {
                                        for old_c1 in [false, true] {
                                            let physical_top = usize::from(top);
                                            let physical_destination =
                                                usize::from((top + destination_index) & 7);
                                            let mut state = LongModeState::default();
                                            state.rip = 0x6100;
                                            state.gpr = std::array::from_fn(|n| {
                                                0x1122_3344_5566_7788 ^ n as u64
                                            });
                                            state.rflags = 0xa55a_1234_5678_9abc;
                                            let mut x87 = crate::state::X87State::fixture_seed();
                                            x87.control_word = control_word;
                                            x87.status_word = (u16::from(top) << 11)
                                                | 0x4500
                                                | (u16::from(old_pe) << 5)
                                                | (u16::from(old_c1) << 9);
                                            x87.tag_word = u16::MAX;
                                            x87.registers = std::array::from_fn(|p| {
                                                std::array::from_fn(|b| {
                                                    0x30u8.wrapping_add((p * 11 + b) as u8)
                                                })
                                            });
                                            x87.registers[physical_destination] =
                                                if high_at_destination { high } else { low };
                                            x87.registers[physical_top] =
                                                if high_at_destination { low } else { high };
                                            x87.set_tag(top, X87Tag::Valid);
                                            x87.set_tag(physical_destination as u8, X87Tag::Valid);
                                            x87.instruction_pointer = 0x0123_4567_89ab_cdef;
                                            x87.data_pointer = 0xfedc_ba98_7654_3210;
                                            x87.last_opcode = 0x05aa;
                                            state.x87 = Some(x87);
                                            let before = state.clone();
                                            let mut memory = Memory::at(
                                                &[0xde, 0xe8 | destination_index],
                                                state.rip,
                                            );
                                            assert_eq!(
                                                step(
                                                    &mut state,
                                                    &mut memory,
                                                    AccessContext::default(),
                                                ),
                                                Ok(StepOutcome::Advanced),
                                                "gap={gap}, FCW={control_word:#06x}, TOP={top}, i={destination_index}, signs={high_negative}/{opposite_sign}, high_at_destination={high_at_destination}"
                                            );

                                            let mut expected = before;
                                            let expected_x87 = expected.x87.as_mut().unwrap();
                                            expected_x87.registers[physical_destination] =
                                                expected_result;
                                            expected_x87.set_tag(top, X87Tag::Empty);
                                            expected_x87.status_word = (expected_x87.status_word
                                                & !((7 << 11) | (1 << 5) | (1 << 9)))
                                                | (u16::from(top.wrapping_add(1) & 7) << 11)
                                                | (u16::from(old_pe || inexact) << 5)
                                                | (u16::from(incremented) << 9);
                                            expected_x87.instruction_pointer = expected.rip;
                                            expected.rip += 2;
                                            assert_eq!(state, expected);
                                            assert!(memory.accesses.is_empty());
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn fsubp_commits_boundary_results_before_pop() {
        let vectors = [
            // (DEST, SRC, expected): +2^-63 and -2^-63.
            (
                binary80_normal(0x8000_0000_0000_0001, 0x3fff, false),
                binary80_normal(0x8000_0000_0000_0000, 0x3fff, false),
                binary80_normal(0x8000_0000_0000_0000, 0x3fc0, false),
            ),
            (
                binary80_normal(0x8000_0000_0000_0000, 0x3fff, false),
                binary80_normal(0x8000_0000_0000_0001, 0x3fff, false),
                binary80_normal(0x8000_0000_0000_0000, 0x3fc0, true),
            ),
            // Maximum even 65-bit coefficient carries to the next exponent.
            (
                binary80_normal(u64::MAX, 0x3fff, false),
                binary80_normal(u64::MAX, 0x3fff, true),
                binary80_normal(u64::MAX, 0x4000, false),
            ),
            // 3 minimum-normal units minus 2 yields minimum Normal.
            (
                binary80_normal(0xc000_0000_0000_0000, 0x0002, false),
                binary80_normal(0x8000_0000_0000_0000, 0x0002, false),
                binary80_normal(0x8000_0000_0000_0000, 0x0001, false),
            ),
            // The normalized exponent gap is exactly 64 and stays in-profile.
            (
                binary80_normal(0x8000_0000_0000_0000, 0x3fff, false),
                binary80_normal(0x8000_0000_0000_0000, 0x3fbf, false),
                binary80_normal(u64::MAX, 0x3ffe, false),
            ),
        ];
        for (destination_value, source_value, expected) in vectors {
            let mut state = LongModeState::default();
            state.rip = 0x2800;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = (5 << 11) | (1 << 9);
            x87.tag_word = u16::MAX & !(3 << (5 * 2)) & !(3 << (6 * 2));
            x87.registers[5] = source_value;
            x87.registers[6] = destination_value;
            state.x87 = Some(x87);
            let mut memory = Memory::at(&[0xde, 0xe9], 0x2800);
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Advanced)
            );
            let after = state.x87.as_ref().unwrap();
            assert_eq!(after.registers[6], expected);
            assert_eq!(after.top(), 6);
            assert_eq!(after.tag_word & (3 << (5 * 2)), 3 << (5 * 2));
            assert_eq!(after.status_word & (1 << 9), 0);
            assert_eq!(after.instruction_pointer, 0x2800);
            assert_eq!(state.rip, 0x2802);
        }
    }

    #[test]
    fn fsubp_alias_and_exact_rejections_are_atomic_for_all_tops() {
        const CONTROL_WORDS: [u16; 12] = [
            0x007f, 0x047f, 0x087f, 0x0c7f, 0x027f, 0x067f, 0x0a7f, 0x0e7f, 0x037f, 0x077f, 0x0b7f,
            0x0f7f,
        ];
        for control_word in CONTROL_WORDS {
            for top in 0u8..8 {
                let mut alias = LongModeState::default();
                alias.rip = 0x3000;
                let mut x87 = crate::state::X87State::fixture_seed();
                x87.control_word = control_word;
                x87.status_word = (u16::from(top) << 11) | 0x0200;
                x87.tag_word = u16::MAX & !(3 << (usize::from(top) * 2));
                x87.registers[usize::from(top)] =
                    binary80_normal(0x8000_0000_0000_0000, 0x3fff, false);
                alias.x87 = Some(x87);
                let before = alias.clone();
                let mut memory = Memory::at(&[0xde, 0xe8], 0x3000);
                assert_eq!(
                    step(&mut alias, &mut memory, AccessContext::default()),
                    Ok(StepOutcome::Unsupported { opcode: 0xde })
                );
                assert_eq!(alias, before, "alias FCW={control_word:#06x}, TOP={top}");
            }
        }

        let one = binary80_normal(0x8000_0000_0000_0000, 0x3fff, false);
        let make_x87 = || {
            let mut x = crate::state::X87State::fixture_seed();
            x.control_word = 0x037f;
            x.status_word = 0;
            x.tag_word = 0;
            x.registers[0] = one;
            x.registers[1] = one;
            x
        };
        let mut rejects = Vec::new();
        let mut bad = make_x87();
        bad.control_word = 0x017f;
        rejects.push(bad);
        for sw in [1, 0x8000] {
            let mut bad = make_x87();
            bad.status_word = sw;
            rejects.push(bad);
        }
        for slot in [0, 1] {
            let mut bad = make_x87();
            bad.tag_word = 3 << (slot * 2);
            rejects.push(bad);
        }
        for raw in [
            binary80_normal(0, 0, false),
            binary80_normal(1, 0, false),
            binary80_normal(0x8000_0000_0000_0000, 0, false),
            binary80_normal(0, 1, false),
            binary80_normal(0x8000_0000_0000_0000, 0x7fff, false),
            binary80_normal(0xc000_0000_0000_0000, 0x7fff, false),
            binary80_normal(0x8000_0000_0000_0001, 0x7fff, false),
            binary80_normal(0, 0x7fff, false),
            binary80_normal(0x4000_0000_0000_0000, 0x7fff, false),
            binary80_normal(1, 0x7fff, false),
            binary80_normal(0x4000_0000_0000_0000, 1, false),
        ] {
            let mut d = make_x87();
            d.registers[1] = raw;
            rejects.push(d);
            let mut s = make_x87();
            s.registers[0] = raw;
            rejects.push(s);
        }
        let mut cancel = make_x87();
        cancel.registers[1] = one;
        rejects.push(cancel);
        // The former exact-only odd 65-bit coefficient refusal now rounds;
        // see the explicit accepted-case matrix above.
        let mut subnormal = make_x87();
        subnormal.registers[1] = binary80_normal(0x8000_0000_0000_0001, 1, false);
        subnormal.registers[0] = binary80_normal(0x8000_0000_0000_0000, 1, false);
        rejects.push(subnormal);
        let mut overflow = make_x87();
        overflow.registers[1] = binary80_normal(u64::MAX, 0x7ffe, false);
        overflow.registers[0] = binary80_normal(u64::MAX, 0x7ffe, true);
        rejects.push(overflow);
        for (reject_index, x87) in rejects.into_iter().enumerate() {
            let mut state = LongModeState::default();
            state.rip = 0x4000;
            state.gpr = [0x0123_4567_89ab_cdef; 16];
            state.rflags = 0xa55a_1234_5678_9abc;
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(&[0xde, 0xe9], 0x4000);
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { opcode: 0xde }),
                "rejection case {reject_index}"
            );
            assert_eq!(state, before);
        }
        let mut missing = LongModeState::default();
        missing.rip = 0x4000;
        let before = missing.clone();
        let mut memory = Memory::at(&[0xde, 0xe9], 0x4000);
        assert_eq!(
            step(&mut missing, &mut memory, AccessContext::default()),
            Ok(StepOutcome::Unsupported { opcode: 0xde })
        );
        assert_eq!(missing, before);
    }

    #[test]
    fn fsubp_large_gap_helper_refusal_cannot_fall_back_to_exact_commit() {
        let mut state = LongModeState::default();
        state.rip = 0x4f00;
        let mut x87 = crate::state::X87State::fixture_seed();
        x87.control_word = 0x037f;
        x87.status_word = 0;
        x87.instruction_selector = Some(0); // rejected by the precision profile
        x87.tag_word = u16::MAX;
        x87.registers[0] = binary80_normal(1u64 << 63, 0x3fff, false);
        x87.registers[1] = binary80_normal(1u64 << 63, 0x3fff - 65, false);
        x87.set_tag(0, X87Tag::Valid);
        x87.set_tag(1, X87Tag::Valid);
        state.x87 = Some(x87);
        let before = state.clone();
        let mut memory = Memory::at(&[0xde, 0xe9], state.rip);

        assert!(bounded_x87_fsubp_sti_st0_large_gap_result(&state, 1).is_none());
        assert!(exact_fsubp_fallback_result(&state, 1).is_none());
        assert_eq!(
            step(&mut state, &mut memory, AccessContext::default()),
            Ok(StepOutcome::Unsupported { opcode: 0xde })
        );
        assert_eq!(state, before);
        assert!(memory.accesses.is_empty());
    }

    #[test]
    fn fsubp_fetch_fault_stop_and_zero_budget_do_not_commit() {
        let mut state = LongModeState::default();
        state.rip = 0x5000;
        let mut x = crate::state::X87State::fixture_seed();
        x.control_word = 0x037f;
        x.status_word = 0x0200;
        x.tag_word = 0;
        x.registers[0] = binary80_normal(0x8000_0000_0000_0000, 0x3fff, false);
        x.registers[1] = binary80_normal(0xc000_0000_0000_0000, 0x3fff, false);
        state.x87 = Some(x);
        for (bytes, stop, budget) in [
            (&[0xde][..], None, 1),
            (&[0xde, 0xe9][..], Some(0x5000), 1),
            (&[0xde, 0xe9][..], None, 0),
        ] {
            let mut current = state.clone();
            let before = current.clone();
            let mut memory = Memory::at(bytes, 0x5000);
            let result = run(
                &mut current,
                &mut memory,
                RunConfig {
                    instruction_budget: budget,
                    stop_rip: stop,
                    context: AccessContext::default(),
                },
                || false,
            );
            assert_eq!(result.instructions_executed, 0);
            assert_eq!(current, before);
            if bytes.len() == 1 {
                assert!(matches!(result.exit, RunExit::MemoryError(_)));
            } else if stop.is_some() {
                assert_eq!(result.exit, RunExit::StopAddress);
            } else {
                assert_eq!(result.exit, RunExit::InstructionBudgetExhausted);
            }
        }
    }

    #[test]
    fn fadd_st0_st1_commits_exact_normal_sum_and_only_defined_state() {
        for (top, source_index, lhs, rhs, expected) in [
            (
                0,
                1,
                binary80_normal(0x8000_0000_0000_0000, 0x3fff, false),
                binary80_normal(0x8000_0000_0000_0000, 0x3fff, false),
                binary80_normal(0x8000_0000_0000_0000, 0x4000, false),
            ),
            (
                0,
                1,
                binary80_normal(0x8000_0000_0000_0000, 0x3fff, true),
                binary80_normal(0x8000_0000_0000_0000, 0x3fff, true),
                binary80_normal(0x8000_0000_0000_0000, 0x4000, true),
            ),
            (
                0,
                1,
                binary80_normal(0xc000_0000_0000_0000, 0x3fff, false),
                binary80_normal(0x8000_0000_0000_0000, 0x3fff, true),
                binary80_normal(0x8000_0000_0000_0000, 0x3ffe, false),
            ),
            // TOP=7, i=1 wraps the logical source to physical register 0.
            (
                7,
                1,
                binary80_normal(0xc000_0000_0000_0000, 0x3fff, false),
                binary80_normal(0xc000_0000_0000_0000, 0x3fff, false),
                binary80_normal(0xc000_0000_0000_0000, 0x4000, false),
            ),
            (
                0,
                1,
                binary80_normal(u64::MAX, 0x3fff, false),
                binary80_normal(u64::MAX, 0x3fff, false),
                binary80_normal(u64::MAX, 0x4000, false),
            ),
            (
                3,
                0,
                binary80_normal(0xc000_0000_0000_0001, 0x4000, true),
                binary80_normal(0xc000_0000_0000_0001, 0x4000, true),
                binary80_normal(0xc000_0000_0000_0001, 0x4001, true),
            ),
            // TOP=7, i=7 wraps to physical register 6; only i=0 aliases TOP.
            (
                7,
                7,
                binary80_normal(u64::MAX, 0x3fff, false),
                binary80_normal(u64::MAX, 0x3fff, false),
                binary80_normal(u64::MAX, 0x4000, false),
            ),
            (
                4,
                2,
                binary80_normal(0x8000_0000_0000_0000, 0x4001, false),
                binary80_normal(0x8000_0000_0000_0000, 0x4001, false),
                binary80_normal(0x8000_0000_0000_0000, 0x4002, false),
            ),
            (
                5,
                3,
                binary80_normal(0x8000_0000_0000_0000, 0x3fff, true),
                binary80_normal(0x8000_0000_0000_0000, 0x3fff, true),
                binary80_normal(0x8000_0000_0000_0000, 0x4000, true),
            ),
            (
                6,
                4,
                binary80_normal(0xc000_0000_0000_0000, 0x3fff, false),
                binary80_normal(0xc000_0000_0000_0000, 0x3fff, false),
                binary80_normal(0xc000_0000_0000_0000, 0x4000, false),
            ),
            (
                2,
                5,
                binary80_normal(0xa000_0000_0000_0000, 0x4000, false),
                binary80_normal(0xa000_0000_0000_0000, 0x4000, false),
                binary80_normal(0xa000_0000_0000_0000, 0x4001, false),
            ),
            (
                1,
                6,
                binary80_normal(0xe000_0000_0000_0000, 0x3ffe, true),
                binary80_normal(0xe000_0000_0000_0000, 0x3ffe, true),
                binary80_normal(0xe000_0000_0000_0000, 0x3fff, true),
            ),
        ] {
            let mut state = LongModeState::default();
            state.rip = 0x1000;
            state.gpr = std::array::from_fn(|index| 0xa1b2_c3d4_e5f6_0718 ^ index as u64);
            state.rflags = 0xa55a_1234_5678_9abc;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = (u16::from(top) << 11) | 0x4700 | 0x0200;
            // The alias form needs only its one used physical register to be Valid.
            x87.tag_word = if source_index == 0 {
                u16::MAX & !(3 << (top * 2))
            } else {
                0
            };
            x87.instruction_pointer = 0x0123_4567_89ab_cdef;
            x87.data_pointer = 0xfedc_ba98_7654_3210;
            x87.last_opcode = 0x05aa;
            let destination = usize::from(top);
            let source = usize::from((top + source_index) & 7);
            x87.registers[destination] = lhs;
            x87.registers[source] = rhs;
            state.x87 = Some(x87.clone());
            let before = state.clone();
            let mut memory = Memory::at(&[0xd8, 0xc0 | source_index], 0x1000);
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Advanced)
            );
            assert_eq!(state.rip, 0x1002);
            assert_eq!(state.gpr, before.gpr);
            assert_eq!(state.rflags, before.rflags);
            let result = state.x87.as_ref().unwrap();
            assert_eq!(result.registers[destination], expected);
            for index in 0..8 {
                if index != destination {
                    assert_eq!(
                        result.registers[index],
                        before.x87.as_ref().unwrap().registers[index]
                    );
                }
            }
            assert_eq!(result.control_word, 0x037f);
            assert_eq!(result.tag_word, before.x87.as_ref().unwrap().tag_word);
            assert_eq!(result.top(), top);
            assert_eq!(
                result.status_word,
                before.x87.as_ref().unwrap().status_word & !(1 << 9)
            );
            assert_eq!(result.status_word & 0x4500, 0x4500);
            assert_eq!(result.instruction_pointer, 0x1000);
            assert_eq!(
                result.data_pointer,
                before.x87.as_ref().unwrap().data_pointer
            );
            assert_eq!(result.last_opcode, before.x87.as_ref().unwrap().last_opcode);
        }
    }

    #[test]
    fn fadd_st0_st1_rejects_unsupported_inputs_without_any_state_commit() {
        let normal = binary80_normal(0x8000_0000_0000_0000, 0x3fff, false);
        let mut absent = LongModeState::default();
        let before = absent.clone();
        let mut memory = Memory::at(&[0xd8, 0xc1], 0);
        assert_eq!(
            step(&mut absent, &mut memory, AccessContext::default()),
            Ok(StepOutcome::Unsupported { opcode: 0xd8 })
        );
        assert_eq!(absent, before);

        let mut cases = Vec::new();
        let mut add_case = |mut change: Box<dyn FnMut(&mut crate::state::X87State)>| {
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = 0x0020; // A clean FSW boundary keeps the arithmetic cases meaningful.
            x87.tag_word = 0;
            x87.registers[0] = normal;
            x87.registers[1] = normal;
            change(&mut x87);
            cases.push(x87);
        };
        add_case(Box::new(|x| {
            x.registers[1] = binary80_normal(0x8000_0000_0000_0000, 0x3fff, true)
        }));
        add_case(Box::new(|x| {
            x.registers[1] = binary80_normal(0x8000_0000_0000_0000, 0x7fff, false)
        }));
        add_case(Box::new(|x| {
            x.registers[1] = binary80_normal(0x8000_0000_0000_0000, 0, false)
        }));
        add_case(Box::new(|x| x.registers[1] = [0; 10]));
        add_case(Box::new(|x| x.registers[1] = binary80_normal(1, 0, false)));
        add_case(Box::new(|x| x.registers[1] = binary80_normal(0, 1, false)));
        add_case(Box::new(|x| x.tag_word = 3));
        add_case(Box::new(|x| x.tag_word = 2));
        add_case(Box::new(|x| x.control_word = 0x017f));
        add_case(Box::new(|x| x.status_word = 1));
        add_case(Box::new(|x| x.status_word = 0x8000));
        add_case(Box::new(|x| {
            x.registers[0] = binary80_normal(0x8000_0000_0000_0001, 1, false);
            x.registers[1] = binary80_normal(0x8000_0000_0000_0000, 1, true);
        }));
        add_case(Box::new(|x| {
            x.registers[0] = binary80_normal(u64::MAX, 0x7ffe, false);
            x.registers[1] = binary80_normal(u64::MAX, 0x7ffe, false);
        }));

        for x87 in cases {
            let mut state = LongModeState::default();
            state.rip = 0x1000;
            state.gpr = [0x0123_4567_89ab_cdef; 16];
            state.rflags = 0xa55a_1234_5678_9abc;
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(&[0xd8, 0xc1], 0x1000);
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { opcode: 0xd8 })
            );
            assert_eq!(state, before);
        }

        for source_index in 0u8..=7 {
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = 0;
            x87.tag_word = 0;
            x87.registers[0] = normal;
            x87.registers[usize::from(source_index)] = normal;
            let top = x87.top();
            let bad_tag_slot = usize::from((top + source_index) & 7);
            x87.tag_word |= 3 << (bad_tag_slot * 2);
            let mut state = LongModeState::default();
            state.rip = 0x1000;
            state.gpr = [0x0123_4567_89ab_cdef; 16];
            state.rflags = 0xa55a_1234_5678_9abc;
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(&[0xd8, 0xc0 | source_index], 0x1000);
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { opcode: 0xd8 })
            );
            assert_eq!(state, before, "source index {source_index}");
        }
    }

    #[test]
    fn fadd_st0_sti_rounds_all_fcws_and_stack_pairs_with_sticky_diagnostics() {
        const CONTROL_WORDS: [u16; 12] = [
            0x007f, 0x047f, 0x087f, 0x0c7f, 0x027f, 0x067f, 0x0a7f, 0x0e7f, 0x037f, 0x077f, 0x0b7f,
            0x0f7f,
        ];
        let lhs_significand = 0x8000_0000_0000_0001;
        let rhs_significand = 0x8000_0000_0000_0000;
        for control_word in CONTROL_WORDS {
            let precision = match control_word & 0x0300 {
                0x0000 => 24,
                0x0200 => 53,
                _ => 64,
            };
            let rounding = (control_word >> 10) & 3;
            for top in 0u8..8 {
                for source_index in 0u8..8 {
                    for (lhs_negative, rhs_negative) in
                        [(false, false), (false, true), (true, false), (true, true)]
                    {
                        let mut state = LongModeState::default();
                        state.rip = 0x1000;
                        state.gpr = std::array::from_fn(|n| 0x1122_3344_5566_7788 ^ n as u64);
                        state.rflags = 0xa55a_1234_5678_9abc;
                        let physical_top = usize::from(top);
                        let physical_source = usize::from((top + source_index) & 7);
                        let mut x87 = crate::state::X87State::fixture_seed();
                        x87.control_word = control_word;
                        let old_pe = (top + source_index) & 1 != 0;
                        x87.status_word =
                            (u16::from(top) << 11) | 0x4500 | (1 << 9) | (u16::from(old_pe) << 5);
                        x87.tag_word = u16::MAX;
                        x87.registers[physical_top] =
                            binary80_normal(lhs_significand, 0x3fff, lhs_negative);
                        x87.set_tag(top, X87Tag::Valid);
                        if source_index != 0 {
                            x87.registers[physical_source] =
                                binary80_normal(rhs_significand, 0x3fff, rhs_negative);
                            x87.set_tag(physical_source as u8, X87Tag::Valid);
                        }
                        state.x87 = Some(x87);
                        let before = state.clone();
                        let mut memory = Memory::at(&[0xd8, 0xc0 | source_index], state.rip);
                        assert_eq!(
                            step(&mut state, &mut memory, AccessContext::default()),
                            Ok(StepOutcome::Advanced),
                            "FCW={control_word:#06x}, TOP={top}, i={source_index}, signs={lhs_negative}/{rhs_negative}"
                        );

                        let (expected_value, inexact, incremented) = if source_index == 0 {
                            if precision == 64 {
                                (
                                    binary80_normal(lhs_significand, 0x4000, lhs_negative),
                                    false,
                                    false,
                                )
                            } else {
                                let incremented = match (rounding, lhs_negative) {
                                    (1, true) | (2, false) => true,
                                    _ => false,
                                };
                                let low_bit = if incremented {
                                    1u64 << (64 - precision)
                                } else {
                                    0
                                };
                                (
                                    binary80_normal(
                                        0x8000_0000_0000_0000 | low_bit,
                                        0x4000,
                                        lhs_negative,
                                    ),
                                    true,
                                    incremented,
                                )
                            }
                        } else if lhs_negative != rhs_negative {
                            (
                                binary80_normal(0x8000_0000_0000_0000, 0x3fc0, lhs_negative),
                                false,
                                false,
                            )
                        } else {
                            let incremented = match (rounding, lhs_negative) {
                                (1, true) | (2, false) => true,
                                _ => false,
                            };
                            let low_bit = if incremented {
                                1u64 << (64 - precision)
                            } else {
                                0
                            };
                            (
                                binary80_normal(
                                    0x8000_0000_0000_0000 | low_bit,
                                    0x4000,
                                    lhs_negative,
                                ),
                                true,
                                incremented,
                            )
                        };
                        let mut expected = before.clone();
                        let expected_x87 = expected.x87.as_mut().unwrap();
                        expected_x87.registers[physical_top] = expected_value;
                        expected_x87.status_word = (expected_x87.status_word
                            & !((1 << 5) | (1 << 9)))
                            | (u16::from(old_pe || inexact) << 5)
                            | (u16::from(incremented) << 9);
                        expected_x87.instruction_pointer = before.rip;
                        expected.rip += 2;
                        assert_eq!(state, expected);
                        assert!(memory.accesses.is_empty(), "FADD performs no data access");
                        assert_eq!(memory.fetches, [before.rip, before.rip + 1]);
                        assert_eq!(memory.bytes, (0..32).collect::<Vec<u8>>());
                    }
                }
            }
        }
    }

    #[test]
    fn fadd_st0_sti_preserves_gap_through_64_rounding() {
        for (gap, expected, inexact) in [
            (
                1u16,
                binary80_normal(0xc000_0000_0000_0000, 0x3fff, false),
                false,
            ),
            (
                63,
                binary80_normal(0x8000_0000_0000_0001, 0x3fff, false),
                false,
            ),
            (
                64,
                binary80_normal(0x8000_0000_0000_0000, 0x3fff, false),
                true,
            ),
        ] {
            let mut state = LongModeState::default();
            state.rip = 0x1100;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = 1 << 9;
            x87.tag_word = u16::MAX;
            x87.registers[0] = binary80_normal(0x8000_0000_0000_0000, 0x3fff, false);
            x87.registers[1] = binary80_normal(0x8000_0000_0000_0000, 0x3fff - gap, false);
            x87.set_tag(0, X87Tag::Valid);
            x87.set_tag(1, X87Tag::Valid);
            state.x87 = Some(x87);
            let mut memory = Memory::at(&[0xd8, 0xc1], state.rip);
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Advanced),
                "gap={gap}"
            );
            assert_eq!(
                state.x87.as_ref().unwrap().registers[0],
                expected,
                "gap={gap}"
            );
            assert_eq!(
                state.x87.as_ref().unwrap().status_word & (1 << 5) != 0,
                inexact,
                "gap={gap}"
            );
        }
    }

    #[test]
    fn fadd_st0_sti_large_gaps_round_all_fcws_and_preserve_full_state() {
        const CONTROL_WORDS: [u16; 12] = [
            0x007f, 0x047f, 0x087f, 0x0c7f, 0x027f, 0x067f, 0x0a7f, 0x0e7f, 0x037f, 0x077f, 0x0b7f,
            0x0f7f,
        ];
        let cases = [
            (65u16, 0x3fff, false, false),
            (66, 0x3fff, true, true),
            (127, 0x3fff, false, true),
            (128, 0x3fff, true, false),
            (32_765, 0x7ffe, false, false),
        ];
        for (gap, high_exponent, negative, high_at_top) in cases {
            for control_word in CONTROL_WORDS {
                let precision = match control_word & 0x0300 {
                    0 => 24,
                    0x0200 => 53,
                    _ => 64,
                };
                let rounding = (control_word >> 10) & 3;
                let increments = if negative {
                    rounding == 1
                } else {
                    rounding == 2
                };
                let expected_significand = if increments {
                    0x8000_0000_0000_0000 | (1u64 << (64 - precision))
                } else {
                    0x8000_0000_0000_0000
                };
                let expected_value = binary80_normal(expected_significand, high_exponent, negative);
                let high = binary80_normal(0x8000_0000_0000_0000, high_exponent, negative);
                let low = binary80_normal(0x8000_0000_0000_0000, high_exponent - gap, negative);
                for top in 0u8..8 {
                    for source_index in 1u8..8 {
                        let mut state = LongModeState::default();
                        state.rip = 0x1180;
                        let mut x87 = crate::state::X87State::fixture_seed();
                        x87.control_word = control_word;
                        x87.status_word = (u16::from(top) << 11) | (1 << 5) | (1 << 9);
                        x87.tag_word = u16::MAX;
                        let physical_top = usize::from(top);
                        let physical_source = usize::from(top.wrapping_add(source_index) & 7);
                        x87.registers[physical_top] = if high_at_top { high } else { low };
                        x87.registers[physical_source] = if high_at_top { low } else { high };
                        x87.set_tag(top, X87Tag::Valid);
                        x87.set_tag(physical_source as u8, X87Tag::Valid);
                        state.x87 = Some(x87);
                        let before = state.clone();
                        let mut memory = Memory::at(&[0xd8, 0xc0 | source_index], state.rip);
                        assert_eq!(
                            step(&mut state, &mut memory, AccessContext::default()),
                            Ok(StepOutcome::Advanced),
                            "gap={gap}, cw={control_word:#06x}, TOP={top}, ST({source_index})"
                        );
                        let mut expected = before;
                        let expected_x87 = expected.x87.as_mut().unwrap();
                        expected_x87.registers[physical_top] = expected_value;
                        expected_x87.status_word = (expected_x87.status_word
                            & !((1 << 5) | (1 << 9)))
                            | (1 << 5)
                            | (u16::from(increments) << 9);
                        expected_x87.instruction_pointer = expected.rip;
                        expected.rip += 2;
                        assert_eq!(state, expected, "gap={gap}, cw={control_word:#06x}");
                        assert!(memory.accesses.is_empty());
                    }
                }
            }
        }
    }

    #[test]
    fn faddp_accepts_gap_65_after_dc_fadd_extension() {
        let mut state = LongModeState::default();
        state.rip = 0x11a0;
        let mut x87 = crate::state::X87State::fixture_seed();
        x87.control_word = 0x037f;
        x87.status_word = 1 << 9;
        x87.tag_word = u16::MAX;
        x87.registers[0] = binary80_normal(0x8000_0000_0000_0000, 0x3fff, false);
        x87.registers[1] = binary80_normal(0x8000_0000_0000_0000, 0x3fff - 65, false);
        x87.set_tag(0, X87Tag::Valid);
        x87.set_tag(1, X87Tag::Valid);
        state.x87 = Some(x87);
        let mut memory = Memory::at(&[0xde, 0xc1], state.rip);
        assert_eq!(
            step(&mut state, &mut memory, AccessContext::default()),
            Ok(StepOutcome::Advanced)
        );
        let x87 = state.x87.as_ref().unwrap();
        assert_eq!(
            x87.registers[1],
            binary80_normal(0x8000_0000_0000_0000, 0x3fff, false)
        );
        assert_eq!(x87.tag(0), Some(X87Tag::Empty));
        assert_eq!(x87.top(), 1);
        assert_ne!(x87.status_word & (1 << 5), 0);
        assert_eq!(x87.status_word & (1 << 9), 0);
    }

    #[test]
    fn fadd_st0_sti_large_gap_tails_cross_p24_and_p53_midpoints_by_parity() {
        for precision in [24u32, 53] {
            let ulp_bit = 64 - precision;
            let half_bit = ulp_bit - 1;
            for odd_lower in [false, true] {
                for tail_negative in [false, true] {
                    let retained = if odd_lower { 1u64 << ulp_bit } else { 0 };
                    let high_significand = 0x8000_0000_0000_0000 | retained | (1u64 << half_bit);
                    let high = binary80_normal(high_significand, 0x3fff, false);
                    let low = binary80_normal(0x8000_0000_0000_0000, 0x3fff - 65, tail_negative);
                    let mut state = LongModeState::default();
                    state.rip = 0x11d0;
                    let mut x87 = crate::state::X87State::fixture_seed();
                    x87.control_word = match precision {
                        24 => 0x007f,
                        _ => 0x027f,
                    };
                    x87.status_word = 0;
                    x87.tag_word = u16::MAX;
                    x87.registers[0] = high;
                    x87.registers[1] = low;
                    x87.set_tag(0, X87Tag::Valid);
                    x87.set_tag(1, X87Tag::Valid);
                    state.x87 = Some(x87);
                    let mut memory = Memory::at(&[0xd8, 0xc1], state.rip);
                    assert_eq!(
                        step(&mut state, &mut memory, AccessContext::default()),
                        Ok(StepOutcome::Advanced)
                    );
                    let rounds_up = !tail_negative;
                    let expected_significand = if rounds_up {
                        0x8000_0000_0000_0000
                            | ((retained + (1u64 << ulp_bit)) & !((1u64 << ulp_bit) - 1))
                    } else {
                        0x8000_0000_0000_0000 | retained
                    };
                    assert_eq!(
                        state.x87.as_ref().unwrap().registers[0],
                        binary80_normal(expected_significand, 0x3fff, false),
                        "p={precision}, odd_lower={odd_lower}, tail_negative={tail_negative}"
                    );
                    assert_eq!(state.x87.as_ref().unwrap().status_word & (1 << 5), 1 << 5);
                    assert_eq!(
                        state.x87.as_ref().unwrap().status_word & (1 << 9) != 0,
                        rounds_up
                    );
                }
            }
        }
    }

    #[test]
    fn fadd_st0_sti_large_gap_alias_and_overflow_boundary() {
        let mut alias = LongModeState::default();
        alias.rip = 0x11b0;
        let mut x87 = crate::state::X87State::fixture_seed();
        x87.control_word = 0x037f;
        x87.status_word = 0;
        x87.tag_word = u16::MAX;
        x87.registers[0] = binary80_normal(0x8000_0000_0000_0000, 0x3fff, false);
        x87.set_tag(0, X87Tag::Valid);
        alias.x87 = Some(x87);
        let mut memory = Memory::at(&[0xd8, 0xc0], alias.rip);
        assert_eq!(
            step(&mut alias, &mut memory, AccessContext::default()),
            Ok(StepOutcome::Advanced)
        );
        assert_eq!(
            alias.x87.as_ref().unwrap().registers[0],
            binary80_normal(0x8000_0000_0000_0000, 0x4000, false)
        );

        let mut overflow = LongModeState::default();
        overflow.rip = 0x11c0;
        let mut x87 = crate::state::X87State::fixture_seed();
        x87.control_word = 0x087f;
        x87.status_word = 1 << 9;
        x87.tag_word = u16::MAX;
        x87.registers[0] = binary80_normal(u64::MAX, 0x7ffe, false);
        x87.registers[1] = binary80_normal(0x8000_0000_0000_0000, 0x7ffe - 65, false);
        x87.set_tag(0, X87Tag::Valid);
        x87.set_tag(1, X87Tag::Valid);
        overflow.x87 = Some(x87);
        let before = overflow.clone();
        let mut memory = Memory::at(&[0xd8, 0xc1], overflow.rip);
        assert_eq!(
            step(&mut overflow, &mut memory, AccessContext::default()),
            Ok(StepOutcome::Unsupported { opcode: 0xd8 })
        );
        assert_eq!(overflow, before);
    }

