    #[test]
    fn fistp_m16int_signaling_nan_rejects_noncanonical_classes_and_faults_atomically() {
        let signaling_nan = binary80_normal(0x8000_0000_0000_0001, 0x7fff, false);
        let invalid_sources = [
            (X87Tag::Valid, signaling_nan),
            (X87Tag::Zero, signaling_nan),
            (X87Tag::Empty, signaling_nan),
        ];
        for (tag, raw) in invalid_sources {
            let mut state = LongModeState::default();
            state.rip = 0x8417;
            state.gpr[Register::Rax as usize] = 0x1000;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = 0;
            x87.registers[0] = raw;
            x87.set_tag(0, tag);
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(&[0xdf, 0x18], state.rip);
            memory.bytes = vec![0xa5; 8];
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { opcode: 0xdf }),
                "tag={tag:?} raw={raw:02x?}"
            );
            assert_eq!(state, before);
            assert_eq!(memory.bytes, vec![0xa5; 8]);
            assert!(memory.accesses.is_empty());
        }

        for (control_word, status_word) in [
            (0x037e, 0),
            (0x037f, 0x0040),
            (0x037f, 0x0080),
            (0x037f, 0x8000),
        ] {
            let mut state = LongModeState::default();
            state.rip = 0x8417;
            state.gpr[Register::Rax as usize] = 0x1000;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = control_word;
            x87.status_word = status_word;
            x87.registers[0] = signaling_nan;
            x87.set_tag(0, X87Tag::Special);
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(&[0xdf, 0x18], state.rip);
            memory.bytes = vec![0xa5; 8];
            assert!(matches!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { .. })
            ));
            assert_eq!(state, before);
            assert_eq!(memory.bytes, vec![0xa5; 8]);
            assert!(memory.accesses.is_empty());
        }

        for code in [&[0x66, 0xdf, 0x18][..], &[0x67, 0xdf, 0x18][..]] {
            let mut state = LongModeState::default();
            state.rip = 0x8417;
            state.gpr[Register::Rax as usize] = 0x1000;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = 0;
            x87.registers[0] = signaling_nan;
            x87.set_tag(0, X87Tag::Special);
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(code, state.rip);
            memory.bytes = vec![0xa5; 8];
            assert!(matches!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { .. })
            ));
            assert_eq!(state, before);
            assert_eq!(memory.bytes, vec![0xa5; 8]);
            assert!(memory.accesses.is_empty());
        }

        for address in [0x0000_8000_0000_0000, 0x0000_7fff_ffff_ffff] {
            let mut state = LongModeState::default();
            state.rip = 0x8417;
            state.gpr[Register::Rax as usize] = address;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = 0x4520;
            x87.registers[0] = signaling_nan;
            x87.set_tag(0, X87Tag::Special);
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(&[0xdf, 0x18], state.rip);
            memory.bytes = vec![0xa5; 8];
            assert!(matches!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Fault(ArchitecturalFault { vector: 13, .. }))
            ));
            assert_eq!(state, before);
            assert_eq!(memory.bytes, vec![0xa5; 8]);
            assert!(memory.accesses.is_empty());
        }

        let mut state = LongModeState::default();
        state.rip = 0x8417;
        state.gpr[Register::Rax as usize] = 0x1000;
        let mut x87 = crate::state::X87State::fixture_seed();
        x87.control_word = 0x037f;
        x87.status_word = 0x4520;
        x87.registers[0] = signaling_nan;
        x87.set_tag(0, X87Tag::Special);
        state.x87 = Some(x87);
        let before = state.clone();
        let mut memory = Memory::at(&[0xdf, 0x18], state.rip);
        memory.bytes = vec![0xa5; 8];
        memory.deny_writes = true;
        assert!(matches!(
            step(&mut state, &mut memory, AccessContext::default()),
            Err(MemoryError::PermissionDenied { .. })
        ));
        assert_eq!(state, before);
        assert_eq!(memory.bytes, vec![0xa5; 8]);
        assert_eq!(memory.accesses, vec![(AccessKind::Write, 0x1000, 2)]);
    }

