    #[test]
    fn fistp_m64int_rounds_literal_ties_and_commits_qword_before_wrapping_pop() {
        for (control_word, expected_positive, expected_negative) in [
            (0x037f, 2_u64, u64::MAX - 1),
            (0x077f, 1, u64::MAX - 1),
            (0x0b7f, 2, u64::MAX),
            (0x0f7f, 1, u64::MAX),
        ] {
            for (negative, expected) in [(false, expected_positive), (true, expected_negative)] {
                let mut state = LongModeState::default();
                state.rip = 0x8480;
                state.gpr[Register::Rax as usize] = 0x1001;
                state.gpr[Register::Rcx as usize] = 0x1234_5678_9abc_def0;
                state.rflags = 0x8d5;
                let mut x87 = crate::state::X87State::fixture_seed();
                x87.control_word = control_word;
                x87.status_word = 0x3820;
                x87.registers[7] = binary80_normal(0xc000_0000_0000_0000, 0x3fff, negative);
                x87.set_tag(7, X87Tag::Valid);
                state.x87 = Some(x87);
                let before_registers = state.x87.as_ref().unwrap().registers;
                let before_gprs = state.gpr;
                let mut memory = Memory::at(&[0xdf, 0x38], state.rip);
                memory.bytes = vec![0xa5; 12];

                assert_eq!(
                    step(&mut state, &mut memory, AccessContext::default()),
                    Ok(StepOutcome::Advanced),
                    "FCW={control_word:04x}, negative={negative}"
                );
                assert_eq!(memory.bytes[..1], [0xa5]);
                assert_eq!(&memory.bytes[1..9], &expected.to_le_bytes());
                assert_eq!(&memory.bytes[9..], &[0xa5; 3]);
                assert_eq!(memory.accesses, vec![(AccessKind::Write, 0x1001, 8)]);
                assert_eq!(state.gpr, before_gprs);
                assert_eq!(state.rflags, 0x8d5);
                let result = state.x87.as_ref().unwrap();
                assert_eq!(result.registers, before_registers);
                assert_eq!(result.tag(7), Some(X87Tag::Empty));
                assert_eq!(result.top(), 0);
                let incremented = expected != if negative { u64::MAX } else { 1 };
                assert_eq!(
                    result.status_word,
                    0x0020 | if incremented { 0x0200 } else { 0 }
                );
                assert_eq!(result.control_word, control_word);
                assert_eq!(result.instruction_pointer, 0x8480);
                assert_eq!(result.data_pointer, 0x1001);
                assert_eq!(state.rip, 0x8482);
            }
        }
    }

    #[test]
    fn fistp_m64int_canonical_infinity_stores_indefinite_with_ie_for_every_environment() {
        for negative in [false, true] {
            let raw = binary80_normal(0x8000_0000_0000_0000, 0x7fff, negative);
            for control_word in [0x037f, 0x077f, 0x0b7f, 0x0f7f] {
                for top in 0..8_u8 {
                    for incoming_pe in [false, true] {
                        for incoming_c1 in [false, true] {
                            let mut state = LongModeState::default();
                            state.rip = 0x8487;
                            state.gpr[Register::Rax as usize] = 0x1003;
                            let mut x87 = crate::state::X87State::fixture_seed();
                            x87.control_word = control_word;
                            x87.status_word = (u16::from(top) << 11)
                                | 0x4500
                                | if incoming_pe { 0x0020 } else { 0 }
                                | if incoming_c1 { 0x0200 } else { 0 };
                            x87.registers[usize::from(top)] = raw;
                            x87.set_tag(top, X87Tag::Special);
                            state.x87 = Some(x87);
                            let before_registers = state.x87.as_ref().unwrap().registers;
                            let before_tags = state.x87.as_ref().unwrap().tag_word;
                            let before_status = state.x87.as_ref().unwrap().status_word;
                            let mut memory = Memory::at(&[0xdf, 0x38], state.rip);
                            memory.bytes = vec![0xa5; 24];

                            assert_eq!(
                                step(&mut state, &mut memory, AccessContext::default()),
                                Ok(StepOutcome::Advanced),
                                "negative={negative} FCW={control_word:04x} TOP={top} PE={incoming_pe} C1={incoming_c1}"
                            );
                            assert_eq!(&memory.bytes[..3], &[0xa5; 3]);
                            assert_eq!(&memory.bytes[3..11], &[0, 0, 0, 0, 0, 0, 0, 0x80]);
                            assert_eq!(&memory.bytes[11..], &[0xa5; 13]);
                            assert_eq!(
                                memory.accesses,
                                vec![(AccessKind::Write, 0x1003, 8)],
                                "infinity FISTP must issue one Qword write and no read"
                            );
                            let after = state.x87.as_ref().unwrap();
                            assert_eq!(after.registers, before_registers);
                            assert_eq!(
                                after.tag_word,
                                before_tags | (3_u16 << (u32::from(top) * 2))
                            );
                            let new_top = top.wrapping_add(1) & 7;
                            assert_eq!(after.top(), new_top);
                            let expected_status = (before_status & !(0x0200 | (7 << 11)))
                                | (u16::from(new_top) << 11)
                                | 0x0001;
                            assert_eq!(after.status_word, expected_status);
                            assert_eq!(after.instruction_pointer, 0x8487);
                            assert_eq!(after.data_pointer, 0x1003);
                            assert_eq!(state.rip, 0x8489);
                        }
                    }
                }
            }
        }
    }

