    #[test]
    fn fst_m32fp_store_faults_preserve_cpu_and_memory_and_report_architectural_pf() {
        let setup = || {
            let mut state = LongModeState::default();
            state.rip = 0x84e0;
            state.gpr[Register::Rax as usize] = 0x1000;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = 0;
            x87.registers[0] = binary80_normal(1 << 63, 0x3fff, false);
            x87.set_tag(0, X87Tag::Valid);
            state.x87 = Some(x87);
            state
        };

        let mut denied = setup();
        let before = denied.clone();
        let mut memory = Memory::at(&[0xd9, 0x10], denied.rip);
        memory.bytes = vec![0xa5; 8];
        memory.deny_writes = true;
        assert!(matches!(
            step(&mut denied, &mut memory, AccessContext::default()),
            Err(MemoryError::PermissionDenied { .. })
        ));
        assert_eq!(denied, before);
        assert_eq!(memory.bytes, vec![0xa5; 8]);
        assert_eq!(memory.accesses, vec![(AccessKind::Write, 0x1000, 4)]);

        let mut faulted = setup();
        let before = faulted.clone();
        let fault = ArchitecturalFault {
            vector: 14,
            error_code: Some(2),
            linear_address: Some(0x1000),
        };
        let mut memory = Memory::at(&[0xd9, 0x10], faulted.rip);
        memory.bytes = vec![0xa5; 8];
        memory.error = Some(MemoryError::Architectural(fault.clone()));
        memory.error_kind = Some(AccessKind::Write);
        assert_eq!(
            step(&mut faulted, &mut memory, AccessContext::default()),
            Ok(StepOutcome::Fault(fault))
        );
        assert_eq!(faulted, before);
        assert_eq!(memory.bytes, vec![0xa5; 8]);
        assert_eq!(memory.accesses, vec![(AccessKind::Write, 0x1000, 4)]);

        let mut noncanonical = setup();
        noncanonical.gpr[Register::Rax as usize] = 0x0000_7fff_ffff_fffe;
        let before = noncanonical.clone();
        let mut memory = Memory::at(&[0xd9, 0x10], noncanonical.rip);
        assert!(matches!(
            step(&mut noncanonical, &mut memory, AccessContext::default()),
            Ok(StepOutcome::Fault(_))
        ));
        assert_eq!(noncanonical, before);
        assert!(memory.accesses.is_empty());
    }

    #[test]
    fn fst_m32fp_rejects_invalid_environment_and_execution_boundaries_atomically() {
        let setup = || {
            let mut state = LongModeState::default();
            state.rip = 0x84f0;
            state.gpr[Register::Rax as usize] = 0x1000;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = 0;
            x87.registers[0] = binary80_normal(1 << 63, 0x3fff, false);
            x87.set_tag(0, X87Tag::Valid);
            state.x87 = Some(x87);
            state
        };
        let mut invalid_fcws = vec![{
            let mut state = setup();
            state.x87.as_mut().unwrap().control_word = 0x027f;
            state
        }];
        for control_word in [0x077e, 0x0bff, 0x1f7f] {
            invalid_fcws.push({
                let mut state = setup();
                state.x87.as_mut().unwrap().control_word = control_word;
                state
            });
        }
        for forbidden_status in [0x0040, 0x0080, 0x8000] {
            invalid_fcws.push({
                let mut state = setup();
                state.x87.as_mut().unwrap().status_word = forbidden_status;
                state
            });
        }
        invalid_fcws.push({
            let mut state = setup();
            state.x87.as_mut().unwrap().set_tag(0, X87Tag::Empty);
            state
        });
        invalid_fcws.push({
            let mut state = setup();
            state.x87.as_mut().unwrap().set_tag(0, X87Tag::Special);
            state
        });
        invalid_fcws.push({
            let mut state = setup();
            state.x87.as_mut().unwrap().registers[0] = [0; 10];
            state
        });
        invalid_fcws.push({
            let mut state = setup();
            state.x87 = None;
            state
        });
        for mut state in invalid_fcws {
            let before = state.clone();
            let mut memory = Memory::at(&[0xd9, 0x10], state.rip);
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { opcode: 0xd9 })
            );
            assert_eq!(state, before);
            assert!(memory.accesses.is_empty());
        }

        for (bytes, stop_rip, budget, fetch_error) in [
            (&[0xd9][..], None, 1, false),
            (&[0xd9, 0x10][..], Some(0x84f0), 1, false),
            (&[0xd9, 0x10][..], None, 0, false),
            (&[0xd9, 0x10][..], None, 1, true),
        ] {
            let mut state = setup();
            let before = state.clone();
            let mut memory = Memory::at(bytes, state.rip);
            if fetch_error {
                memory.fetch_error = Some((
                    state.rip + 1,
                    MemoryError::Unmapped {
                        address: state.rip + 1,
                        access: AccessKind::Fetch,
                    },
                ));
            }
            let result = run(
                &mut state,
                &mut memory,
                RunConfig {
                    instruction_budget: budget,
                    stop_rip,
                    context: AccessContext::default(),
                },
                || false,
            );
            assert_eq!(result.instructions_executed, 0);
            assert_eq!(state, before);
            assert!(memory.accesses.is_empty());
        }
    }

    #[test]
    fn fistp_m64int_rounds_normal_fractions_below_one_for_every_environment() {
        // Literal Qword results by RN/RD/RU/RZ rows and positive/negative columns.
        let vectors = [
            (
                1_u64 << 63,
                0x3ffe_u16,
                "exact half",
                [[0, 0], [0, u64::MAX], [1, 0], [0, 0]],
            ),
            (
                (1_u64 << 63) + 1,
                0x3ffe,
                "above half",
                [[1, u64::MAX], [0, u64::MAX], [1, 0], [0, 0]],
            ),
            (
                u64::MAX,
                0x3ffd,
                "immediately below half",
                [[0, 0], [0, u64::MAX], [1, 0], [0, 0]],
            ),
            (
                u64::MAX,
                0x3ffe,
                "immediately below one",
                [[1, u64::MAX], [0, u64::MAX], [1, 0], [0, 0]],
            ),
            (
                1_u64 << 63,
                0x0001,
                "minimum Normal",
                [[0, 0], [0, u64::MAX], [1, 0], [0, 0]],
            ),
            (
                1_u64 << 63,
                0x3ffd,
                "exponent -2",
                [[0, 0], [0, u64::MAX], [1, 0], [0, 0]],
            ),
            (
                1_u64 << 63,
                0x3fc0,
                "exponent -63",
                [[0, 0], [0, u64::MAX], [1, 0], [0, 0]],
            ),
            (
                1_u64 << 63,
                0x3fbf,
                "exponent -64",
                [[0, 0], [0, u64::MAX], [1, 0], [0, 0]],
            ),
            (
                1_u64 << 63,
                0x3fbe,
                "exponent -65",
                [[0, 0], [0, u64::MAX], [1, 0], [0, 0]],
            ),
        ];
        for (significand, exponent_word, label, expected_by_mode) in vectors {
            for (sign_index, negative) in [false, true].into_iter().enumerate() {
                let raw = binary80_normal(significand, exponent_word, negative);
                for (mode_index, control_word) in
                    [0x037f, 0x077f, 0x0b7f, 0x0f7f].into_iter().enumerate()
                {
                    let expected = expected_by_mode[mode_index][sign_index];
                    for top in 0..8_u8 {
                        for incoming_pe in [false, true] {
                            for incoming_c1 in [false, true] {
                                let mut state = LongModeState::default();
                                state.rip = 0x8490;
                                state.gpr[Register::Rax as usize] = 0x1001;
                                let mut x87 = crate::state::X87State::fixture_seed();
                                x87.control_word = control_word;
                                x87.status_word = (u16::from(top) << 11)
                                    | 0x4100
                                    | if incoming_pe { 0x0020 } else { 0 }
                                    | if incoming_c1 { 0x0200 } else { 0 };
                                x87.registers[usize::from(top)] = raw;
                                x87.set_tag(top, X87Tag::Valid);
                                state.x87 = Some(x87);
                                let before_registers = state.x87.as_ref().unwrap().registers;
                                let before_tags = state.x87.as_ref().unwrap().tag_word;
                                let before_status = state.x87.as_ref().unwrap().status_word;
                                let mut memory = Memory::at(&[0xdf, 0x38], state.rip);
                                memory.bytes = vec![0xa5; 16];

                                assert_eq!(
                                    step(&mut state, &mut memory, AccessContext::default()),
                                    Ok(StepOutcome::Advanced),
                                    "{label}: FCW={control_word:04x} negative={negative} TOP={top} PE={incoming_pe} C1={incoming_c1}"
                                );
                                assert_eq!(&memory.bytes[1..9], &expected.to_le_bytes());
                                assert_eq!(memory.bytes[0], 0xa5);
                                assert_eq!(&memory.bytes[9..], &[0xa5; 7]);
                                assert_eq!(
                                    memory.accesses,
                                    vec![(AccessKind::Write, 0x1001, 8)],
                                    "fractional FISTP m64 must issue one Qword write and no read"
                                );
                                let after = state.x87.as_ref().unwrap();
                                assert_eq!(after.registers, before_registers);
                                assert_eq!(
                                    after.tag_word,
                                    before_tags | (3_u16 << (u32::from(top) * 2))
                                );
                                let new_top = top.wrapping_add(1) & 7;
                                assert_eq!(after.top(), new_top);
                                let expected_status = (before_status & !(0x0200 | (7 << 11)))
                                    | (u16::from(new_top) << 11)
                                    | 0x0020
                                    | if expected != 0 { 0x0200 } else { 0 };
                                assert_eq!(after.status_word, expected_status);
                                assert_eq!(after.instruction_pointer, 0x8490);
                                assert_eq!(after.data_pointer, 0x1001);
                                assert_eq!(state.rip, 0x8492);
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn fistp_m64int_rounds_canonical_subnormals_for_every_sticky_status_combination() {
        let fractions = [
            1_u64,
            0x0123_4567_89ab_cdef,
            0x4000_0000_0000_0000,
            0x7fff_ffff_ffff_ffff,
        ];
        let control_words = [0x037f, 0x077f, 0x0b7f, 0x0f7f];
        for fraction in fractions {
            for negative in [false, true] {
                let raw = binary80_normal(fraction, 0, negative);
                for (mode, control_word) in control_words.into_iter().enumerate() {
                    for top in 0..8_u8 {
                        for sticky in 0..64_u16 {
                            for old_c1 in [false, true] {
                                let magnitude = u64::from(match mode {
                                    1 => negative,
                                    2 => !negative,
                                    _ => false,
                                });
                                let expected = if negative {
                                    0_u64.wrapping_sub(magnitude)
                                } else {
                                    magnitude
                                };
                                let mut state = LongModeState::default();
                                state.rip = 0x8490;
                                state.gpr[Register::Rax as usize] = 0x1003;
                                let mut x87 = crate::state::X87State::fixture_seed();
                                x87.control_word = control_word;
                                x87.status_word = (u16::from(top) << 11)
                                    | 0x4500
                                    | sticky
                                    | if old_c1 { 0x0200 } else { 0 };
                                x87.registers[usize::from(top)] = raw;
                                x87.set_tag(top, X87Tag::Special);
                                state.x87 = Some(x87);
                                let before = state.x87.as_ref().unwrap().clone();
                                let mut memory = Memory::at(&[0xdf, 0x38], state.rip);
                                memory.bytes = vec![0xa5; 16];

                                assert_eq!(
                                    step(&mut state, &mut memory, AccessContext::default()),
                                    Ok(StepOutcome::Advanced),
                                    "fraction={fraction:#018x} negative={negative} RC={mode} TOP={top} sticky={sticky:#04x} C1={old_c1}"
                                );
                                assert_eq!(&memory.bytes[3..11], &expected.to_le_bytes());
                                assert_eq!(&memory.bytes[..3], &[0xa5; 3]);
                                assert_eq!(&memory.bytes[11..], &[0xa5; 5]);
                                assert_eq!(memory.accesses, vec![(AccessKind::Write, 0x1003, 8)]);
                                let after = state.x87.as_ref().unwrap();
                                assert_eq!(after.registers, before.registers);
                                assert_eq!(
                                    after.tag_word,
                                    before.tag_word | (3_u16 << (u32::from(top) * 2))
                                );
                                let new_top = top.wrapping_add(1) & 7;
                                assert_eq!(after.top(), new_top);
                                assert_eq!(after.status_word & 0x003f, sticky | 0x0020);
                                assert_eq!(after.status_word & 0x4500, 0x4500);
                                assert_eq!(after.status_word & 0x0200 != 0, magnitude == 1);
                                assert_eq!(after.instruction_pointer, 0x8490);
                                assert_eq!(after.data_pointer, 0x1003);
                                assert_eq!(state.rip, 0x8492);
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn fistp_m64int_fraction_rejects_other_sources_and_controls_before_access() {
        let valid_fraction = binary80_normal(1_u64 << 63, 0x3ffd, false);
        let invalid_sources = [
            (X87Tag::Empty, valid_fraction),
            (X87Tag::Zero, valid_fraction),
            (X87Tag::Special, valid_fraction),
            (
                X87Tag::Valid,
                binary80_normal(0x0123_4567_89ab_cdef, 0, false),
            ),
            (
                X87Tag::Special,
                binary80_normal(0x8123_4567_89ab_cdef, 0, false),
            ),
            (X87Tag::Special, binary80_normal(0, 0, false)),
            (
                X87Tag::Valid,
                binary80_normal(0x8000_0000_0000_0000, 0, false),
            ),
            (X87Tag::Valid, binary80_normal(1, 0, false)),
            (
                X87Tag::Valid,
                binary80_normal(0x4000_0000_0000_0000, 0x3ffe, false),
            ),
            (
                X87Tag::Valid,
                binary80_normal(0x8000_0000_0000_0000, 0x7fff, false),
            ),
        ];
        for (tag, raw) in invalid_sources {
            let mut state = LongModeState::default();
            state.rip = 0x8490;
            state.gpr[Register::Rax as usize] = 0x1000;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = 0;
            x87.registers[0] = raw;
            x87.set_tag(0, tag);
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(&[0xdf, 0x38], state.rip);
            memory.bytes = vec![0xa5; 16];
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { opcode: 0xdf })
            );
            assert_eq!(state, before);
            assert_eq!(memory.bytes, vec![0xa5; 16]);
            assert!(memory.accesses.is_empty());
        }

        for control_word in [0x037e, 0x047f, 0x137f] {
            let mut state = LongModeState::default();
            state.rip = 0x8490;
            state.gpr[Register::Rax as usize] = 0x1000;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = control_word;
            x87.status_word = 0;
            x87.registers[0] = valid_fraction;
            x87.set_tag(0, X87Tag::Valid);
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(&[0xdf, 0x38], state.rip);
            memory.bytes = vec![0xa5; 16];
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { opcode: 0xdf })
            );
            assert_eq!(state, before);
            assert!(memory.accesses.is_empty());
        }

        for forbidden_status in [0x0040, 0x0080, 0x8000] {
            let mut state = LongModeState::default();
            state.rip = 0x8490;
            state.gpr[Register::Rax as usize] = 0x1000;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = forbidden_status;
            x87.registers[0] = valid_fraction;
            x87.set_tag(0, X87Tag::Valid);
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(&[0xdf, 0x38], state.rip);
            memory.bytes = vec![0xa5; 16];
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { opcode: 0xdf })
            );
            assert_eq!(state, before);
            assert!(memory.accesses.is_empty());
        }

        for bytes in [&[0x66, 0xdf, 0x38][..], &[0xdf, 0x30][..]] {
            let mut state = LongModeState::default();
            state.rip = 0x8490;
            state.gpr[Register::Rax as usize] = 0x1000;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = 0;
            x87.registers[0] = valid_fraction;
            x87.set_tag(0, X87Tag::Valid);
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(bytes, state.rip);
            memory.bytes = vec![0xa5; 16];
            assert!(matches!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { .. })
            ));
            assert_eq!(state, before);
            assert_eq!(memory.bytes, vec![0xa5; 16]);
            assert!(memory.accesses.is_empty());
        }
    }

    #[test]
    fn fistp_m64int_fraction_write_and_range_failures_are_atomic() {
        let raw = binary80_normal(1_u64 << 63, 0x3ffd, true);
        for address in [0x0000_8000_0000_0000, 0x0000_7fff_ffff_fffc] {
            let mut state = LongModeState::default();
            state.rip = 0x8490;
            state.gpr[Register::Rax as usize] = address;
            let mut x87 = crate::state::X87State::fixture_seed();
            x87.control_word = 0x037f;
            x87.status_word = 0x4700;
            x87.registers[0] = raw;
            x87.set_tag(0, X87Tag::Valid);
            state.x87 = Some(x87);
            let before = state.clone();
            let mut memory = Memory::at(&[0xdf, 0x38], state.rip);
            memory.bytes = vec![0xa5; 16];
            assert!(matches!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Fault(ArchitecturalFault { vector: 13, .. }))
            ));
            assert_eq!(state, before);
            assert_eq!(memory.bytes, vec![0xa5; 16]);
            assert!(memory.accesses.is_empty());
        }

        let mut state = LongModeState::default();
        state.rip = 0x8490;
        state.gpr[Register::Rax as usize] = 0x1000;
        let mut x87 = crate::state::X87State::fixture_seed();
        x87.control_word = 0x037f;
        x87.status_word = 0x4700;
        x87.registers[0] = raw;
        x87.set_tag(0, X87Tag::Valid);
        state.x87 = Some(x87);
        let before = state.clone();
        let mut memory = Memory::at(&[0xdf, 0x38], state.rip);
        memory.bytes = vec![0xa5; 16];
        memory.deny_writes = true;
        assert!(matches!(
            step(&mut state, &mut memory, AccessContext::default()),
            Err(MemoryError::PermissionDenied {
                access: AccessKind::Write,
                ..
            })
        ));
        assert_eq!(state, before);
        assert_eq!(memory.bytes, vec![0xa5; 16]);
        assert_eq!(memory.accesses, vec![(AccessKind::Write, 0x1000, 8)]);

        let mut injected = before.clone();
        let mut memory = Memory::at(&[0xdf, 0x38], injected.rip);
        memory.bytes = vec![0xa5; 16];
        memory.error = Some(MemoryError::Backend("injected qword write failure".into()));
        memory.error_kind = Some(AccessKind::Write);
        assert!(matches!(
            step(&mut injected, &mut memory, AccessContext::default()),
            Err(MemoryError::Backend(_))
        ));
        assert_eq!(injected, before);
        assert_eq!(memory.bytes, vec![0xa5; 16]);
        assert_eq!(memory.accesses, vec![(AccessKind::Write, 0x1000, 8)]);
    }

