    #[test]
    fn pand_register_covers_truth_table_all_pairs_aliasing_and_full_state() {
        let sentinels = [
            ([0; 16], [0; 16]),
            ([0xff; 16], [0xff; 16]),
            ([0; 16], [0xff; 16]),
            ([0xaa; 16], [0x55; 16]),
            ([0x55; 16], [0xaa; 16]),
            (
                std::array::from_fn(|index| if index < 8 { 0xff } else { 0 }),
                std::array::from_fn(|index| if index < 8 { 0 } else { 0xff }),
            ),
            ([0xff; 16], [0; 16]),
        ];
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                for (lhs, rhs) in sentinels {
                    let mut code = vec![0x66];
                    if destination >= 8 || source >= 8 {
                        code.push(rex);
                    }
                    code.extend([0x0f, 0xdb, modrm]);
                    let mut memory = Memory::at(&code, 0x1000);
                    let mut state = LongModeState::default();
                    state.x87 = Some(X87State::fixture_seed());
                    state.sse = Some(SseState {
                        xmm: [[0x6d; 16]; 16],
                        mxcsr: 0xe1a5_5a7e,
                    });
                    state.sse.as_mut().unwrap().xmm[destination as usize] = lhs;
                    if source != destination {
                        state.sse.as_mut().unwrap().xmm[source as usize] = rhs;
                    }
                    state.rip = 0x1000;
                    state.rflags = 0x8d7 | crate::DF;
                    let before = state.clone();
                    let expected_source = if source == destination { lhs } else { rhs };
                    let expected = std::array::from_fn(|index| lhs[index] & expected_source[index]);
                    assert_eq!(
                        step(&mut state, &mut memory, AccessContext::default()).unwrap(),
                        StepOutcome::Advanced
                    );
                    let mut unchanged = before;
                    unchanged.rip += code.len() as u64;
                    unchanged.sse.as_mut().unwrap().xmm[destination as usize] = expected;
                    assert_eq!(state, unchanged, "dest={destination}, src={source}");
                    assert!(memory.accesses.is_empty(), "PAND performed a data access");
                }
            }
        }

        // Exercise every bit position directly; each vector covers the four
        // AND truth-table rows and includes both lower and upper halves.
        for bit in 0..128usize {
            for (lhs, rhs, expected) in [
                (false, false, false),
                (false, true, false),
                (true, false, false),
                (true, true, true),
            ] {
                let mut state = LongModeState::default();
                state.x87 = Some(X87State::fixture_seed());
                state.sse = Some(SseState {
                    xmm: [[0; 16]; 16],
                    mxcsr: 0x1f80,
                });
                let byte = bit / 8;
                let mask = 1 << (bit % 8);
                state.sse.as_mut().unwrap().xmm[1][byte] = if lhs { mask } else { 0 };
                state.sse.as_mut().unwrap().xmm[2][byte] = if rhs { mask } else { 0 };
                let mut memory = Memory::at(&[0x66, 0x0f, 0xdb, 0xca], 0x1000);
                state.rip = 0x1000;
                step(&mut state, &mut memory, AccessContext::default()).unwrap();
                assert_eq!(
                    state.sse.as_ref().unwrap().xmm[1][byte] & mask != 0,
                    expected,
                    "bit={bit}, lhs={lhs}, rhs={rhs}"
                );
            }
        }
    }

    #[test]
    fn pandn_register_covers_truth_table_all_pairs_aliasing_and_full_state() {
        let sentinels = [
            ([0; 16], [0; 16]),
            ([0xff; 16], [0xff; 16]),
            ([0; 16], [0xff; 16]),
            ([0xaa; 16], [0x55; 16]),
            ([0x55; 16], [0xaa; 16]),
            (
                std::array::from_fn(|index| if index < 8 { 0xff } else { 0 }),
                std::array::from_fn(|index| if index < 8 { 0 } else { 0xff }),
            ),
            ([0xff; 16], [0; 16]),
        ];
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                for (lhs, rhs) in sentinels {
                    let mut code = vec![0x66];
                    if destination >= 8 || source >= 8 {
                        code.push(rex);
                    }
                    code.extend([0x0f, 0xdf, modrm]);
                    let mut memory = Memory::at(&code, 0x1000);
                    let mut state = LongModeState::default();
                    state.x87 = Some(X87State::fixture_seed());
                    state.sse = Some(SseState {
                        xmm: [[0x6d; 16]; 16],
                        mxcsr: 0xe1a5_5a7e,
                    });
                    state.sse.as_mut().unwrap().xmm[destination as usize] = lhs;
                    if source != destination {
                        state.sse.as_mut().unwrap().xmm[source as usize] = rhs;
                    }
                    state.rip = 0x1000;
                    state.rflags = 0x8d7 | crate::DF;
                    let before = state.clone();
                    let expected_source = if source == destination { lhs } else { rhs };
                    let expected =
                        std::array::from_fn(|index| !lhs[index] & expected_source[index]);
                    assert_eq!(
                        step(&mut state, &mut memory, AccessContext::default()).unwrap(),
                        StepOutcome::Advanced
                    );
                    let mut unchanged = before;
                    unchanged.rip += code.len() as u64;
                    unchanged.sse.as_mut().unwrap().xmm[destination as usize] = expected;
                    assert_eq!(state, unchanged, "dest={destination}, src={source}");
                    assert!(memory.accesses.is_empty(), "PANDN performed a data access");
                }
            }
        }

        // Distinguish `~DEST & SRC` from `DEST & ~SRC`: DEST=0xf0 and
        // SRC=0x0f must produce 0x0f, while the reversed operands produce 0xf0.
        let mut state = LongModeState::default();
        state.x87 = Some(X87State::fixture_seed());
        state.sse = Some(SseState {
            xmm: [[0; 16]; 16],
            mxcsr: 0x1f80,
        });
        state.sse.as_mut().unwrap().xmm[1] = [0xf0; 16];
        state.sse.as_mut().unwrap().xmm[2] = [0x0f; 16];
        state.rip = 0x1000;
        let mut memory = Memory::at(&[0x66, 0x0f, 0xdf, 0xca], 0x1000);
        assert_eq!(
            step(&mut state, &mut memory, AccessContext::default()).unwrap(),
            StepOutcome::Advanced
        );
        assert_eq!(state.sse.as_ref().unwrap().xmm[1], [0x0f; 16]);

        // Exercise every bit position directly; each vector covers the four
        // AND truth-table rows and includes both lower and upper halves.
        for bit in 0..128usize {
            for (lhs, rhs, expected) in [
                (false, false, false),
                (false, true, true),
                (true, false, false),
                (true, true, false),
            ] {
                let mut state = LongModeState::default();
                state.x87 = Some(X87State::fixture_seed());
                state.sse = Some(SseState {
                    xmm: [[0; 16]; 16],
                    mxcsr: 0x1f80,
                });
                let byte = bit / 8;
                let mask = 1 << (bit % 8);
                state.sse.as_mut().unwrap().xmm[1][byte] = if lhs { mask } else { 0 };
                state.sse.as_mut().unwrap().xmm[2][byte] = if rhs { mask } else { 0 };
                let mut memory = Memory::at(&[0x66, 0x0f, 0xdf, 0xca], 0x1000);
                state.rip = 0x1000;
                step(&mut state, &mut memory, AccessContext::default()).unwrap();
                assert_eq!(
                    state.sse.as_ref().unwrap().xmm[1][byte] & mask != 0,
                    expected,
                    "bit={bit}, lhs={lhs}, rhs={rhs}"
                );
            }
        }
    }

