    #[test]
    fn pmaxsw_missing_state_truncated_fetch_and_unstarted_run_are_atomic() {
        let code = [0x66, 0x0f, 0xee, 0xc1];
        let mut memory = Memory::at(&code, 0x1000);
        let mut state = LongModeState::default();
        state.rip = 0x1000;
        let before = state.clone();
        assert_eq!(
            step(&mut state, &mut memory, AccessContext::default()).unwrap(),
            StepOutcome::Unsupported { opcode: 0xee }
        );
        assert_eq!(state, before);
        assert!(memory.accesses.is_empty());
        let mut memory = Memory::at(&[0x66, 0x0f, 0xee], 0x1000);
        let mut state = LongModeState::default();
        state.rip = 0x1000;
        state.sse = Some(SseState {
            xmm: [[0xa5; 16]; 16],
            mxcsr: 0x1f80,
        });
        let before = state.clone();
        assert!(step(&mut state, &mut memory, AccessContext::default()).is_err());
        assert_eq!(state, before);
        assert!(memory.accesses.is_empty());
        for (budget, stop_rip, expected_exit) in [
            (0, None, RunExit::InstructionBudgetExhausted),
            (1, Some(0x1000), RunExit::StopAddress),
        ] {
            let mut memory = Memory::at(&code, 0x1000);
            let mut state = LongModeState::default();
            state.rip = 0x1000;
            state.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr: 0x1f80,
            });
            let before = state.clone();
            let result = run(
                &mut state,
                &mut memory,
                RunConfig {
                    instruction_budget: budget,
                    stop_rip,
                    context: AccessContext::default(),
                },
                || false,
            );
            assert_eq!(result.exit, expected_exit);
            assert_eq!(result.instructions_executed, 0);
            assert_eq!(state, before);
            assert!(memory.accesses.is_empty());
        }
    }

