    #[test]
    fn psadbw_register_sums_absolute_unsigned_byte_differences_per_half_for_all_xmm_pairs() {
        let left = [
            0, 255, 10, 200, 128, 1, 0x55, 0xaa, 255, 255, 0, 0, 20, 40, 60, 80,
        ];
        let right = [
            255, 0, 20, 100, 128, 2, 0xaa, 0x55, 0, 0, 255, 255, 40, 20, 80, 60,
        ];
        let patterns = [
            (left, right),
            ([0; 16], [0; 16]),
            ([0; 16], [u8::MAX; 16]),
            ([0x80; 16], [0x7f; 16]),
        ];
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                for (lhs, rhs) in patterns {
                    let mut code = vec![0x66];
                    if destination >= 8 || source >= 8 {
                        code.push(rex);
                    }
                    code.extend([0x0f, 0xf6, modrm]);
                    let mut memory = Memory::at(&code, 0x1000);
                    let mut state = LongModeState::default();
                    state.x87 = Some(X87State::fixture_seed());
                    state.sse = Some(SseState {
                        xmm: [[0xa5; 16]; 16],
                        mxcsr: 0xe1a5_5a7e,
                    });
                    state.sse.as_mut().unwrap().xmm[destination as usize] = lhs;
                    if source != destination {
                        state.sse.as_mut().unwrap().xmm[source as usize] = rhs;
                    }
                    state.rip = 0x1000;
                    state.rflags = 0x8d7 | crate::DF;
                    let before = state.clone();
                    let old_source = if source == destination { lhs } else { rhs };
                    let mut expected = [0; 16];
                    for half in 0..2 {
                        let start = half * 8;
                        let sum: u16 = lhs[start..start + 8]
                            .iter()
                            .zip(&old_source[start..start + 8])
                            .map(|(a, b)| u16::from(a.abs_diff(*b)))
                            .sum();
                        expected[start..start + 2].copy_from_slice(&sum.to_le_bytes());
                    }
                    assert_eq!(
                        step(&mut state, &mut memory, AccessContext::default()).unwrap(),
                        StepOutcome::Advanced
                    );
                    let mut unchanged = before;
                    unchanged.rip += code.len() as u64;
                    unchanged.sse.as_mut().unwrap().xmm[destination as usize] = expected;
                    assert_eq!(state, unchanged, "dest={destination}, src={source}");
                    assert!(memory.accesses.is_empty(), "PSADBW performed a data access");
                }
            }
        }
    }

    #[test]
    fn pmovmskb_xmm_to_gpr_builds_byte_sign_mask_and_zero_extends_for_all_register_pairs() {
        let mut patterns: Vec<[u8; 16]> = [0x0000u16, 0xffff, 0x5555, 0xaaaa]
            .into_iter()
            .map(|mask| std::array::from_fn(|i| if mask & (1 << i) != 0 { 0x80 } else { 0x7f }))
            .collect();
        for bit in 0..16 {
            patterns.extend([
                std::array::from_fn(|i| if i == bit { 0x80 } else { 0 }),
                std::array::from_fn(|i| if i == bit { 0x80 } else { 0x7f }),
            ]);
        }
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                for xmm in &patterns {
                    let mut code = vec![0x66];
                    if destination >= 8 || source >= 8 {
                        code.push(rex);
                    }
                    code.extend([0x0f, 0xd7, modrm]);
                    let mut memory = Memory::at(&code, 0x1000);
                    let mut state = LongModeState::default();
                    state.x87 = Some(X87State::fixture_seed());
                    state.sse = Some(SseState {
                        xmm: [[0xa5; 16]; 16],
                        mxcsr: 0xe1a5_5a7e,
                    });
                    state.sse.as_mut().unwrap().xmm[source as usize] = *xmm;
                    state.gpr[destination as usize] = 0xdead_beef_1234_5678;
                    state.rip = 0x1000;
                    state.rflags = 0x8d7 | crate::DF;
                    let before = state.clone();
                    let expected = xmm
                        .iter()
                        .enumerate()
                        .fold(0u32, |mask, (i, byte)| mask | (u32::from(byte >> 7) << i));
                    assert_eq!(
                        step(&mut state, &mut memory, AccessContext::default()).unwrap(),
                        StepOutcome::Advanced
                    );
                    let mut unchanged = before;
                    unchanged.rip += code.len() as u64;
                    unchanged.gpr[destination as usize] = u64::from(expected);
                    assert_eq!(
                        state, unchanged,
                        "gpr={destination}, xmm={source}, bytes={xmm:02x?}"
                    );
                    assert!(
                        memory.accesses.is_empty(),
                        "PMOVMSKB performed a data access"
                    );
                }
            }
        }
    }

