    #[test]
    fn psraw_immediate_honors_all_unsigned_counts_on_every_xmm_and_preserves_side_state() {
        for destination in 0..16u8 {
            for count in 0..=u8::MAX {
                let mut code = vec![0x66];
                if destination >= 8 {
                    code.push(0x41);
                }
                code.extend([0x0f, 0x71, 0xe0 | (destination & 7), count]);
                let mut memory = Memory::at(&code, 0x1000);
                let mut state = LongModeState::default();
                state.rip = 0x1000;
                state.rflags = 0x8d7 | crate::DF;
                state.x87 = Some(X87State::fixture_seed());
                let original: [u8; 16] = [
                    0x00, 0x80, 0xff, 0xff, 0xfd, 0xff, 0xff, 0x7f, 0x00, 0x80, 0x01, 0x00, 0x01,
                    0x00, 0xff, 0x7f,
                ];
                let mut xmm_state = [[0x5a; 16]; 16];
                xmm_state[usize::from(destination)] = original;
                state.sse = Some(SseState {
                    xmm: xmm_state,
                    mxcsr: 0x1f80,
                });
                let before = state.clone();
                let expected: [u8; 16] = std::array::from_fn(|index| {
                    let lane = index / 2;
                    let value = i16::from_le_bytes([original[lane * 2], original[lane * 2 + 1]]);
                    // Independent widened floor-division reference for signed arithmetic shift.
                    let result = if count >= 16 {
                        if value < 0 { -1i16 } else { 0i16 }
                    } else {
                        (i32::from(value).div_euclid(1i32 << count)) as i16
                    };
                    result.to_le_bytes()[index % 2]
                });
                assert_eq!(
                    step(&mut state, &mut memory, AccessContext::default()).unwrap(),
                    StepOutcome::Advanced
                );
                let mut unchanged = before;
                unchanged.rip += code.len() as u64;
                unchanged.sse.as_mut().unwrap().xmm[usize::from(destination)] = expected;
                assert_eq!(state, unchanged, "dest={destination} count={count}");
                assert!(memory.accesses.is_empty());
            }
        }
    }

