    #[test]
    fn movss_register_copies_low_dword_and_preserves_all_other_state() {
        for opcode in [0x10, 0x11] {
            for destination in 0..16u8 {
                for source in 0..16u8 {
                    let (reg, rm) = if opcode == 0x10 {
                        (destination, source)
                    } else {
                        (source, destination)
                    };
                    let rex = 0x40 | ((reg >> 3) << 2) | (rm >> 3);
                    let modrm = 0xc0 | ((reg & 7) << 3) | (rm & 7);
                    let code = [0xf3, rex, 0x0f, opcode, modrm];
                    let mut memory = Memory::at(&code, 0x1000);
                    let mut state = LongModeState::default();
                    state.rip = 0x1000;
                    state.rflags = crate::DF | 2;
                    state.gpr[Register::Rcx as usize] = 0x1234;
                    state.x87 = Some(X87State::fixture_seed());
                    let mut xmm = [[0u8; 16]; 16];
                    for (register, bytes) in xmm.iter_mut().enumerate() {
                        for (index, byte) in bytes.iter_mut().enumerate() {
                            *byte = (register as u8).wrapping_mul(16).wrapping_add(index as u8);
                        }
                    }
                    state.sse = Some(SseState { xmm, mxcsr: 0x1f80 });
                    let before = state.clone();
                    assert_eq!(
                        step(&mut state, &mut memory, AccessContext::default()).unwrap(),
                        StepOutcome::Advanced
                    );
                    assert_eq!(state.rip, 0x1005);
                    assert_eq!(state.gpr, before.gpr);
                    assert_eq!(state.rflags, before.rflags);
                    assert_eq!(state.x87, before.x87);
                    assert_eq!(
                        state.sse.as_ref().unwrap().mxcsr,
                        before.sse.as_ref().unwrap().mxcsr
                    );
                    for register in 0..16usize {
                        let actual = &state.sse.as_ref().unwrap().xmm[register];
                        let original = &before.sse.as_ref().unwrap().xmm[register];
                        if register == usize::from(destination) {
                            assert_eq!(
                                &actual[..4],
                                &before.sse.as_ref().unwrap().xmm[usize::from(source)][..4]
                            );
                            assert_eq!(&actual[4..], &original[4..]);
                        } else {
                            assert_eq!(actual, original);
                        }
                    }
                    assert!(memory.accesses.is_empty());
                }
            }
        }

        for code in [&[0xf3, 0x0f, 0x10, 0xc1][..], &[0xf3, 0x0f, 0x11, 0xc1][..]] {
            for (x87, sse) in [
                (
                    None,
                    Some(SseState {
                        xmm: [[0x5a; 16]; 16],
                        mxcsr: 0x1f80,
                    }),
                ),
                (Some(X87State::fixture_seed()), None),
            ] {
                let mut memory = Memory::at(&code, 0x1000);
                let mut state = LongModeState::default();
                state.rip = 0x1000;
                state.x87 = x87;
                state.sse = sse;
                let before = state.clone();
                assert!(matches!(
                    step(&mut state, &mut memory, AccessContext::default()),
                    Ok(StepOutcome::Unsupported { .. })
                ));
                assert_eq!(state, before);
                assert!(memory.accesses.is_empty());
            }
        }

        for code in [
            &[0xf3, 0x45, 0x0f, 0x10, 0xc1][..],
            &[0xf3, 0x45, 0x0f, 0x11, 0xc1][..],
        ] {
            for length in 1..5 {
                let mut memory = Memory::at(&code[..length], 0x1000);
                let mut state = LongModeState::default();
                state.rip = 0x1000;
                state.x87 = Some(X87State::fixture_seed());
                state.sse = Some(SseState {
                    xmm: [[0x5a; 16]; 16],
                    mxcsr: 0x1f80,
                });
                let before = state.clone();
                assert_ne!(
                    step(&mut state, &mut memory, AccessContext::default()),
                    Ok(StepOutcome::Advanced)
                );
                assert_eq!(state, before);
                assert!(memory.accesses.is_empty());
            }

            for (budget, stop_rip, expected_exit, retired) in [
                (0, None, RunExit::InstructionBudgetExhausted, 0),
                (1, Some(0x1000), RunExit::StopAddress, 0),
                (1, Some(0x1005), RunExit::StopAddress, 1),
            ] {
                let mut memory = Memory::at(code, 0x1000);
                let mut state = LongModeState::default();
                state.rip = 0x1000;
                state.x87 = Some(X87State::fixture_seed());
                state.sse = Some(SseState {
                    xmm: [[0x5a; 16]; 16],
                    mxcsr: 0x1f80,
                });
                let result = run(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: budget,
                        stop_rip,
                        context: AccessContext::default(),
                    },
                    || false,
                );
                assert_eq!(result.exit, expected_exit);
                assert_eq!(result.instructions_executed, retired);
            }
        }
    }

    #[test]
    fn rsqrtss_register_updates_only_destination_low_dword_without_data_accesses() {
        use crate::binary_float::Binary32;

        let source_bits: [u32; 16] = [
            0x0000_0000, // +0
            0x8000_0000, // -0
            0x0000_0001, // subnormal
            0x3f80_0000, // 1
            0x4080_0000, // 4
            0x7f80_0000, // +infinity
            0xff80_0000, // -infinity
            0x7f80_0001, // SNaN
            0x7fc1_2345, // QNaN
            0xffc5_4321, // negative QNaN
            0x0080_0000, // minimum normal
            0x7f7f_ffff, // maximum finite
            0x4000_0000, // 2
            0x4040_0000, // 3
            0xbf80_0000, // -1
            0xbf00_0000, // -0.5
        ];
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let code = [0xf3, rex, 0x0f, 0x52, modrm];
                let mut memory = Memory::at(&code, 0x1000);
                let mut state = LongModeState::default();
                state.rip = 0x1000;
                state.rflags = crate::DF | 2;
                state.gpr[Register::Rcx as usize] = 0x1234_5678_9abc_def0;
                state.x87 = Some(X87State::fixture_seed());
                let mut xmm = [[0x5a; 16]; 16];
                for (register, bytes) in xmm.iter_mut().enumerate() {
                    let bits = source_bits[register];
                    bytes[..4].copy_from_slice(&bits.to_le_bytes());
                }
                state.sse = Some(SseState {
                    xmm,
                    mxcsr: 0x0000_ffff,
                });
                let before = state.clone();
                let expected_bits = Binary32::from_bits(source_bits[usize::from(source)])
                    .reciprocal_sqrt_sse_raw()
                    .to_bits();
                let mut expected_state = before.clone();
                expected_state.rip = 0x1005;
                expected_state.sse.as_mut().unwrap().xmm[usize::from(destination)][..4]
                    .copy_from_slice(&expected_bits.to_le_bytes());

                assert_eq!(
                    step(&mut state, &mut memory, AccessContext::default()).unwrap(),
                    StepOutcome::Advanced
                );
                assert_eq!(state.rip, 0x1005);
                assert_eq!(state.gpr, before.gpr);
                assert_eq!(state.rflags, before.rflags);
                assert_eq!(state.x87, before.x87);
                assert_eq!(
                    state.sse.as_ref().unwrap().mxcsr,
                    before.sse.as_ref().unwrap().mxcsr
                );
                assert_eq!(state, expected_state);
                for register in 0..16usize {
                    let actual = &state.sse.as_ref().unwrap().xmm[register];
                    let original = &before.sse.as_ref().unwrap().xmm[register];
                    if register == usize::from(destination) {
                        assert_eq!(&actual[..4], &expected_bits.to_le_bytes());
                        assert_eq!(&actual[4..], &original[4..]);
                    } else {
                        assert_eq!(actual, original);
                    }
                }
                assert!(memory.accesses.is_empty());
                assert_eq!(memory.fetches, (0x1000..0x1005).collect::<Vec<_>>());
            }
        }
    }

