    #[test]
    fn xorpd_prerequisite_fault_priority_matrix_is_atomic_at_every_cpl() {
        for privilege in [
            PrivilegeLevel::Ring0,
            PrivilegeLevel::Ring1,
            PrivilegeLevel::Ring2,
            PrivilegeLevel::Ring3,
        ] {
            for bits in 0..16u8 {
                let controls = XorpdPrerequisiteState {
                    sse2_available: bits & 1 != 0,
                    cr0_em: bits & 2 != 0,
                    cr0_ts: bits & 4 != 0,
                    cr4_osfxsr: bits & 8 != 0,
                };
                let mut memory = Memory::at(&[0x66, 0x0f, 0x57, 0xc1], 0x2000);
                let mut state = LongModeState::default();
                state.rip = 0x2000;
                state.rflags = 0x0cd7 | crate::DF;
                state.x87 = Some(X87State::fixture_seed());
                state.sse = Some(SseState {
                    xmm: std::array::from_fn(|register| {
                        std::array::from_fn(|byte| (register * 31 + byte * 7) as u8)
                    }),
                    mxcsr: 0xa5a5_1f80,
                });
                let before = state.clone();
                let result = run_with_xorpd_prerequisites(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(0x2004),
                        context: AccessContext {
                            privilege,
                            ..AccessContext::default()
                        },
                    },
                    controls,
                    || false,
                );
                let expected_vector =
                    if !controls.sse2_available || controls.cr0_em || !controls.cr4_osfxsr {
                        Some(6)
                    } else if controls.cr0_ts {
                        Some(7)
                    } else {
                        None
                    };
                match expected_vector {
                    Some(vector) => {
                        assert_eq!(
                            result.exit,
                            RunExit::Fault(ArchitecturalFault {
                                vector,
                                error_code: None,
                                linear_address: None,
                            }),
                            "CPL={privilege:?}, controls={controls:?}"
                        );
                        assert_eq!(result.instructions_executed, 0);
                        assert_eq!(state, before);
                    }
                    None => {
                        assert_eq!(result.exit, RunExit::StopAddress);
                        assert_eq!(result.instructions_executed, 1);
                        let mut expected = before.clone();
                        expected.rip = 0x2004;
                        expected.sse.as_mut().unwrap().xmm[0] = std::array::from_fn(|index| {
                            before.sse.as_ref().unwrap().xmm[0][index]
                                ^ before.sse.as_ref().unwrap().xmm[1][index]
                        });
                        assert_eq!(state, expected);
                    }
                }
                assert_eq!(memory.fetches, [0x2000, 0x2001, 0x2002, 0x2003]);
                assert!(memory.accesses.is_empty());
            }
        }
    }

    #[test]
    fn minss_invalid_prerequisites_and_arithmetic_exits_have_distinct_state_effects() {
        for privilege in [
            PrivilegeLevel::Ring0,
            PrivilegeLevel::Ring1,
            PrivilegeLevel::Ring2,
            PrivilegeLevel::Ring3,
        ] {
            for bits in 0..32u8 {
                let controls = MinssInvalidControls {
                    sse_available: bits & 1 != 0,
                    cr0_em: bits & 2 != 0,
                    cr0_ts: bits & 4 != 0,
                    cr4_osfxsr: bits & 8 != 0,
                    cr4_osxmmexcpt: bits & 16 != 0,
                };
                let code = [0xf3, 0x0f, 0x5d, 0xc1];
                let mut memory = Memory::at(&code, 0x2000);
                let mut state = LongModeState::default();
                state.rip = 0x2000;
                state.x87 = Some(X87State::fixture_seed());
                state.sse = Some(SseState {
                    xmm: [[0x5a; 16]; 16],
                    mxcsr: 0x1f80,
                });
                let before = state.clone();
                let result = run_with_minss_invalid_controls(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(0x2004),
                        context: AccessContext {
                            privilege,
                            ..AccessContext::default()
                        },
                    },
                    controls,
                    || false,
                );
                let expected = if !controls.sse_available || controls.cr0_em || !controls.cr4_osfxsr
                {
                    Some(6)
                } else if controls.cr0_ts {
                    Some(7)
                } else {
                    None
                };
                if let Some(vector) = expected {
                    assert_eq!(
                        result.exit,
                        RunExit::Fault(ArchitecturalFault {
                            vector,
                            error_code: None,
                            linear_address: None
                        })
                    );
                    assert_eq!(result.instructions_executed, 0);
                    assert_eq!(state, before, "CPL={privilege:?}, controls={controls:?}");
                } else {
                    assert_eq!(result.exit, RunExit::StopAddress);
                    assert_eq!(result.instructions_executed, 1);
                    assert_eq!(state.rip, 0x2004);
                    assert_eq!(
                        state.sse.as_ref().unwrap().xmm[0][..4],
                        before.sse.as_ref().unwrap().xmm[0][..4]
                    );
                    assert_eq!(
                        state.sse.as_ref().unwrap().mxcsr,
                        before.sse.as_ref().unwrap().mxcsr
                    );
                    assert_eq!(
                        &state.sse.as_ref().unwrap().xmm[0][4..],
                        &before.sse.as_ref().unwrap().xmm[0][4..]
                    );
                }
                assert!(memory.accesses.is_empty());
            }
        }

        let nans = [0x7fc1_2345u32, 0xffc5_4321, 0x7f81_2345, 0xff80_0001];
        for lhs in nans {
            for rhs in nans {
                for rc in 0..4u32 {
                    for prior_sticky in [0, 0x3f] {
                        for (osxmmexcpt, vector) in [(false, 6), (true, 19)] {
                            let code = [0xf3, 0x0f, 0x5d, 0xc1];
                            let mut memory = Memory::at(&code, 0x3000);
                            let mut state = LongModeState::default();
                            state.rip = 0x3000;
                            state.x87 = Some(X87State::fixture_seed());
                            let mut xmm = [[0x5a; 16]; 16];
                            xmm[0][..4].copy_from_slice(&lhs.to_le_bytes());
                            xmm[1][..4].copy_from_slice(&rhs.to_le_bytes());
                            let mxcsr = 0x1f00 | (rc << 13) | prior_sticky;
                            state.sse = Some(SseState { xmm, mxcsr });
                            let before = state.clone();
                            let controls = MinssInvalidControls {
                                sse_available: true,
                                cr0_em: false,
                                cr0_ts: false,
                                cr4_osfxsr: true,
                                cr4_osxmmexcpt: osxmmexcpt,
                            };
                            let result = run_with_minss_invalid_controls(
                                &mut state,
                                &mut memory,
                                RunConfig {
                                    instruction_budget: 1,
                                    stop_rip: Some(0x3004),
                                    context: AccessContext::default(),
                                },
                                controls,
                                || false,
                            );
                            assert_eq!(
                                result.exit,
                                RunExit::Fault(ArchitecturalFault {
                                    vector,
                                    error_code: None,
                                    linear_address: None
                                })
                            );
                            assert_eq!(result.instructions_executed, 0);
                            assert_eq!(state.rip, before.rip);
                            assert_eq!(state.sse.as_ref().unwrap().mxcsr, mxcsr | 1);
                            assert_eq!(
                                state.sse.as_ref().unwrap().xmm,
                                before.sse.as_ref().unwrap().xmm
                            );
                            assert_eq!(state.x87, before.x87);
                            assert!(memory.accesses.is_empty());
                        }
                    }
                }
            }
        }

        // A sticky IE from an earlier instruction is not a new invalid event.
        for rc in 0..4u32 {
            let code = [0xf3, 0x0f, 0x5d, 0xc1];
            let mut memory = Memory::at(&code, 0x4000);
            let mut state = LongModeState::default();
            state.rip = 0x4000;
            state.x87 = Some(X87State::fixture_seed());
            let mut xmm = [[0x5a; 16]; 16];
            xmm[0][..4].copy_from_slice(&1.0f32.to_bits().to_le_bytes());
            xmm[1][..4].copy_from_slice(&2.0f32.to_bits().to_le_bytes());
            state.sse = Some(SseState {
                xmm,
                mxcsr: 0x1f81 | (rc << 13),
            });
            let controls = MinssInvalidControls {
                sse_available: true,
                cr0_em: false,
                cr0_ts: false,
                cr4_osfxsr: true,
                cr4_osxmmexcpt: false,
            };
            let result = run_with_minss_invalid_controls(
                &mut state,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(0x4004),
                    context: AccessContext::default(),
                },
                controls,
                || false,
            );
            assert_eq!(result.exit, RunExit::StopAddress);
            assert_eq!(state.sse.as_ref().unwrap().mxcsr, 0x1f81 | (rc << 13));
        }
    }

    #[test]
    fn minss_invalid_controls_preserve_stop_budget_fetch_and_exact_form_order() {
        let controls = MinssInvalidControls {
            sse_available: false,
            cr0_em: false,
            cr0_ts: true,
            cr4_osfxsr: false,
            cr4_osxmmexcpt: false,
        };
        for (code, budget, stop, expected) in [
            (
                &[0xf3, 0x0f, 0x5d, 0xc1][..],
                1,
                Some(0x2000),
                RunExit::StopAddress,
            ),
            (
                &[0xf3, 0x0f, 0x5d, 0xc1][..],
                0,
                None,
                RunExit::InstructionBudgetExhausted,
            ),
            (
                &[0xf3, 0x0f, 0x5d][..],
                1,
                None,
                RunExit::MemoryError(MemoryError::Unmapped {
                    address: 0x2003,
                    access: AccessKind::Fetch,
                }),
            ),
            (
                &[0xf3, 0x0f, 0x5d, 0xc0][..],
                1,
                None,
                RunExit::Unsupported { opcode: 0x5d },
            ),
            (
                &[0xf3, 0x45, 0x0f, 0x5d, 0xc1][..],
                1,
                None,
                RunExit::Unsupported { opcode: 0x5d },
            ),
        ] {
            let mut memory = Memory::at(code, 0x2000);
            let mut state = LongModeState::default();
            state.rip = 0x2000;
            state.x87 = Some(X87State::fixture_seed());
            state.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr: 0x1f00,
            });
            let before = state.clone();
            let result = run_with_minss_invalid_controls(
                &mut state,
                &mut memory,
                RunConfig {
                    instruction_budget: budget,
                    stop_rip: stop,
                    context: AccessContext::default(),
                },
                controls,
                || false,
            );
            assert_eq!(result.exit, expected);
            assert_eq!(state, before);
            assert!(memory.accesses.is_empty());
        }
    }

    #[test]
    fn minss_invalid_controls_reuse_masked_result_for_noninvalid_scalar_classes() {
        use crate::binary_float::{Binary32, BinaryClass};

        for (lhs, rhs) in [
            (0x3f80_0000u32, 0x4000_0000u32), // finite
            (0x0000_0000, 0x8000_0000),       // signed zero
            (0x7f80_0000, 0xff80_0000),       // infinities
            (0x0000_0001, 0x3f80_0000),       // masked denormal operand
        ] {
            for rc in 0..4u32 {
                let code = [0xf3, 0x0f, 0x5d, 0xc1];
                let mut memory = Memory::at(&code, 0x5000);
                let mut state = LongModeState::default();
                state.rip = 0x5000;
                state.x87 = Some(X87State::fixture_seed());
                let mut xmm = [[0x5a; 16]; 16];
                xmm[0][..4].copy_from_slice(&lhs.to_le_bytes());
                xmm[1][..4].copy_from_slice(&rhs.to_le_bytes());
                let mxcsr = 0x1f00 | (rc << 13);
                state.sse = Some(SseState { xmm, mxcsr });
                let expected = Binary32::min_sse_raw_result(
                    Binary32::from_bits(lhs),
                    Binary32::from_bits(rhs),
                );
                assert!(!expected.invalid_operation());
                let expected_de = (Binary32::from_bits(lhs).class() == BinaryClass::Subnormal
                    || Binary32::from_bits(rhs).class() == BinaryClass::Subnormal)
                    as u32;
                let controls = MinssInvalidControls {
                    sse_available: true,
                    cr0_em: false,
                    cr0_ts: false,
                    cr4_osfxsr: true,
                    cr4_osxmmexcpt: false,
                };
                let result = run_with_minss_invalid_controls(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(0x5004),
                        context: AccessContext::default(),
                    },
                    controls,
                    || false,
                );
                assert_eq!(result.exit, RunExit::StopAddress);
                assert_eq!(
                    state.sse.as_ref().unwrap().xmm[0][..4],
                    expected.value().to_bits().to_le_bytes()
                );
                assert_eq!(
                    state.sse.as_ref().unwrap().mxcsr,
                    mxcsr | (expected_de << 1)
                );
            }
        }
    }

    #[test]
    fn minss_unmasked_denormal_faults_without_retirement_and_commits_de_only() {
        for subnormal in [
            0x0000_0001u32,
            0x0000_0002,
            0x007f_ffff,
            0x8000_0001,
            0x807f_ffff,
        ] {
            for neighbor in [
                0x0000_0000u32,
                0x8000_0000,
                0x0080_0000,
                0x8080_0000,
                0x7f80_0000,
                0xff80_0000,
                0x3f80_0000,
            ] {
                for (lhs, rhs) in [(subnormal, neighbor), (neighbor, subnormal)] {
                    for im in [false, true] {
                        for osxmmexcpt in [false, true] {
                            let code = [0xf3, 0x0f, 0x5d, 0xc1];
                            let mut memory = Memory::at(&code, 0x6000);
                            let mut state = LongModeState::default();
                            state.rip = 0x6000;
                            state.x87 = Some(X87State::fixture_seed());
                            let mut xmm = [[0x5a; 16]; 16];
                            xmm[0][..4].copy_from_slice(&lhs.to_le_bytes());
                            xmm[1][..4].copy_from_slice(&rhs.to_le_bytes());
                            let mxcsr = 0x1e05 | (u32::from(im) << 7) | (3 << 13);
                            state.sse = Some(SseState { xmm, mxcsr });
                            let before = state.clone();
                            let controls = MinssInvalidControls {
                                sse_available: true,
                                cr0_em: false,
                                cr0_ts: false,
                                cr4_osfxsr: true,
                                cr4_osxmmexcpt: osxmmexcpt,
                            };
                            let result = run_with_minss_unmasked_denormal_controls(
                                &mut state,
                                &mut memory,
                                RunConfig {
                                    instruction_budget: 1,
                                    stop_rip: Some(0x6004),
                                    context: AccessContext::default(),
                                },
                                controls,
                                || false,
                            );
                            assert_eq!(
                                result.exit,
                                RunExit::Fault(ArchitecturalFault {
                                    vector: if osxmmexcpt { 19 } else { 6 },
                                    error_code: None,
                                    linear_address: None,
                                })
                            );
                            assert_eq!(result.instructions_executed, 0);
                            assert_eq!(state.rip, before.rip);
                            assert_eq!(state.sse.as_ref().unwrap().mxcsr, mxcsr | 2);
                            assert_eq!(
                                state.sse.as_ref().unwrap().xmm,
                                before.sse.as_ref().unwrap().xmm
                            );
                            assert_eq!(state.x87, before.x87);
                            assert!(memory.accesses.is_empty());
                        }
                    }
                }
            }
        }

        // Masking DE permits a real subnormal event to retire with DE sticky.
        for im in [false, true] {
            for osxmmexcpt in [false, true] {
                let code = [0xf3, 0x0f, 0x5d, 0xc1];
                let mut memory = Memory::at(&code, 0x6080);
                let mut state = LongModeState::default();
                state.rip = 0x6080;
                state.x87 = Some(X87State::fixture_seed());
                let mut xmm = [[0x5a; 16]; 16];
                xmm[0][..4].copy_from_slice(&0x0000_0001u32.to_le_bytes());
                xmm[1][..4].copy_from_slice(&1.0f32.to_bits().to_le_bytes());
                let mxcsr = 0x1f05 | (u32::from(im) << 7);
                state.sse = Some(SseState { xmm, mxcsr });
                let result = run_with_minss_unmasked_denormal_controls(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(0x6084),
                        context: AccessContext::default(),
                    },
                    MinssInvalidControls {
                        sse_available: true,
                        cr0_em: false,
                        cr0_ts: false,
                        cr4_osfxsr: true,
                        cr4_osxmmexcpt: osxmmexcpt,
                    },
                    || false,
                );
                assert_eq!(result.exit, RunExit::StopAddress);
                assert_eq!(result.instructions_executed, 1);
                assert_eq!(state.sse.as_ref().unwrap().mxcsr, mxcsr | 2);
            }
        }

        // Prior DE alone is sticky state, not a new unmasked event.
        let code = [0xf3, 0x0f, 0x5d, 0xc1];
        let mut memory = Memory::at(&code, 0x6100);
        let mut state = LongModeState::default();
        state.rip = 0x6100;
        state.x87 = Some(X87State::fixture_seed());
        let mut xmm = [[0x5a; 16]; 16];
        xmm[0][..4].copy_from_slice(&1.0f32.to_bits().to_le_bytes());
        xmm[1][..4].copy_from_slice(&2.0f32.to_bits().to_le_bytes());
        state.sse = Some(SseState { xmm, mxcsr: 0x1e82 });
        let result = run_with_minss_unmasked_denormal_controls(
            &mut state,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: Some(0x6104),
                context: AccessContext::default(),
            },
            MinssInvalidControls {
                sse_available: true,
                cr0_em: false,
                cr0_ts: false,
                cr4_osfxsr: true,
                cr4_osxmmexcpt: false,
            },
            || false,
        );
        assert_eq!(result.exit, RunExit::StopAddress);
        assert_eq!(result.instructions_executed, 1);
        assert_eq!(state.sse.as_ref().unwrap().mxcsr, 0x1e82);
    }

    #[test]
    fn minss_unmasked_denormal_obeys_invalid_priority_and_mixed_masks() {
        for nan in [0x7fc1_2345u32, 0xff81_2345] {
            for (lhs, rhs) in [(nan, 0x0000_0001), (0x8000_0001, nan)] {
                for im in [false, true] {
                    for dm in [false, true] {
                        for osxmmexcpt in [false, true] {
                            let code = [0xf3, 0x0f, 0x5d, 0xc1];
                            let mut memory = Memory::at(&code, 0x6200);
                            let mut state = LongModeState::default();
                            state.rip = 0x6200;
                            state.x87 = Some(X87State::fixture_seed());
                            let mut xmm = [[0x5a; 16]; 16];
                            xmm[0][..4].copy_from_slice(&lhs.to_le_bytes());
                            xmm[1][..4].copy_from_slice(&rhs.to_le_bytes());
                            let mxcsr = 0x1e00
                                | (u32::from(im) << 7)
                                | (u32::from(dm) << 8)
                                | (2 << 13)
                                | 0x10;
                            state.sse = Some(SseState { xmm, mxcsr });
                            let before = state.clone();
                            let result = run_with_minss_unmasked_denormal_controls(
                                &mut state,
                                &mut memory,
                                RunConfig {
                                    instruction_budget: 1,
                                    stop_rip: Some(0x6204),
                                    context: AccessContext::default(),
                                },
                                MinssInvalidControls {
                                    sse_available: true,
                                    cr0_em: false,
                                    cr0_ts: false,
                                    cr4_osfxsr: true,
                                    cr4_osxmmexcpt: osxmmexcpt,
                                },
                                || false,
                            );
                            let should_fault = !im || !dm;
                            if should_fault {
                                assert_eq!(
                                    result.exit,
                                    RunExit::Fault(ArchitecturalFault {
                                        vector: if osxmmexcpt { 19 } else { 6 },
                                        error_code: None,
                                        linear_address: None,
                                    })
                                );
                                assert_eq!(result.instructions_executed, 0);
                                assert_eq!(state.rip, before.rip);
                                assert_eq!(
                                    state.sse.as_ref().unwrap().xmm,
                                    before.sse.as_ref().unwrap().xmm
                                );
                                let flags = 0x3;
                                assert_eq!(state.sse.as_ref().unwrap().mxcsr, mxcsr | flags);
                            } else {
                                assert_eq!(result.exit, RunExit::StopAddress);
                                assert_eq!(result.instructions_executed, 1);
                                assert_eq!(state.rip, 0x6204);
                                assert_eq!(state.sse.as_ref().unwrap().mxcsr, mxcsr | 1);
                                assert_eq!(
                                    state.sse.as_ref().unwrap().xmm[0][..4],
                                    rhs.to_le_bytes()
                                );
                            }
                            assert_eq!(state.x87, before.x87);
                        }
                    }
                }
            }
        }
    }

