    #[test]
    fn null_ds_es_loads_change_only_the_selected_visible_state() {
        for (code, change_ds, change_es) in [
            (&[0x8e, 0xd8][..], true, false),
            (&[0x8e, 0xc0][..], false, true),
            (&[0x8e, 0xd8, 0x8e, 0xc0][..], true, true),
            (&[0x8e, 0xd8, 0x8e, 0xd8][..], true, false),
        ] {
            let mut state = LongModeState {
                cr4: None,
                sti_shadow: None,
                ds_selector: 0x2b,
                es_selector: 0x30,
                cs_selector: None,
                cs_cache: None,
                ss_selector: None,
                ss_cache: None,
                ..LongModeState::default()
            };
            state.gpr[Register::Rax as usize] = 0xfeed_beef_0000_0000;
            state.rflags = 0x0cd7;
            let before = state.clone();
            let mut memory = Memory::new(code);
            let retired = (code.len() / 2) as u64;
            let result = run(
                &mut state,
                &mut memory,
                RunConfig {
                    instruction_budget: retired,
                    stop_rip: None,
                    context: AccessContext {
                        privilege: PrivilegeLevel::Ring0,
                        ..AccessContext::default()
                    },
                },
                || false,
            );
            assert_eq!(result.instructions_executed, retired, "{:?}", result.exit);
            assert_eq!(result.rflags_defined, crate::INTEGER_FLAGS);
            assert_eq!(state.rip, retired * 2);
            assert_eq!(state.gpr, before.gpr);
            assert_eq!(state.rflags, before.rflags);
            assert_eq!(state.fs_base, before.fs_base);
            assert_eq!(state.gs_base, before.gs_base);
            assert_eq!(state.fs_selector, before.fs_selector);
            assert_eq!(state.gs_selector, before.gs_selector);
            assert_eq!(state.ds_selector, if change_ds { 0 } else { 0x2b });
            assert_eq!(state.ds_unusable, change_ds);
            assert_eq!(state.es_selector, if change_es { 0 } else { 0x30 });
            assert_eq!(state.es_unusable, change_es);
            assert!(memory.accesses.is_empty());
        }
    }

    #[test]
    fn null_ds_es_loads_reject_neighbors_nonzero_ax_cpl_and_truncation() {
        for code in [
            &[0x66, 0x8e, 0xd8][..],
            &[0x48, 0x8e, 0xd8][..],
            &[0x8e, 0xd0][..],
            &[0x8e, 0xc8][..],
        ] {
            let mut state = LongModeState::default();
            let before = state.clone();
            let mut memory = Memory::new(code);
            assert_eq!(
                step(&mut state, &mut memory, AccessContext::default()),
                Ok(StepOutcome::Unsupported { opcode: 0x8e })
            );
            assert_eq!(state, before);
            assert!(memory.accesses.is_empty());
        }
        let mut nonzero = LongModeState::default();
        nonzero.gpr[Register::Rax as usize] = 0x10001;
        let before = nonzero.clone();
        let mut memory = Memory::new(&[0x8e, 0xd8]);
        assert_eq!(
            step(
                &mut nonzero,
                &mut memory,
                AccessContext {
                    privilege: PrivilegeLevel::Ring0,
                    ..AccessContext::default()
                }
            ),
            Ok(StepOutcome::Unsupported { opcode: 0x8e })
        );
        assert_eq!(nonzero, before);
        assert!(memory.accesses.is_empty());

        let mut user = LongModeState::default();
        let before = user.clone();
        let mut memory = Memory::new(&[0x8e, 0xd8]);
        assert_eq!(
            step(
                &mut user,
                &mut memory,
                AccessContext {
                    privilege: PrivilegeLevel::Ring3,
                    ..AccessContext::default()
                }
            ),
            Ok(StepOutcome::Unsupported { opcode: 0x8e })
        );
        assert_eq!(user, before);
        assert!(memory.accesses.is_empty());

        let mut truncated = LongModeState::default();
        let before = truncated.clone();
        let mut memory = Memory::new(&[0x8e]);
        assert_eq!(
            step(&mut truncated, &mut memory, AccessContext::default()),
            Err(MemoryError::Unmapped {
                address: 1,
                access: AccessKind::Fetch
            })
        );
        assert_eq!(truncated, before);
        assert!(memory.accesses.is_empty());
    }

    fn ds_descriptor(access: u8, base: u32, limit: u32, flags: u8) -> [u8; 8] {
        [
            limit as u8,
            (limit >> 8) as u8,
            base as u8,
            (base >> 8) as u8,
            (base >> 16) as u8,
            access,
            ((flags & 0x0f) << 4) | ((limit >> 16) as u8 & 0x0f),
            (base >> 24) as u8,
        ]
    }

    fn ds_load_state(selector: u64) -> LongModeState {
        let mut state = LongModeState {
            cr4: None,
            sti_shadow: None,
            ds_selector: 0x23,
            ds_unusable: false,
            ds_cache: Some(crate::state::DsDescriptorCache {
                base: 0xaaaa_aaaa,
                limit: 0x1234,
                access: 0x93,
                flags: 0,
            }),
            gdtr: Some(Gdtr {
                base: 0x1000,
                limit: 0x20,
            }),
            ..LongModeState::default()
        };
        state.rip = 0x400;
        state.gpr[Register::Rax as usize] = selector;
        state.gpr[Register::Rbx as usize] = 0x8877_6655_4433_2211;
        state.rflags = 0x0cd7;
        state
    }

    fn es_load_state(selector: u64) -> LongModeState {
        let mut state = ds_load_state(selector);
        state.fs_base = 0x0000_7fff_0000_1234;
        state.gs_base = 0x0000_7fff_0000_5678;
        state.fs_selector = 0x40;
        state.gs_selector = 0x48;
        state.fs_cache = Some(crate::FsDescriptorCache {
            limit: 0x1111,
            access: 0x93,
            flags: 0,
        });
        state.gs_cache = Some(crate::FsDescriptorCache {
            limit: 0x2222,
            access: 0x93,
            flags: 0,
        });
        state.es_selector = 0x30;
        state.es_unusable = false;
        state.es_cache = Some(crate::state::DataSegmentDescriptorCache {
            base: 0xbbbb_bbbb,
            limit: 0x4321,
            access: 0x93,
            flags: 0,
        });
        state
    }

    #[test]
    fn mov_ds_ax_loads_general_present_data_descriptors_and_caches_hidden_state() {
        for (selector, dpl) in [(0x18, 0), (0x1b, 3)] {
            let mut state = ds_load_state(0xfeed_beef_0000_0000 | selector);
            let mut memory = Memory::at(&[0x8e, 0xd8], 0x400);
            memory.bytes[24..32].copy_from_slice(&ds_descriptor(
                0x93 | ((dpl as u8) << 5),
                0x1234_5678,
                0xabcde,
                0,
            ));
            let before = state.clone();
            let mut expected = before.clone();
            expected.rip += 2;
            expected.ds_selector = selector as u16;
            expected.ds_unusable = false;
            expected.ds_cache = Some(crate::state::DsDescriptorCache {
                base: 0x1234_5678,
                limit: 0xabcde,
                access: 0x93 | ((dpl as u8) << 5),
                flags: 0,
            });
            assert_eq!(
                step(&mut state, &mut memory, lgdt_ring0()),
                Ok(StepOutcome::Advanced)
            );
            assert_eq!(state, expected);
            assert_eq!(memory.fetches, [0x400, 0x401]);
            assert_eq!(memory.accesses, [(AccessKind::Read, 0x1018, 8)]);
        }
    }

