    #[test]
    fn lgdt_then_mov_ds_caches_descriptor_while_long_mode_data_address_stays_flat() {
        let mut code = vec![0x0f, 0x01, 0x55, 0x00]; // LGDT [RBP]
        code.extend([0xb8, 0x18, 0, 0, 0]); // MOV EAX, 0x18
        code.extend([0x8e, 0xd8]); // MOV DS, AX
        code.extend([0x48, 0xb8, 0x00, 0x10, 0, 0, 0, 0, 0, 0]); // MOV RAX, 0x1000
        code.extend([0x48, 0x8b, 0x18]); // MOV RBX, [RAX]

        let mut state = LongModeState {
            cr4: None,
            sti_shadow: None,
            ds_cache: Some(crate::state::DsDescriptorCache {
                base: 0,
                limit: 0xffff,
                access: 0x93,
                flags: 0,
            }),
            gdtr: Some(Gdtr { base: 0, limit: 0 }),
            idtr: None,
            ..LongModeState::default()
        };
        state.rip = 0x400;
        state.gpr[Register::Rbp as usize] = 0x1008;
        let mut memory = Memory::at(&code, 0x400);
        memory.bytes[8..10].copy_from_slice(&0x1fu16.to_le_bytes());
        memory.bytes[10..18].copy_from_slice(&0x1000u64.to_le_bytes());
        memory.bytes[24..32].copy_from_slice(&ds_descriptor(0x92, 0x1234_5678, 0xffff, 0));

        let result = run(
            &mut state,
            &mut memory,
            RunConfig {
                instruction_budget: 5,
                stop_rip: Some(0x400 + code.len() as u64),
                context: lgdt_ring0(),
            },
            || false,
        );
        assert_eq!(result.exit, RunExit::StopAddress);
        assert_eq!(result.instructions_executed, 5);
        assert_eq!(state.ds_selector, 0x18);
        assert_eq!(state.ds_cache.unwrap().base, 0x1234_5678);
        assert_eq!(
            state.gpr[Register::Rbx as usize],
            u64::from_le_bytes([0, 1, 2, 3, 4, 5, 6, 7])
        );
        assert!(memory.accesses.contains(&(AccessKind::Read, 0x1000, 8)));
        memory.bytes[24..32].copy_from_slice(&ds_descriptor(0x93, 0x7654_3210, 0xffff, 0));
        assert_eq!(state.ds_cache.unwrap().base, 0x1234_5678);
    }

    #[test]
    fn psubusb_register_covers_all_xmm_pairs_and_preserves_full_state_without_data_access() {
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let mut code = vec![0x66];
                if destination >= 8 || source >= 8 {
                    code.push(rex);
                }
                code.extend([0x0f, 0xd8, modrm]);

                let mut memory = Memory::at(&code, 0x1000);
                let mut state = LongModeState::default();
                state.x87 = Some(X87State::fixture_seed());
                state.sse = Some(SseState {
                    xmm: [[0; 16]; 16],
                    mxcsr: 0x1f80,
                });
                state.rip = 0x1000;
                state.rflags = 0x8d7 | crate::DF;
                for register in 0..16usize {
                    for (lane, value) in state.sse.as_mut().unwrap().xmm[register]
                        .iter_mut()
                        .enumerate()
                    {
                        *value = (register as u8)
                            .wrapping_mul(29)
                            .wrapping_add((lane as u8).wrapping_mul(17));
                    }
                }

                let before = state.clone();
                let expected = std::array::from_fn(|lane| {
                    before.sse.as_ref().unwrap().xmm[destination as usize][lane]
                        .saturating_sub(before.sse.as_ref().unwrap().xmm[source as usize][lane])
                });
                assert_eq!(
                    step(&mut state, &mut memory, AccessContext::default()).unwrap(),
                    StepOutcome::Advanced
                );

                let mut unchanged = before.clone();
                unchanged.rip += code.len() as u64;
                unchanged.sse.as_mut().unwrap().xmm[destination as usize] = expected;
                assert_eq!(state, unchanged, "dest={destination}, src={source}");
                assert!(memory.accesses.is_empty(), "PSUBUSB performed data access");
            }
        }
    }

