    #[test]
    fn rdtsc_uses_injected_value_and_cr4_tsd_gates_source_atomically() {
        let value = 0xfedc_ba98_7654_3210;
        for privilege in [
            PrivilegeLevel::Ring0,
            PrivilegeLevel::Ring1,
            PrivilegeLevel::Ring2,
            PrivilegeLevel::Ring3,
        ] {
            for cr4_tsd in [false, true] {
                let mut state = LongModeState {
                    cr4: None,
                    sti_shadow: None,
                    rip: 0x1000,
                    rflags: 0x0cd7,
                    ..LongModeState::default()
                };
                for (index, register) in state.gpr.iter_mut().enumerate() {
                    *register = 0xdead_0000_0000_0000 | index as u64;
                }
                let before = state.clone();
                let mut memory = SepMemory::new(&[0x0f, 0x31], 0x1000);
                let mut calls = 0;
                let mut source = || {
                    calls += 1;
                    value
                };
                let result = run_with_rdtsc_source(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(0x1002),
                        context: AccessContext {
                            privilege,
                            ..AccessContext::default()
                        },
                    },
                    RdtscControls { cr4_tsd },
                    &mut source,
                    || false,
                );
                if cr4_tsd && privilege != PrivilegeLevel::Ring0 {
                    assert_eq!(
                        result.exit,
                        RunExit::Fault(ArchitecturalFault {
                            vector: 13,
                            error_code: Some(0),
                            linear_address: None,
                        })
                    );
                    assert_eq!(result.instructions_executed, 0);
                    assert_eq!(calls, 0);
                    assert_eq!(state, before);
                } else {
                    let mut expected = before;
                    expected.gpr[Register::Rax as usize] = 0x7654_3210;
                    expected.gpr[Register::Rdx as usize] = 0xfedc_ba98;
                    expected.rip = 0x1002;
                    assert_eq!(result.exit, RunExit::StopAddress);
                    assert_eq!(result.instructions_executed, 1);
                    assert_eq!(calls, 1);
                    assert_eq!(state, expected);
                }
                assert_eq!(memory.fetches, [0x1000, 0x1001]);
                assert_eq!(memory.data_accesses, 0);
            }
        }
    }

    #[test]
    fn rdtsc_legacy_prefix_and_boundary_paths_do_not_read_the_source() {
        let mut state = LongModeState {
            cr4: None,
            sti_shadow: None,
            rip: 0x1000,
            ..LongModeState::default()
        };
        let before = state.clone();
        let mut memory = SepMemory::new(&[0x0f, 0x31], 0x1000);
        let legacy = run(
            &mut state,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: None,
                context: AccessContext::default(),
            },
            || false,
        );
        assert_eq!(legacy.exit, RunExit::Unsupported { opcode: 0x31 });
        assert_eq!(legacy.instructions_executed, 0);
        assert_eq!(state, before);

        for (config, expected_exit) in [
            (
                RunConfig {
                    instruction_budget: 0,
                    stop_rip: None,
                    context: AccessContext::default(),
                },
                RunExit::InstructionBudgetExhausted,
            ),
            (
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(0x1000),
                    context: AccessContext::default(),
                },
                RunExit::StopAddress,
            ),
        ] {
            let mut calls = 0;
            let mut source = || {
                calls += 1;
                7
            };
            let mut memory = SepMemory::new(&[0x0f, 0x31], 0x1000);
            let result = run_with_rdtsc_source(
                &mut state,
                &mut memory,
                config,
                RdtscControls { cr4_tsd: false },
                &mut source,
                || false,
            );
            assert_eq!(result.exit, expected_exit);
            assert_eq!(calls, 0);
            assert_eq!(state, before);
            assert!(memory.fetches.is_empty());
        }

        for code in [&[0x48, 0x0f, 0x31][..], &[0xf3, 0x0f, 0x31][..]] {
            let mut state = LongModeState {
                cr4: None,
                sti_shadow: None,
                rip: 0x1000,
                ..LongModeState::default()
            };
            let before = state.clone();
            let mut memory = SepMemory::new(code, 0x1000);
            let mut calls = 0;
            let mut source = || {
                calls += 1;
                7
            };
            let result = run_with_rdtsc_source(
                &mut state,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: None,
                    context: AccessContext::default(),
                },
                RdtscControls { cr4_tsd: false },
                &mut source,
                || false,
            );
            assert!(matches!(result.exit, RunExit::Unsupported { opcode: 0x31 }));
            assert_eq!(calls, 0);
            assert_eq!(state, before);
        }

        let mut truncated_state = LongModeState {
            cr4: None,
            sti_shadow: None,
            rip: 0x1000,
            ..LongModeState::default()
        };
        let before = truncated_state.clone();
        let mut truncated = SepMemory::new(&[0x0f], 0x1000);
        let mut calls = 0;
        let mut source = || {
            calls += 1;
            7
        };
        let result = run_with_rdtsc_source(
            &mut truncated_state,
            &mut truncated,
            RunConfig {
                instruction_budget: 1,
                stop_rip: None,
                context: AccessContext::default(),
            },
            RdtscControls { cr4_tsd: false },
            &mut source,
            || false,
        );
        assert!(matches!(
            result.exit,
            RunExit::MemoryError(MemoryError::Unmapped {
                access: AccessKind::Fetch,
                ..
            })
        ));
        assert_eq!(calls, 0);
        assert_eq!(result.instructions_executed, 0);
        assert_eq!(truncated_state, before);
        assert_eq!(truncated.fetches, [0x1000, 0x1001]);
    }

    #[test]
    fn sep_disabled_legacy_prefix_neighbor_and_fetch_failures_fail_closed() {
        let profile = SepProfile::SepDisabledV1;
        for code in [
            &[0x0f, 0x34][..],
            &[0x0f, 0x35][..],
            &[0x48, 0x0f, 0x34][..],
            &[0xf3, 0x0f, 0x35][..],
            &[0xf0, 0x0f, 0x34][..],
            &[0xf0, 0x0f, 0x35][..],
            &[0x0f, 0x33][..],
        ] {
            let mut state = LongModeState::default();
            state.rip = 0x1000;
            let before = state.clone();
            let mut memory = SepMemory::new(code, 0x1000);
            let result = if code.len() == 2 && code[1] != 0x33 {
                step(&mut state, &mut memory, AccessContext::default())
            } else {
                step_with_sep_profile(&mut state, &mut memory, AccessContext::default(), &profile)
            };
            assert!(matches!(result, Ok(StepOutcome::Unsupported { .. })));
            assert_eq!(state, before);
            assert!(memory.data_accesses == 0);
        }

        let mut state = LongModeState::default();
        state.rip = 0x1000;
        let before = state.clone();
        let mut memory = SepMemory::new(&[0x0f, 0x34], 0x1000);
        let result = run(
            &mut state,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: None,
                context: AccessContext::default(),
            },
            || false,
        );
        assert_eq!(result.exit, RunExit::Unsupported { opcode: 0x34 });
        assert_eq!(result.instructions_executed, 0);
        assert_eq!(state, before);
        assert_eq!(memory.fetches, [0x1000, 0x1001]);
        assert_eq!(memory.data_accesses, 0);

        for length in 0..2 {
            let mut state = LongModeState::default();
            state.rip = 0x1000;
            let before = state.clone();
            let mut memory = SepMemory::new(&[0x0f, 0x34][..length], 0x1000);
            let result = run_with_sep_profile(
                &mut state,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: None,
                    context: AccessContext::default(),
                },
                &profile,
                || false,
            );
            assert!(matches!(
                result.exit,
                RunExit::MemoryError(MemoryError::Unmapped {
                    access: AccessKind::Fetch,
                    ..
                })
            ));
            assert_eq!(result.instructions_executed, 0);
            assert_eq!(state, before);
            assert!(memory.data_accesses == 0);
        }

        for offset in 0..2 {
            let mut state = LongModeState::default();
            state.rip = 0x1000;
            let before = state.clone();
            let expected = ArchitecturalFault {
                vector: 14,
                error_code: Some(0x24),
                linear_address: Some(0x1000 + offset),
            };
            let mut memory = SepMemory::new(&[0x0f, 0x34], 0x1000);
            memory.fetch_error = Some((
                0x1000 + offset,
                MemoryError::Architectural(expected.clone()),
            ));
            let result = run_with_sep_profile(
                &mut state,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: None,
                    context: AccessContext::default(),
                },
                &profile,
                || false,
            );
            assert_eq!(result.exit, RunExit::Fault(expected));
            assert_eq!(result.instructions_executed, 0);
            assert_eq!(state, before);
            assert_eq!(memory.fetches.len(), (offset + 1) as usize);
            assert!(memory.data_accesses == 0);
        }
    }

