    #[test]
    fn addpd_register_pairs_and_mxcsr_events_are_atomic() {
        let code = [0x66, 0x0f, 0x58, 0xc1];
        let controls = AddpdControls {
            sse2_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        let run = |state: &mut LongModeState, memory: &mut Memory| {
            run_with_addpd_register_controls(
                state,
                memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(state.rip + 4),
                    context: AccessContext::default(),
                },
                controls,
                || false,
            )
        };

        let mut state = LongModeState::default();
        state.rip = 0x27100;
        let mut xmm = [[0x5a; 16]; 16];
        xmm[0][..8].copy_from_slice(&0x3ff0_0000_0000_0000u64.to_le_bytes());
        xmm[0][8..].copy_from_slice(&0x3ff0_0000_0000_0000u64.to_le_bytes());
        xmm[1][..8].copy_from_slice(&0x3ca0_0000_0000_0000u64.to_le_bytes()); // 2^-53
        xmm[1][8..].copy_from_slice(&0x8000_0000_0000_0000u64.to_le_bytes()); // -0
        state.sse = Some(SseState { xmm, mxcsr: 0x1f80 });
        let mut memory = Memory::at(&code, state.rip);
        let result = run(&mut state, &mut memory);
        assert_eq!(result.exit, RunExit::StopAddress);
        assert_eq!(
            state.sse.as_ref().unwrap().xmm[0][..8],
            0x3ff0_0000_0000_0000u64.to_le_bytes()
        );
        assert_eq!(
            state.sse.as_ref().unwrap().xmm[0][8..],
            0x3ff0_0000_0000_0000u64.to_le_bytes()
        );
        assert_eq!(state.sse.as_ref().unwrap().mxcsr & 0x3f, 0x20);

        // Precision unmasked: status is committed but the whole destination
        // and RIP stay unchanged.
        let mut faulting = LongModeState::default();
        faulting.rip = 0x27100;
        let mut xmm = [[0x5a; 16]; 16];
        xmm[0][..8].copy_from_slice(&0x3ff0_0000_0000_0000u64.to_le_bytes());
        xmm[1][..8].copy_from_slice(&0x3ca0_0000_0000_0000u64.to_le_bytes());
        faulting.sse = Some(SseState { xmm, mxcsr: 0x0f80 });
        let old_destination = faulting.sse.as_ref().unwrap().xmm[0];
        let mut memory = Memory::at(&code, faulting.rip);
        let result = run(&mut faulting, &mut memory);
        assert_eq!(
            result.exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 19,
                error_code: None,
                linear_address: None,
            })
        );
        assert_eq!(faulting.sse.as_ref().unwrap().xmm[0], old_destination);
        assert_eq!(faulting.sse.as_ref().unwrap().mxcsr & 0x3f, 0x20);
        assert_eq!(faulting.rip, 0x27100);

        for cpl in 0..=3 {
            let mut cpl_state = LongModeState::default();
            cpl_state.rip = 0x27100;
            cpl_state.cs_selector = Some(cpl);
            cpl_state.sse = Some(SseState {
                xmm: [[0; 16]; 16],
                mxcsr: 0x1f80,
            });
            let mut cpl_memory = Memory::at(&code, cpl_state.rip);
            assert_eq!(
                run(&mut cpl_state, &mut cpl_memory).exit,
                RunExit::StopAddress
            );
        }

        for (gate, vector) in [
            (
                AddpdControls {
                    sse2_available: false,
                    cr0_ts: true,
                    ..controls
                },
                6,
            ),
            (
                AddpdControls {
                    cr0_ts: true,
                    ..controls
                },
                7,
            ),
        ] {
            let mut gated = LongModeState::default();
            gated.rip = 0x27100;
            gated.sse = Some(SseState {
                xmm: [[0; 16]; 16],
                mxcsr: 0x1f80,
            });
            let before = gated.clone();
            let mut gate_memory = Memory::at(&code, gated.rip);
            let gate_rip = gated.rip;
            let result = run_with_addpd_register_controls(
                &mut gated,
                &mut gate_memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(gate_rip + 4),
                    context: AccessContext::default(),
                },
                gate,
                || false,
            );
            assert_eq!(
                result.exit,
                RunExit::Fault(ArchitecturalFault {
                    vector,
                    error_code: None,
                    linear_address: None
                })
            );
            assert_eq!(gated, before);
            assert!(gate_memory.accesses.is_empty());
        }

        let short = [0x66, 0x0f, 0x58];
        let mut short_state = LongModeState::default();
        short_state.rip = 0x27100;
        short_state.sse = Some(SseState {
            xmm: [[0; 16]; 16],
            mxcsr: 0x1f80,
        });
        let before = short_state.clone();
        let mut short_memory = Memory::at(&short, short_state.rip);
        let result = run_with_addpd_register_controls(
            &mut short_state,
            &mut short_memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: None,
                context: AccessContext::default(),
            },
            AddpdControls {
                sse2_available: false,
                cr0_em: true,
                cr0_ts: true,
                cr4_osfxsr: false,
                cr4_osxmmexcpt: false,
            },
            || false,
        );
        assert!(matches!(result.exit, RunExit::MemoryError(_)));
        assert_eq!(short_state, before);
        assert_eq!(short_memory.fetches.len(), short.len() + 1);
        assert!(short_memory.accesses.is_empty());

        for mxcsr in [0x1fc0, 0x0001_1f80, 0x1b80, 0x1780] {
            let mut invalid = LongModeState::default();
            invalid.rip = 0x27180;
            invalid.sse = Some(SseState {
                xmm: [[0; 16]; 16],
                mxcsr,
            });
            let before = invalid.clone();
            let mut invalid_memory = Memory::at(&code, invalid.rip);
            assert_eq!(
                run(&mut invalid, &mut invalid_memory).exit,
                RunExit::Unsupported { opcode: 0x58 }
            );
            assert_eq!(invalid, before);
            assert!(invalid_memory.accesses.is_empty());
        }
    }

    #[test]
    fn cvtpd2ps_executes_all_xmm_pairs_and_snapshots_aliases() {
        let controls = Cvtpd2psControls {
            sse2_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let mut code = vec![0x66];
                if destination >= 8 || source >= 8 {
                    code.push(0x40 | ((destination >> 1) & 4) | (source >> 3));
                }
                code.extend([0x0f, 0x5a, 0xc0 | ((destination & 7) << 3) | (source & 7)]);
                let mut state = LongModeState::default();
                state.rip = 0x2c000;
                let mut xmm = [[0xa5; 16]; 16];
                xmm[usize::from(source)][..8]
                    .copy_from_slice(&0x3ff0_0000_1000_0000u64.to_le_bytes());
                xmm[usize::from(source)][8..]
                    .copy_from_slice(&0x3ff8_0000_0000_0000u64.to_le_bytes());
                state.sse = Some(SseState { xmm, mxcsr: 0x1f80 });
                let length = code.len() as u64;
                let stop_rip = state.rip + length;
                let mut memory = Memory::at(&code, state.rip);
                let result = run_with_cvtpd2ps_register_controls(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(stop_rip),
                        context: AccessContext::default(),
                    },
                    controls,
                    || false,
                );
                assert_eq!(
                    result.exit,
                    RunExit::StopAddress,
                    "destination={destination} source={source}"
                );
                let result_xmm = &state.sse.as_ref().unwrap().xmm[usize::from(destination)];
                assert_eq!(&result_xmm[..4], &0x3f80_0000u32.to_le_bytes());
                assert_eq!(&result_xmm[4..8], &0x3fc0_0000u32.to_le_bytes());
                assert_eq!(&result_xmm[8..], &[0; 8]);
                assert_eq!(state.sse.as_ref().unwrap().mxcsr & 0x3f, 0x20);
            }
        }
    }

    #[test]
    fn addsd_register_pairs_snapshot_low64_and_preserve_upper_destination() {
        let controls = AddsdControls {
            sse2_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        for destination in 0u8..16 {
            for source in 0u8..16 {
                let mut code = vec![0xf2];
                if destination >= 8 || source >= 8 {
                    code.push(0x40 | ((destination >> 1) & 4) | (source >> 3));
                }
                code.extend([0x0f, 0x58, 0xc0 | ((destination & 7) << 3) | (source & 7)]);
                let mut state = LongModeState::default();
                state.rip = 0x2d000;
                let mut xmm = [[0x5a; 16]; 16];
                for register in &mut xmm {
                    register[..8].copy_from_slice(&0x3ff0_0000_0000_0000u64.to_le_bytes());
                    register[8..].copy_from_slice(&0x7ff0_0000_0000_0001u64.to_le_bytes());
                }
                if destination != source {
                    xmm[usize::from(source)][..8]
                        .copy_from_slice(&0x3ca0_0000_0000_0000u64.to_le_bytes());
                }
                let expected_upper = xmm[usize::from(destination)][8..].to_vec();
                state.sse = Some(SseState { xmm, mxcsr: 0x1f80 });
                let rip = state.rip;
                let mut memory = Memory::at(&code, rip);
                let result = run_with_addsd_register_controls(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(rip + code.len() as u64),
                        context: AccessContext::default(),
                    },
                    controls,
                    || false,
                );
                assert_eq!(result.exit, RunExit::StopAddress, "{destination},{source}");
                assert_eq!(result.instructions_executed, 1);
                let sse = state.sse.as_ref().unwrap();
                assert_eq!(
                    u64::from_le_bytes(sse.xmm[usize::from(destination)][..8].try_into().unwrap()),
                    if destination == source {
                        0x4000_0000_0000_0000
                    } else {
                        0x3ff0_0000_0000_0000
                    },
                    "{destination},{source}"
                );
                assert_eq!(&sse.xmm[usize::from(destination)][8..], expected_upper);
                assert_eq!(sse.mxcsr & 0x3f, u32::from(destination != source) << 5);
                assert!(memory.accesses.is_empty());
            }
        }
    }

    #[test]
    fn addsd_pre_and_post_events_commit_atomically_and_gate_after_fetch() {
        let code = [0xf2, 0x0f, 0x58, 0xc1];
        let controls = AddsdControls {
            sse2_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        let mut state = LongModeState::default();
        state.rip = 0x2e000;
        state.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x1f00,
        });
        state.sse.as_mut().unwrap().xmm[0][..8]
            .copy_from_slice(&0x7ff0_0000_0000_0001u64.to_le_bytes());
        state.sse.as_mut().unwrap().xmm[1][..8]
            .copy_from_slice(&0x3ff0_0000_0000_0000u64.to_le_bytes());
        let before_xmm = state.sse.as_ref().unwrap().xmm[0];
        let rip = state.rip;
        let mut memory = Memory::at(&code, rip);
        let result = run_with_addsd_register_controls(
            &mut state,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: Some(rip + 4),
                context: AccessContext::default(),
            },
            controls,
            || false,
        );
        assert_eq!(
            result.exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 19,
                error_code: None,
                linear_address: None
            })
        );
        assert_eq!(state.sse.as_ref().unwrap().mxcsr & 3, 1);
        assert_eq!(state.sse.as_ref().unwrap().xmm[0], before_xmm);
        assert_eq!(state.rip, 0x2e000);
        assert_eq!(result.instructions_executed, 0);
        assert!(memory.accesses.is_empty());

        let mut fallback = LongModeState::default();
        fallback.rip = 0x2e080;
        fallback.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x1f00,
        });
        fallback.sse.as_mut().unwrap().xmm[0][..8]
            .copy_from_slice(&0x7ff0_0000_0000_0001u64.to_le_bytes());
        let rip = fallback.rip;
        let mut memory = Memory::at(&code, rip);
        let result = run_with_addsd_register_controls(
            &mut fallback,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: Some(rip + 4),
                context: AccessContext::default(),
            },
            AddsdControls {
                cr4_osxmmexcpt: false,
                ..controls
            },
            || false,
        );
        assert_eq!(
            result.exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 6,
                error_code: None,
                linear_address: None
            })
        );
        assert_eq!(fallback.sse.as_ref().unwrap().mxcsr & 3, 1);
        assert_eq!(fallback.rip, rip);
        assert!(memory.accesses.is_empty());

        let mut unmasked_pm = LongModeState::default();
        unmasked_pm.rip = 0x2e0c0;
        unmasked_pm.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x0f80,
        });
        unmasked_pm.sse.as_mut().unwrap().xmm[0][..8]
            .copy_from_slice(&0x3ff0_0000_0000_0000u64.to_le_bytes());
        unmasked_pm.sse.as_mut().unwrap().xmm[1][..8]
            .copy_from_slice(&0x3ca0_0000_0000_0000u64.to_le_bytes());
        let before = unmasked_pm.sse.as_ref().unwrap().xmm[0];
        let rip = unmasked_pm.rip;
        let mut memory = Memory::at(&code, rip);
        let result = run_with_addsd_register_controls(
            &mut unmasked_pm,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: Some(rip + 4),
                context: AccessContext::default(),
            },
            controls,
            || false,
        );
        assert_eq!(
            result.exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 19,
                error_code: None,
                linear_address: None
            })
        );
        assert_eq!(unmasked_pm.sse.as_ref().unwrap().mxcsr & 0x3f, 0x20);
        assert_eq!(unmasked_pm.sse.as_ref().unwrap().xmm[0], before);
        assert_eq!(unmasked_pm.rip, rip);
        assert_eq!(result.instructions_executed, 0);
        assert!(memory.accesses.is_empty());

        let short = [0xf2, 0x0f, 0x58];
        let mut truncated = LongModeState::default();
        truncated.rip = 0x2e100;
        truncated.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x1f80,
        });
        let mut memory = Memory::at(&short, truncated.rip);
        memory.fetch_error = Some((
            truncated.rip + 3,
            MemoryError::Architectural(ArchitecturalFault {
                vector: 14,
                error_code: Some(0),
                linear_address: Some(truncated.rip + 3),
            }),
        ));
        let result = run_with_addsd_register_controls(
            &mut truncated,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: None,
                context: AccessContext::default(),
            },
            AddsdControls {
                sse2_available: false,
                ..controls
            },
            || false,
        );
        assert_eq!(
            result.exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 14,
                error_code: Some(0),
                linear_address: Some(0x2e103),
            })
        );
        assert_eq!(truncated.rip, 0x2e100);
        assert!(memory.accesses.is_empty());
    }

    #[test]
    fn addsd_rounding_boundaries_and_cpl_gate_matrix() {
        let controls = AddsdControls {
            sse2_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        let code = [0xf2, 0x0f, 0x58, 0xc1];
        let vectors: &[(u64, u64, u32, u64, u32)] = &[
            (
                0x3ff0_0000_0000_0000,
                0x3ca0_0000_0000_0000,
                0x1f80,
                0x3ff0_0000_0000_0000,
                0x20,
            ),
            (
                0x3ff0_0000_0000_0000,
                0x3ca0_0000_0000_0000,
                0x5f80,
                0x3ff0_0000_0000_0001,
                0x20,
            ),
            (
                0xbff0_0000_0000_0000,
                0xbca0_0000_0000_0000,
                0x1f80,
                0xbff0_0000_0000_0000,
                0x20,
            ),
            (
                0xbff0_0000_0000_0000,
                0xbca0_0000_0000_0000,
                0x3f80,
                0xbff0_0000_0000_0001,
                0x20,
            ),
            (0, 0x8000_0000_0000_0000, 0x1f80, 0, 0),
            (0, 0x8000_0000_0000_0000, 0x3f80, 0x8000_0000_0000_0000, 0),
            (
                0x8000_0000_0000_0000,
                0x8000_0000_0000_0000,
                0x5f80,
                0x8000_0000_0000_0000,
                0,
            ),
            (0x3ff0_0000_0000_0000, 0xbff0_0000_0000_0000, 0x1f80, 0, 0),
            (
                0x3ff0_0000_0000_0000,
                0xbff0_0000_0000_0000,
                0x3f80,
                0x8000_0000_0000_0000,
                0,
            ),
            (0x0010_0000_0000_0001, 0x8010_0000_0000_0000, 0x1f80, 1, 0),
            (
                0x0010_0000_0000_0001,
                0x8010_0000_0000_0000,
                0x9f80,
                0,
                0x30,
            ),
            (
                0x3ff0_0000_0000_0000,
                1,
                0x5f80,
                0x3ff0_0000_0000_0001,
                0x22,
            ),
            (
                0x7fef_ffff_ffff_ffff,
                0x7c90_0000_0000_0000,
                0x1f80,
                0x7ff0_0000_0000_0000,
                0x28,
            ),
            (
                0x7fef_ffff_ffff_ffff,
                0x7c90_0000_0000_0000,
                0x3f80,
                0x7fef_ffff_ffff_ffff,
                0x20,
            ),
            (
                0x7fef_ffff_ffff_ffff,
                0x7c90_0000_0000_0000,
                0x5f80,
                0x7ff0_0000_0000_0000,
                0x28,
            ),
            (
                0x7fef_ffff_ffff_ffff,
                0x7c90_0000_0000_0000,
                0x7f80,
                0x7fef_ffff_ffff_ffff,
                0x20,
            ),
            (
                0x7fef_ffff_ffff_ffff,
                0x7fef_ffff_ffff_ffff,
                0x1f80,
                0x7ff0_0000_0000_0000,
                0x28,
            ),
            (
                0x7fef_ffff_ffff_ffff,
                0x7fef_ffff_ffff_ffff,
                0x3f80,
                0x7fef_ffff_ffff_ffff,
                0x28,
            ),
            (
                0x7fef_ffff_ffff_ffff,
                0x7fef_ffff_ffff_ffff,
                0x5f80,
                0x7ff0_0000_0000_0000,
                0x28,
            ),
            (
                0x7fef_ffff_ffff_ffff,
                0x7fef_ffff_ffff_ffff,
                0x7f80,
                0x7fef_ffff_ffff_ffff,
                0x28,
            ),
        ];
        for &(lhs, rhs, mxcsr, expected, flags) in vectors {
            let mut state = LongModeState::default();
            state.rip = 0x2e200;
            state.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr,
            });
            state.sse.as_mut().unwrap().xmm[0][..8].copy_from_slice(&lhs.to_le_bytes());
            state.sse.as_mut().unwrap().xmm[1][..8].copy_from_slice(&rhs.to_le_bytes());
            let rip = state.rip;
            let mut memory = Memory::at(&code, rip);
            let result = run_with_addsd_register_controls(
                &mut state,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(rip + 4),
                    context: AccessContext::default(),
                },
                controls,
                || false,
            );
            assert_eq!(
                result.exit,
                RunExit::StopAddress,
                "{lhs:016x}+{rhs:016x} MXCSR={mxcsr:04x}"
            );
            assert_eq!(
                u64::from_le_bytes(state.sse.as_ref().unwrap().xmm[0][..8].try_into().unwrap()),
                expected
            );
            assert_eq!(state.sse.as_ref().unwrap().mxcsr & 0x3b, flags);
            assert!(memory.accesses.is_empty());
        }

        for privilege in [
            PrivilegeLevel::Ring0,
            PrivilegeLevel::Ring1,
            PrivilegeLevel::Ring2,
            PrivilegeLevel::Ring3,
        ] {
            let mut state = LongModeState::default();
            state.rip = 0x2e300;
            state.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr: 0x1f80,
            });
            let rip = state.rip;
            let mut memory = Memory::at(&code, rip);
            let result = run_with_addsd_register_controls(
                &mut state,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(rip + 4),
                    context: AccessContext {
                        privilege,
                        ..AccessContext::default()
                    },
                },
                controls,
                || false,
            );
            assert_eq!(result.exit, RunExit::StopAddress, "CPL {privilege:?}");
            assert!(memory.accesses.is_empty());

            let mut gated = LongModeState::default();
            gated.rip = rip;
            gated.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr: 0x1f80,
            });
            let before = gated.clone();
            let mut memory = Memory::at(&code, rip);
            let result = run_with_addsd_register_controls(
                &mut gated,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(rip + 4),
                    context: AccessContext {
                        privilege,
                        ..AccessContext::default()
                    },
                },
                AddsdControls {
                    sse2_available: false,
                    ..controls
                },
                || false,
            );
            assert_eq!(
                result.exit,
                RunExit::Fault(ArchitecturalFault {
                    vector: 6,
                    error_code: None,
                    linear_address: None,
                }),
                "CPL {privilege:?}"
            );
            assert_eq!(gated, before);
            assert!(memory.accesses.is_empty());

            for (gate_controls, vector) in [
                (
                    AddsdControls {
                        cr0_em: true,
                        ..controls
                    },
                    6,
                ),
                (
                    AddsdControls {
                        cr4_osfxsr: false,
                        ..controls
                    },
                    6,
                ),
                (
                    AddsdControls {
                        cr0_ts: true,
                        ..controls
                    },
                    7,
                ),
            ] {
                let mut gated = LongModeState::default();
                gated.rip = rip;
                gated.sse = Some(SseState {
                    xmm: [[0x5a; 16]; 16],
                    mxcsr: 0x1f80,
                });
                let before = gated.clone();
                let mut memory = Memory::at(&code, rip);
                let result = run_with_addsd_register_controls(
                    &mut gated,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(rip + 4),
                        context: AccessContext {
                            privilege,
                            ..AccessContext::default()
                        },
                    },
                    gate_controls,
                    || false,
                );
                assert_eq!(
                    result.exit,
                    RunExit::Fault(ArchitecturalFault {
                        vector,
                        error_code: None,
                        linear_address: None,
                    }),
                    "CPL {privilege:?} controls {gate_controls:?}"
                );
                assert_eq!(gated, before);
                assert!(memory.accesses.is_empty());
            }
        }

        // High-lane SNaN/subnormal canaries are ignored even with IM, DM, and
        // PM unmasked; low-lane exact addition still retires without events.
        let mut high_poison = LongModeState::default();
        high_poison.rip = 0x2e400;
        high_poison.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x0c00,
        });
        high_poison.sse.as_mut().unwrap().xmm[0][..8]
            .copy_from_slice(&0x3ff0_0000_0000_0000u64.to_le_bytes());
        high_poison.sse.as_mut().unwrap().xmm[1][..8]
            .copy_from_slice(&0x3ff0_0000_0000_0000u64.to_le_bytes());
        high_poison.sse.as_mut().unwrap().xmm[0][8..]
            .copy_from_slice(&0x7ff0_0000_0000_0001u64.to_le_bytes());
        high_poison.sse.as_mut().unwrap().xmm[1][8..].copy_from_slice(&1u64.to_le_bytes());
        let mut memory = Memory::at(&code, high_poison.rip);
        let rip = high_poison.rip;
        let result = run_with_addsd_register_controls(
            &mut high_poison,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: Some(rip + 4),
                context: AccessContext::default(),
            },
            controls,
            || false,
        );
        assert_eq!(result.exit, RunExit::StopAddress);
        assert_eq!(high_poison.sse.as_ref().unwrap().mxcsr, 0x0c00);
        assert_eq!(
            u64::from_le_bytes(
                high_poison.sse.as_ref().unwrap().xmm[0][..8]
                    .try_into()
                    .unwrap()
            ),
            0x4000_0000_0000_0000
        );
        assert!(memory.accesses.is_empty());

        // Old sticky PE with PM unmasked does not fault absent a new PE.
        let mut sticky = LongModeState::default();
        sticky.rip = 0x2e500;
        sticky.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x0fa0,
        });
        sticky.sse.as_mut().unwrap().xmm[0][..8]
            .copy_from_slice(&0x3ff0_0000_0000_0000u64.to_le_bytes());
        sticky.sse.as_mut().unwrap().xmm[1][..8]
            .copy_from_slice(&0x3ff0_0000_0000_0000u64.to_le_bytes());
        let mut memory = Memory::at(&code, sticky.rip);
        let rip = sticky.rip;
        let result = run_with_addsd_register_controls(
            &mut sticky,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: Some(rip + 4),
                context: AccessContext::default(),
            },
            controls,
            || false,
        );
        assert_eq!(result.exit, RunExit::StopAddress);
        assert_eq!(sticky.sse.as_ref().unwrap().mxcsr, 0x0fa0);
        assert!(memory.accesses.is_empty());

        // Runtime admission rejects DAZ, clear OM/UM, and reserved bits.
        for mxcsr in [0x1fc0, 0x1b80, 0x1780, 0x11f80] {
            let mut invalid = LongModeState::default();
            invalid.rip = 0x2e600;
            invalid.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr,
            });
            let before = invalid.clone();
            let rip = invalid.rip;
            let mut memory = Memory::at(&code, rip);
            let result = run_with_addsd_register_controls(
                &mut invalid,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(rip + 4),
                    context: AccessContext::default(),
                },
                controls,
                || false,
            );
            assert!(matches!(result.exit, RunExit::Unsupported { opcode: 0x58 }));
            assert_eq!(invalid, before);
            assert!(memory.accesses.is_empty());
        }
    }

    #[test]
    fn addss_register_pairs_snapshot_all_xmm_pairs_and_preserve_high96() {
        let controls = AddssControls {
            sse_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let code: Vec<u8> = if destination >= 8 || source >= 8 {
                    let rex = 0x40 | ((destination >> 1) & 4) | (source >> 3);
                    vec![0xf3, rex, 0x0f, 0x58, modrm]
                } else {
                    vec![0xf3, 0x0f, 0x58, modrm]
                };
                let mut state = LongModeState::default();
                state.rip = 0x2f000;
                state.sse = Some(SseState {
                    xmm: [[0x5a; 16]; 16],
                    mxcsr: 0x0c00,
                });
                state.sse.as_mut().unwrap().xmm[usize::from(destination)][..4]
                    .copy_from_slice(&0x3f80_0000u32.to_le_bytes());
                if source != destination {
                    state.sse.as_mut().unwrap().xmm[usize::from(source)][..4]
                        .copy_from_slice(&0x4000_0000u32.to_le_bytes());
                }
                state.sse.as_mut().unwrap().xmm[usize::from(destination)][4..]
                    .copy_from_slice(&[0x01, 0x00, 0x80, 0x7f, 1, 0, 0, 0, 1, 0, 0, 0]);
                if source != destination {
                    state.sse.as_mut().unwrap().xmm[usize::from(source)][4..]
                        .copy_from_slice(&[0x01, 0x00, 0xc0, 0x7f, 1, 0, 0, 0, 1, 0, 0, 0]);
                }
                let old_destination = state.sse.as_ref().unwrap().xmm[usize::from(destination)];
                let stop_rip = state.rip + code.len() as u64;
                let mut memory = Memory::at(&code, state.rip);
                let result = run_with_addss_register_controls(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(stop_rip),
                        context: AccessContext::default(),
                    },
                    controls,
                    || false,
                );
                let expected = if destination == source {
                    0x4000_0000
                } else {
                    0x4040_0000
                };
                assert_eq!(result.exit, RunExit::StopAddress, "{destination},{source}");
                assert_eq!(result.instructions_executed, 1);
                assert_eq!(state.rip, stop_rip);
                assert_eq!(state.sse.as_ref().unwrap().mxcsr, 0x0c00);
                let new_destination = state.sse.as_ref().unwrap().xmm[usize::from(destination)];
                assert_eq!(
                    u32::from_le_bytes(new_destination[..4].try_into().unwrap()),
                    expected
                );
                assert_eq!(&new_destination[4..], &old_destination[4..]);
                assert!(memory.accesses.is_empty());
            }
        }
    }

    #[test]
    fn addss_rounding_exceptions_tiny_results_and_atomicity() {
        let controls = AddssControls {
            sse_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        let code = [0xf3, 0x0f, 0x58, 0xc1];
        let run = |lhs: u32, rhs: u32, mxcsr: u32| {
            let mut state = LongModeState::default();
            state.rip = 0x2f100;
            state.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr,
            });
            state.sse.as_mut().unwrap().xmm[0][..4].copy_from_slice(&lhs.to_le_bytes());
            state.sse.as_mut().unwrap().xmm[1][..4].copy_from_slice(&rhs.to_le_bytes());
            let old_high = state.sse.as_ref().unwrap().xmm[0][4..].to_vec();
            let stop_rip = state.rip + 4;
            let mut memory = Memory::at(&code, state.rip);
            let result = run_with_addss_register_controls(
                &mut state,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(stop_rip),
                    context: AccessContext::default(),
                },
                controls,
                || false,
            );
            (result, state, memory, old_high)
        };

        for (rc, expected, flags) in [
            (0, 0x3f80_0000, 0x20),
            (1, 0x3f80_0000, 0x20),
            (2, 0x3f80_0001, 0x20),
            (3, 0x3f80_0000, 0x20),
        ] {
            let (result, state, memory, high) = run(0x3f80_0000, 0x3380_0000, 0x1f80 | (rc << 13));
            assert_eq!(result.exit, RunExit::StopAddress);
            assert_eq!(
                u32::from_le_bytes(state.sse.as_ref().unwrap().xmm[0][..4].try_into().unwrap()),
                expected
            );
            assert_eq!(state.sse.as_ref().unwrap().mxcsr & 0x3f, flags);
            assert_eq!(&state.sse.as_ref().unwrap().xmm[0][4..], high.as_slice());
            assert!(memory.accesses.is_empty());
        }
        for (rc, expected) in [
            (0, 0xbf80_0000),
            (1, 0xbf80_0001),
            (2, 0xbf80_0000),
            (3, 0xbf80_0000),
        ] {
            let (result, state, _, _) = run(0xbf80_0000, 0xb380_0000, 0x1f80 | (rc << 13));
            assert_eq!(result.exit, RunExit::StopAddress);
            assert_eq!(
                u32::from_le_bytes(state.sse.as_ref().unwrap().xmm[0][..4].try_into().unwrap()),
                expected
            );
            assert_eq!(state.sse.as_ref().unwrap().mxcsr & 0x3f, 0x20);
        }
        for (rc, expected, flags) in [
            (0, 0x7f80_0000, 0x28),
            (1, 0x7f7f_ffff, 0x20),
            (2, 0x7f80_0000, 0x28),
            (3, 0x7f7f_ffff, 0x20),
        ] {
            let (result, state, _, _) = run(0x7f7f_ffff, 0x7300_0000, 0x1f80 | (rc << 13));
            assert_eq!(result.exit, RunExit::StopAddress);
            assert_eq!(
                u32::from_le_bytes(state.sse.as_ref().unwrap().xmm[0][..4].try_into().unwrap()),
                expected
            );
            assert_eq!(state.sse.as_ref().unwrap().mxcsr & 0x3f, flags);
        }
        for rc in 0..4 {
            let (result, state, _, _) = run(0x7f7f_ffff, 0x7f7f_ffff, 0x1f80 | (rc << 13));
            assert_eq!(result.exit, RunExit::StopAddress);
            assert_eq!(state.sse.as_ref().unwrap().mxcsr & 0x3f, 0x28);
        }
        let (exact, exact_state, _, _) = run(0x0080_0001, 0x8080_0000, 0x1f80);
        assert_eq!(exact.exit, RunExit::StopAddress);
        assert_eq!(
            u32::from_le_bytes(
                exact_state.sse.as_ref().unwrap().xmm[0][..4]
                    .try_into()
                    .unwrap()
            ),
            1
        );
        assert_eq!(exact_state.sse.as_ref().unwrap().mxcsr & 0x3f, 0);
        let (flushed, flushed_state, _, _) = run(0x0080_0001, 0x8080_0000, 0x9f80);
        assert_eq!(flushed.exit, RunExit::StopAddress);
        assert_eq!(
            u32::from_le_bytes(
                flushed_state.sse.as_ref().unwrap().xmm[0][..4]
                    .try_into()
                    .unwrap()
            ),
            0
        );
        assert_eq!(flushed_state.sse.as_ref().unwrap().mxcsr & 0x3f, 0x30);
        let (gap, gap_state, _, _) = run(0x3f80_0000, 1, 0x5f80);
        assert_eq!(gap.exit, RunExit::StopAddress);
        assert_eq!(
            u32::from_le_bytes(
                gap_state.sse.as_ref().unwrap().xmm[0][..4]
                    .try_into()
                    .unwrap()
            ),
            0x3f80_0001
        );
        assert_eq!(gap_state.sse.as_ref().unwrap().mxcsr & 0x3f, 0x22);

        for (lhs, rhs, expected, flags) in [
            (0x7fc0_1234, 0xff80_0001, 0x7fc0_1234, 0x01),
            (0x7f80_0001, 0x7fc0_2345, 0x7fc0_0001, 0x01),
            (0x7fc0_0001, 0x3f80_0000, 0x7fc0_0001, 0),
            (0x7f80_0000, 0xff80_0000, 0xffc0_0000, 0x01),
            (0x7f80_0000, 1, 0x7f80_0000, 0x02),
        ] {
            let (result, state, _, _) = run(lhs, rhs, 0x1f80);
            assert_eq!(result.exit, RunExit::StopAddress, "{lhs:08x}+{rhs:08x}");
            assert_eq!(
                u32::from_le_bytes(state.sse.as_ref().unwrap().xmm[0][..4].try_into().unwrap()),
                expected
            );
            assert_eq!(state.sse.as_ref().unwrap().mxcsr & 0x3f, flags);
        }
        for (lhs, rhs, expected) in [
            (0x0000_0000, 0x0000_0000, 0x0000_0000),
            (0x8000_0000, 0x8000_0000, 0x8000_0000),
            (0x3f80_0000, 0xbf80_0000, 0x0000_0000),
            (0x3f80_0000, 0xbf80_0000, 0x8000_0000),
        ] {
            let mxcsr = if expected == 0x8000_0000 && lhs == 0x3f80_0000 {
                0x3f80
            } else {
                0x1f80
            };
            let (result, state, _, _) = run(lhs, rhs, mxcsr);
            assert_eq!(result.exit, RunExit::StopAddress);
            assert_eq!(
                u32::from_le_bytes(state.sse.as_ref().unwrap().xmm[0][..4].try_into().unwrap()),
                expected
            );
        }

        for (lhs, rhs, mxcsr, expected_flags, vector) in [
            (0x7f80_0000, 0xff80_0000, 0x1f00, 0x01, 19),
            (0x3f80_0000, 1, 0x1e80, 0x02, 19),
        ] {
            let (result, state, _, high) = run(lhs, rhs, mxcsr);
            assert_eq!(
                result.exit,
                RunExit::Fault(ArchitecturalFault {
                    vector,
                    error_code: None,
                    linear_address: None
                })
            );
            assert_eq!(state.sse.as_ref().unwrap().mxcsr & 0x3f, expected_flags);
            assert_eq!(&state.sse.as_ref().unwrap().xmm[0][4..], high.as_slice());
            assert_eq!(state.rip, 0x2f100);
        }
        let (pm_fault, pm_state, _, _) = run(0x3f80_0000, 0x3380_0000, 0x0f80);
        assert_eq!(
            pm_fault.exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 19,
                error_code: None,
                linear_address: None
            })
        );
        assert_eq!(pm_state.sse.as_ref().unwrap().mxcsr & 0x3f, 0x20);
        assert_eq!(pm_state.rip, 0x2f100);
    }

    #[test]
    fn addps_register_pairs_use_four_binary32_lanes_and_atomic_events() {
        let controls = AddpsControls {
            sse_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        let execute = |state: &mut LongModeState, memory: &mut Memory| {
            run_with_addps_register_controls(
                state,
                memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(state.rip + 3),
                    context: AccessContext::default(),
                },
                controls,
                || false,
            )
        };
        let code = [0x0f, 0x58, 0xc1];
        let pack = |lanes: [u32; 4]| {
            let mut bytes = [0; 16];
            for (index, value) in lanes.into_iter().enumerate() {
                bytes[index * 4..index * 4 + 4].copy_from_slice(&value.to_le_bytes());
            }
            bytes
        };
        let unpack = |bytes: [u8; 16]| {
            std::array::from_fn::<_, 4, _>(|index| {
                u32::from_le_bytes(bytes[index * 4..index * 4 + 4].try_into().unwrap())
            })
        };

        let mut state = LongModeState::default();
        state.rip = 0x2a000;
        let mut xmm = [[0x5a; 16]; 16];
        xmm[0] = pack([0x3f80_0000, 0xbf80_0000, 0x0080_0001, 0x7f7f_ffff]);
        xmm[1] = pack([0x3380_0000, 0xb380_0000, 0x8080_0000, 0x7300_0000]);
        state.sse = Some(SseState { xmm, mxcsr: 0x1f80 });
        let mut memory = Memory::at(&code, state.rip);
        assert_eq!(execute(&mut state, &mut memory).exit, RunExit::StopAddress);
        assert_eq!(
            unpack(state.sse.as_ref().unwrap().xmm[0]),
            [0x3f80_0000, 0xbf80_0000, 1, 0x7f80_0000]
        );
        assert_eq!(state.sse.as_ref().unwrap().mxcsr & 0x3f, 0x28);

        // A new unmasked pre-event in any lane suppresses every post flag and
        // the whole XMM write, while committing all new IE/DE status bits.
        let mut faulting = LongModeState::default();
        faulting.rip = 0x2a000;
        let mut xmm = [[0x5a; 16]; 16];
        xmm[0] = pack([0x7f80_0001, 0x0000_0001, 0x7f7f_ffff, 0x0080_0001]);
        xmm[1] = pack([0x3f80_0000, 0x3f80_0000, 0x7f7f_ffff, 0x8080_0000]);
        faulting.sse = Some(SseState { xmm, mxcsr: 0x1c00 }); // IM=DM=0, PM=1
        let old_destination = faulting.sse.as_ref().unwrap().xmm[0];
        let mut memory = Memory::at(&code, faulting.rip);
        assert_eq!(
            execute(&mut faulting, &mut memory).exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 19,
                error_code: None,
                linear_address: None,
            })
        );
        assert_eq!(faulting.sse.as_ref().unwrap().xmm[0], old_destination);
        assert_eq!(faulting.sse.as_ref().unwrap().mxcsr & 0x3f, 0x03);
        assert_eq!(faulting.rip, 0x2a000);

        // A masked precision event faults only after status commit.
        let mut precision = LongModeState::default();
        precision.rip = 0x2a000;
        let mut xmm = [[0; 16]; 16];
        xmm[0] = pack([0x3f80_0000, 0, 0, 0]);
        xmm[1] = pack([0x3380_0000, 0, 0, 0]);
        precision.sse = Some(SseState { xmm, mxcsr: 0x0f80 });
        let old_destination = precision.sse.as_ref().unwrap().xmm[0];
        let mut memory = Memory::at(&code, precision.rip);
        assert_eq!(
            execute(&mut precision, &mut memory).exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 19,
                error_code: None,
                linear_address: None,
            })
        );
        assert_eq!(precision.sse.as_ref().unwrap().xmm[0], old_destination);
        assert_eq!(precision.sse.as_ref().unwrap().mxcsr & 0x3f, 0x20);

        let mut fallback = LongModeState::default();
        fallback.rip = 0x2a000;
        let mut xmm = [[0; 16]; 16];
        xmm[0] = pack([0x3f80_0000, 0, 0, 0]);
        xmm[1] = pack([0x3380_0000, 0, 0, 0]);
        fallback.sse = Some(SseState { xmm, mxcsr: 0x0f80 });
        let before_xmm = fallback.sse.as_ref().unwrap().xmm[0];
        let mut memory = Memory::at(&code, fallback.rip);
        let stop_rip = fallback.rip + 3;
        assert_eq!(
            run_with_addps_register_controls(
                &mut fallback,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(stop_rip),
                    context: AccessContext::default(),
                },
                AddpsControls {
                    cr4_osxmmexcpt: false,
                    ..controls
                },
                || false,
            )
            .exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 6,
                error_code: None,
                linear_address: None,
            })
        );
        assert_eq!(fallback.sse.as_ref().unwrap().xmm[0], before_xmm);
        assert_eq!(fallback.sse.as_ref().unwrap().mxcsr & 0x3f, 0x20);

        for (rc, expected) in [
            (0x0000, 0x3f80_0000),
            (0x2000, 0x3f80_0000),
            (0x4000, 0x3f80_0001),
            (0x6000, 0x3f80_0000),
        ] {
            let mut rounded = LongModeState::default();
            rounded.rip = 0x2a000;
            let mut xmm = [[0; 16]; 16];
            xmm[0] = pack([0x3f80_0000, 0, 0, 0]);
            xmm[1] = pack([0x3380_0000, 0, 0, 0]);
            rounded.sse = Some(SseState {
                xmm,
                mxcsr: 0x1f80 | rc,
            });
            let mut memory = Memory::at(&code, rounded.rip);
            assert_eq!(
                execute(&mut rounded, &mut memory).exit,
                RunExit::StopAddress
            );
            assert_eq!(unpack(rounded.sse.as_ref().unwrap().xmm[0])[0], expected);
            assert_eq!(rounded.sse.as_ref().unwrap().mxcsr & 0x3f, 0x20);
        }
        for (rc, expected, flags) in [
            (0x0000, 0x7f80_0000, 0x28),
            (0x2000, 0x7f7f_ffff, 0x20),
            (0x4000, 0x7f80_0000, 0x28),
            (0x6000, 0x7f7f_ffff, 0x20),
        ] {
            let mut overflow = LongModeState::default();
            overflow.rip = 0x2a000;
            let mut xmm = [[0; 16]; 16];
            xmm[0] = pack([0x7f7f_ffff, 0, 0, 0]);
            xmm[1] = pack([0x7300_0000, 0, 0, 0]);
            overflow.sse = Some(SseState {
                xmm,
                mxcsr: 0x1f80 | rc,
            });
            let mut memory = Memory::at(&code, overflow.rip);
            assert_eq!(
                execute(&mut overflow, &mut memory).exit,
                RunExit::StopAddress
            );
            assert_eq!(unpack(overflow.sse.as_ref().unwrap().xmm[0])[0], expected);
            assert_eq!(overflow.sse.as_ref().unwrap().mxcsr & 0x3f, flags);
        }
        for rc in [0x0000, 0x2000, 0x4000, 0x6000] {
            let mut overflow = LongModeState::default();
            overflow.rip = 0x2a000;
            let mut xmm = [[0; 16]; 16];
            xmm[0] = pack([0x7f7f_ffff, 0, 0, 0]);
            xmm[1] = pack([0x7f7f_ffff, 0, 0, 0]);
            overflow.sse = Some(SseState {
                xmm,
                mxcsr: 0x1f80 | rc,
            });
            let mut memory = Memory::at(&code, overflow.rip);
            assert_eq!(
                execute(&mut overflow, &mut memory).exit,
                RunExit::StopAddress
            );
            assert_eq!(overflow.sse.as_ref().unwrap().mxcsr & 0x3f, 0x28);
        }
        for (ftz, expected, flags) in [(false, 1, 0), (true, 0, 0x30)] {
            let mut tiny = LongModeState::default();
            tiny.rip = 0x2a000;
            let mut xmm = [[0; 16]; 16];
            xmm[0] = pack([0x0080_0001, 0, 0, 0]);
            xmm[1] = pack([0x8080_0000, 0, 0, 0]);
            tiny.sse = Some(SseState {
                xmm,
                mxcsr: 0x1f80 | if ftz { 1 << 15 } else { 0 },
            });
            let mut memory = Memory::at(&code, tiny.rip);
            assert_eq!(execute(&mut tiny, &mut memory).exit, RunExit::StopAddress);
            assert_eq!(unpack(tiny.sse.as_ref().unwrap().xmm[0])[0], expected);
            assert_eq!(tiny.sse.as_ref().unwrap().mxcsr & 0x3f, flags);
        }
        for (rc, expected) in [(0x0000, [0, 0x8000_0000, 0, 0]), (0x2000, [0x8000_0000; 4])] {
            let mut zeros = LongModeState::default();
            zeros.rip = 0x2a000;
            let mut xmm = [[0; 16]; 16];
            xmm[0] = pack([0, 0x8000_0000, 0x3f80_0000, 0xbf80_0000]);
            xmm[1] = pack([0x8000_0000, 0x8000_0000, 0xbf80_0000, 0x3f80_0000]);
            zeros.sse = Some(SseState {
                xmm,
                mxcsr: 0x1f80 | rc,
            });
            let mut memory = Memory::at(&code, zeros.rip);
            assert_eq!(execute(&mut zeros, &mut memory).exit, RunExit::StopAddress);
            assert_eq!(unpack(zeros.sse.as_ref().unwrap().xmm[0]), expected);
            assert_eq!(zeros.sse.as_ref().unwrap().mxcsr & 0x3f, 0);
        }
        let mut special = LongModeState::default();
        special.rip = 0x2a000;
        let mut xmm = [[0; 16]; 16];
        xmm[0] = pack([0x7f80_0042, 0x7fc0_0042, 0x7f80_0000, 0x7f80_0000]);
        xmm[1] = pack([0x7fc0_1234, 0x7f80_0001, 1, 0xff80_0000]);
        let mut special_expected = xmm[0];
        special_expected[0..4].copy_from_slice(&0x7fc0_0042u32.to_le_bytes());
        special_expected[4..8].copy_from_slice(&0x7fc0_0042u32.to_le_bytes());
        special_expected[8..12].copy_from_slice(&0x7f80_0000u32.to_le_bytes());
        special_expected[12..16].copy_from_slice(&0xffc0_0000u32.to_le_bytes());
        special.sse = Some(SseState { xmm, mxcsr: 0x1f80 });
        let mut memory = Memory::at(&code, special.rip);
        assert_eq!(
            execute(&mut special, &mut memory).exit,
            RunExit::StopAddress
        );
        assert_eq!(special.sse.as_ref().unwrap().xmm[0], special_expected);
        assert_eq!(special.sse.as_ref().unwrap().mxcsr & 0x3f, 0x03);

        // Exercise the required all-flags matrix twice with different lane
        // orders so IE/DE aggregation cannot depend on where those lanes sit.
        for order in [[0usize, 1, 2, 3], [2usize, 3, 0, 1]] {
            let sources = [
                (0x7f80_0001, 0x3f80_0000), // SNaN + 1 => IE
                (0x0000_0001, 0x3f80_0000), // minsub + 1 => DE|PE
                (0x7f7f_ffff, 0x7f7f_ffff), // maxfinite + maxfinite => OE|PE
                (0x0080_0001, 0x8080_0000), // FTZ exact tiny => UE|PE
            ];
            let mut dst = [0u32; 4];
            let mut src = [0u32; 4];
            let mut expected = [0u32; 4];
            for (lane, source_lane) in order.into_iter().enumerate() {
                (dst[lane], src[lane]) = sources[source_lane];
                expected[lane] = [0x7fc0_0001, 0x3f80_0000, 0x7f80_0000, 0x0000_0000][source_lane];
            }
            let mut masked = LongModeState::default();
            masked.rip = 0x2a000;
            let mut xmm = [[0; 16]; 16];
            xmm[0] = pack(dst);
            xmm[1] = pack(src);
            masked.sse = Some(SseState { xmm, mxcsr: 0x9f80 });
            let mut memory = Memory::at(&code, masked.rip);
            assert_eq!(execute(&mut masked, &mut memory).exit, RunExit::StopAddress);
            assert_eq!(unpack(masked.sse.as_ref().unwrap().xmm[0]), expected);
            assert_eq!(masked.sse.as_ref().unwrap().mxcsr & 0x3f, 0x3b);
        }

        let matrix_sources = [
            (0x7f80_0001, 0x3f80_0000),
            (0x0000_0001, 0x3f80_0000),
            (0x7f7f_ffff, 0x7f7f_ffff),
            (0x0080_0001, 0x8080_0000),
        ];
        let mut matrix_dst = [0u32; 4];
        let mut matrix_src = [0u32; 4];
        for (lane, (lhs, rhs)) in matrix_sources.into_iter().enumerate() {
            matrix_dst[lane] = lhs;
            matrix_src[lane] = rhs;
        }
        let mut pre_fault = LongModeState::default();
        pre_fault.rip = 0x2a000;
        let mut xmm = [[0; 16]; 16];
        xmm[0] = pack(matrix_dst);
        xmm[1] = pack(matrix_src);
        pre_fault.sse = Some(SseState {
            xmm,
            mxcsr: 0x9f80 & !((1 << 7) | (1 << 8)),
        });
        let old_destination = pre_fault.sse.as_ref().unwrap().xmm[0];
        let mut memory = Memory::at(&code, pre_fault.rip);
        assert_eq!(
            execute(&mut pre_fault, &mut memory).exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 19,
                error_code: None,
                linear_address: None,
            })
        );
        assert_eq!(pre_fault.sse.as_ref().unwrap().mxcsr & 0x3f, 0x03);
        assert_eq!(pre_fault.sse.as_ref().unwrap().xmm[0], old_destination);
        assert_eq!(pre_fault.rip, 0x2a000);

        let mut precision_fault = LongModeState::default();
        precision_fault.rip = 0x2a000;
        let mut xmm = [[0; 16]; 16];
        xmm[0] = pack(matrix_dst);
        xmm[1] = pack(matrix_src);
        precision_fault.sse = Some(SseState {
            xmm,
            mxcsr: 0x9f80 & !(1 << 12),
        });
        let old_destination = precision_fault.sse.as_ref().unwrap().xmm[0];
        let mut memory = Memory::at(&code, precision_fault.rip);
        assert_eq!(
            execute(&mut precision_fault, &mut memory).exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 19,
                error_code: None,
                linear_address: None,
            })
        );
        assert_eq!(precision_fault.sse.as_ref().unwrap().mxcsr & 0x3f, 0x3b);
        assert_eq!(
            precision_fault.sse.as_ref().unwrap().xmm[0],
            old_destination
        );
        assert_eq!(precision_fault.rip, 0x2a000);

        // The same register pair reads both inputs before writing the result.
        let mut alias = LongModeState::default();
        alias.rip = 0x2a000;
        let mut xmm = [[0; 16]; 16];
        xmm[1] = pack([0x3f80_0000, 0x4000_0000, 0x4040_0000, 0x4080_0000]);
        alias.sse = Some(SseState { xmm, mxcsr: 0x1f80 });
        let alias_code = [0x0f, 0x58, 0xc9];
        let mut memory = Memory::at(&alias_code, alias.rip);
        assert_eq!(execute(&mut alias, &mut memory).exit, RunExit::StopAddress);
        assert_eq!(
            unpack(alias.sse.as_ref().unwrap().xmm[1]),
            [0x4000_0000, 0x4080_0000, 0x40c0_0000, 0x4100_0000]
        );
    }

    #[test]
    fn addps_full_fetch_precedes_sse_and_ts_gates_at_all_cpls() {
        let code = [0x0f, 0x58, 0xc1];
        let controls = AddpsControls {
            sse_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        for cpl in 0..=3 {
            for (controls, vector) in [
                (
                    AddpsControls {
                        sse_available: false,
                        cr0_em: false,
                        cr0_ts: true,
                        cr4_osfxsr: true,
                        cr4_osxmmexcpt: true,
                    },
                    6,
                ),
                (
                    AddpsControls {
                        sse_available: true,
                        cr0_em: true,
                        cr0_ts: true,
                        cr4_osfxsr: true,
                        cr4_osxmmexcpt: true,
                    },
                    6,
                ),
                (
                    AddpsControls {
                        sse_available: true,
                        cr0_em: false,
                        cr0_ts: true,
                        cr4_osfxsr: false,
                        cr4_osxmmexcpt: true,
                    },
                    6,
                ),
                (
                    AddpsControls {
                        sse_available: true,
                        cr0_em: false,
                        cr0_ts: true,
                        cr4_osfxsr: true,
                        cr4_osxmmexcpt: true,
                    },
                    7,
                ),
            ] {
                let mut state = LongModeState::default();
                state.rip = 0x2b000;
                state.cs_selector = Some(cpl);
                state.sse = Some(SseState {
                    xmm: [[0x5a; 16]; 16],
                    mxcsr: 0x1f80,
                });
                let before = state.clone();
                let mut memory = Memory::at(&code, state.rip);
                let result = run_with_addps_register_controls(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: None,
                        context: AccessContext::default(),
                    },
                    controls,
                    || false,
                );
                assert_eq!(
                    result.exit,
                    RunExit::Fault(ArchitecturalFault {
                        vector,
                        error_code: None,
                        linear_address: None,
                    })
                );
                assert_eq!(state, before);
                assert!(memory.accesses.is_empty());
            }
        }

        let short = [0x0f, 0x58];
        let mut state = LongModeState::default();
        state.rip = 0x2b100;
        state.sse = Some(SseState {
            xmm: [[0; 16]; 16],
            mxcsr: 0x1f80,
        });
        let mut memory = Memory::at(&short, state.rip);
        memory.fetch_error = Some((
            state.rip + 2,
            MemoryError::Architectural(ArchitecturalFault {
                vector: 14,
                error_code: Some(0),
                linear_address: Some(state.rip + 2),
            }),
        ));
        let result = run_with_addps_register_controls(
            &mut state,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: None,
                context: AccessContext::default(),
            },
            AddpsControls {
                sse_available: false,
                cr0_em: false,
                cr0_ts: true,
                cr4_osfxsr: false,
                cr4_osxmmexcpt: true,
            },
            || false,
        );
        assert_eq!(
            result.exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 14,
                error_code: Some(0),
                linear_address: Some(state.rip + 2),
            })
        );
        assert_eq!(result.instructions_executed, 0);
        assert_eq!(state.rip, 0x2b100);
        assert!(memory.accesses.is_empty());

        for mxcsr in [0x1fc0, 0x0001_1f80, 0x1b80, 0x1780] {
            let mut invalid_mxcsr = LongModeState::default();
            invalid_mxcsr.rip = 0x2b200;
            invalid_mxcsr.sse = Some(SseState {
                xmm: [[0; 16]; 16],
                mxcsr, // DAZ or a reserved bit is outside this profile.
            });
            let before = invalid_mxcsr.clone();
            let mut memory = Memory::at(&code, invalid_mxcsr.rip);
            assert_eq!(
                run_with_addps_register_controls(
                    &mut invalid_mxcsr,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: None,
                        context: AccessContext::default(),
                    },
                    controls,
                    || false,
                )
                .exit,
                RunExit::Unsupported { opcode: 0x58 }
            );
            assert_eq!(invalid_mxcsr, before);
            assert!(memory.accesses.is_empty());
        }

        // Generic interpreter dispatch has no ADDPS controls and stays closed.
        let mut generic = LongModeState::default();
        generic.rip = 0x2b300;
        generic.sse = Some(SseState {
            xmm: [[0; 16]; 16],
            mxcsr: 0x1f80,
        });
        let before = generic.clone();
        let mut memory = Memory::at(&code, generic.rip);
        assert_eq!(
            run(
                &mut generic,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: None,
                    context: AccessContext::default(),
                },
                || false,
            )
            .exit,
            RunExit::Unsupported { opcode: 0x58 }
        );
        assert_eq!(generic, before);
        assert!(memory.accesses.is_empty());

        // Existing sticky IE/DE/PE bits do not retrigger when a zero sum
        // produces no new event, even while IM and DM are clear.
        let mut sticky = LongModeState::default();
        sticky.rip = 0x2b400;
        let mut xmm = [[0; 16]; 16];
        xmm[0][..4].copy_from_slice(&0u32.to_le_bytes());
        xmm[1][..4].copy_from_slice(&0u32.to_le_bytes());
        sticky.sse = Some(SseState { xmm, mxcsr: 0x0e23 });
        let mut memory = Memory::at(&code, sticky.rip);
        assert_eq!(
            run_with_addps_register_controls(
                &mut sticky,
                &mut memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: None,
                    context: AccessContext::default(),
                },
                controls,
                || false,
            )
            .exit,
            RunExit::InstructionBudgetExhausted
        );
        assert_eq!(sticky.sse.as_ref().unwrap().mxcsr, 0x0e23);
        assert_eq!(sticky.rip, 0x2b403);
    }

