    #[test]
    fn addps_executes_all_xmm_pairs_from_prestate_inputs_at_all_cpls() {
        let controls = AddpsControls {
            sse_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let mut code = Vec::new();
                if destination >= 8 || source >= 8 {
                    code.push(0x40 | ((destination >> 1) & 4) | (source >> 3));
                }
                code.extend([0x0f, 0x58, modrm]);
                let pack = |lanes: [u32; 4]| {
                    let mut bytes = [0; 16];
                    for (lane, value) in lanes.into_iter().enumerate() {
                        bytes[lane * 4..lane * 4 + 4].copy_from_slice(&value.to_le_bytes());
                    }
                    bytes
                };
                let mut state = LongModeState::default();
                state.rip = 0x2c000;
                state.cs_selector = Some(u16::from(destination & 3));
                state.gpr = std::array::from_fn(|index| 0xabc0_0000 + index as u64);
                let old_gpr = state.gpr;
                let old_rflags = state.rflags;
                let xmm = std::array::from_fn(|register| {
                    let index = register as u32;
                    pack([
                        0x3f80_0000 + index * 2,
                        0xbf80_0000 + index * 2,
                        0x4000_0000 + index * 4,
                        0x8000_0000,
                    ])
                });
                let before_xmm = xmm;
                state.sse = Some(SseState { xmm, mxcsr: 0x1f80 });
                let expected = [
                    0x4000_0000 + u32::from(destination) + u32::from(source),
                    0xc000_0000 + u32::from(destination) + u32::from(source),
                    0x4080_0000 + 2 * (u32::from(destination) + u32::from(source)),
                    0x8000_0000,
                ];
                assert_eq!(
                    state.sse.as_ref().unwrap().xmm[usize::from(destination)],
                    before_xmm[usize::from(destination)]
                );
                let mut memory = Memory::at(&code, state.rip);
                let stop_rip = state.rip + code.len() as u64;
                let result = run_with_addps_register_controls(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(stop_rip),
                        context: AccessContext::default(),
                    },
                    controls,
                    || false,
                );
                assert_eq!(result.exit, RunExit::StopAddress, "{destination},{source}");
                assert_eq!(
                    state.sse.as_ref().unwrap().xmm[usize::from(destination)],
                    pack(expected),
                    "{destination},{source}"
                );
                assert_eq!(state.sse.as_ref().unwrap().mxcsr, 0x1f80);
                assert_eq!(state.gpr, old_gpr);
                assert_eq!(state.rflags, old_rflags);
                for register in 0..16 {
                    if register != usize::from(destination) {
                        assert_eq!(
                            state.sse.as_ref().unwrap().xmm[register],
                            before_xmm[register],
                            "{destination},{source},XMM{register}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn divpd_memory_rax_fetch_gates_and_address_failures_are_atomic() {
        let code = [0x66, 0x0f, 0x5e, 0x00];
        let controls = DivpdControls {
            sse2_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        let config = RunConfig {
            instruction_budget: 1,
            stop_rip: None,
            context: AccessContext::default(),
        };
        let make_state = |rax| {
            let mut state = LongModeState::default();
            state.rip = 0x2c000;
            state.write(RegisterView::low(Register::Rax, OperandSize::Qword), rax);
            state.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr: 0x1f80,
            });
            state
        };

        for (controls, vector) in [
            (
                DivpdControls {
                    sse2_available: false,
                    cr0_ts: true,
                    ..controls
                },
                6,
            ),
            (
                DivpdControls {
                    cr0_em: true,
                    cr0_ts: true,
                    ..controls
                },
                6,
            ),
            (
                DivpdControls {
                    cr4_osfxsr: false,
                    cr0_ts: true,
                    ..controls
                },
                6,
            ),
            (
                DivpdControls {
                    cr0_ts: true,
                    ..controls
                },
                7,
            ),
        ] {
            for cpl in 0..=3 {
                let mut state = make_state(0x1000);
                state.cs_selector = Some(cpl);
                let before = state.clone();
                let mut memory = Memory::at(&code, state.rip);
                let result = run_with_divpd_memory_rax_controls(
                    &mut state,
                    &mut memory,
                    config,
                    controls,
                    || false,
                );
                assert_eq!(
                    result.exit,
                    RunExit::Fault(ArchitecturalFault {
                        vector,
                        error_code: None,
                        linear_address: None
                    })
                );
                assert_eq!(state, before);
                assert!(memory.accesses.is_empty());
            }
        }

        let mut short = make_state(0x1000);
        let before = short.clone();
        let mut memory = Memory::at(&code[..3], short.rip);
        memory.fetch_error = Some((
            short.rip + 3,
            MemoryError::Architectural(ArchitecturalFault {
                vector: 14,
                error_code: Some(0),
                linear_address: Some(short.rip + 3),
            }),
        ));
        let result = run_with_divpd_memory_rax_controls(
            &mut short,
            &mut memory,
            config,
            DivpdControls {
                sse2_available: false,
                cr0_ts: true,
                ..controls
            },
            || false,
        );
        assert_eq!(
            result.exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 14,
                error_code: Some(0),
                linear_address: Some(before.rip + 3)
            })
        );
        assert_eq!(short, before);
        assert!(memory.accesses.is_empty());

        for address in [0x1001, 0x0000_8000_0000_0000] {
            let mut state = make_state(address);
            let before = state.clone();
            let mut memory = Memory::at(&code, state.rip);
            assert_eq!(
                run_with_divpd_memory_rax_controls(
                    &mut state,
                    &mut memory,
                    config,
                    controls,
                    || false
                )
                .exit,
                RunExit::Fault(ArchitecturalFault {
                    vector: 13,
                    error_code: Some(0),
                    linear_address: None
                })
            );
            assert_eq!(state, before);
            assert!(memory.accesses.is_empty());
        }

        let mut state = make_state(0x1000);
        let before = state.clone();
        let mut memory = Memory::at(&code, state.rip);
        memory.error = Some(MemoryError::Backend("injected DIVPD read failure".into()));
        memory.error_kind = Some(AccessKind::Read);
        assert_eq!(
            run_with_divpd_memory_rax_controls(&mut state, &mut memory, config, controls, || false)
                .exit,
            RunExit::MemoryError(MemoryError::Backend("injected DIVPD read failure".into()))
        );
        assert_eq!(state, before);
        assert_eq!(memory.accesses, [(AccessKind::Read, 0x1000, 16)]);

        // The largest aligned canonical base has an inclusive endpoint of
        // u64::MAX; checked addition succeeds and the single read then faults.
        let endpoint = 0xffff_ffff_ffff_fff0;
        let mut state = make_state(endpoint);
        let before = state.clone();
        let mut memory = Memory::at(&code, state.rip);
        assert_eq!(
            run_with_divpd_memory_rax_controls(&mut state, &mut memory, config, controls, || false)
                .exit,
            RunExit::MemoryError(MemoryError::Unmapped {
                address: endpoint,
                access: AccessKind::Read
            })
        );
        assert_eq!(state, before);
        assert_eq!(memory.accesses, [(AccessKind::Read, endpoint, 16)]);
    }

    #[test]
    fn divpd_register_pairs_snapshot_all_xmm_aliases_atomically() {
        let controls = DivpdControls {
            sse2_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        for destination in 0u8..16 {
            for source in 0u8..16 {
                let mut code = vec![0x66];
                if destination >= 8 || source >= 8 {
                    code.push(0x40 | ((destination >> 1) & 4) | (source >> 3));
                }
                code.extend([0x0f, 0x5e, 0xc0 | ((destination & 7) << 3) | (source & 7)]);
                let mut state = LongModeState::default();
                state.rip = 0x2a000;
                let mut xmm = [[0x5a; 16]; 16];
                for register in &mut xmm {
                    register[..8].copy_from_slice(&0x4000_0000_0000_0000u64.to_le_bytes());
                    register[8..].copy_from_slice(&0x4000_0000_0000_0000u64.to_le_bytes());
                }
                state.sse = Some(SseState { xmm, mxcsr: 0x1f80 });
                let rip = state.rip;
                let mut memory = Memory::at(&code, rip);
                let result = run_with_divpd_register_controls(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(rip + code.len() as u64),
                        context: AccessContext::default(),
                    },
                    controls,
                    || false,
                );
                assert_eq!(result.exit, RunExit::StopAddress, "{destination},{source}");
                assert_eq!(result.instructions_executed, 1);
                let sse = state.sse.as_ref().unwrap();
                assert_eq!(
                    u64::from_le_bytes(sse.xmm[usize::from(destination)][..8].try_into().unwrap()),
                    0x3ff0_0000_0000_0000,
                    "{destination},{source}"
                );
                assert_eq!(
                    u64::from_le_bytes(sse.xmm[usize::from(destination)][8..].try_into().unwrap()),
                    0x3ff0_0000_0000_0000,
                    "{destination},{source}"
                );
                assert_eq!(sse.mxcsr, 0x1f80);
                assert!(memory.accesses.is_empty());
            }
        }
    }

