    #[test]
    fn divsd_ftz_preserves_binary64_negative_zero_and_underflow_flags() {
        let code = [0xf2, 0x0f, 0x5e, 0xc1];
        let mut state = LongModeState::default();
        state.rip = 0x2b300;
        let mut xmm = [[0x5a; 16]; 16];
        xmm[0][..8].copy_from_slice(&0x8010_0000_0000_0000u64.to_le_bytes());
        xmm[0][8..].copy_from_slice(&0x1234_5678_9abc_def0u64.to_le_bytes());
        xmm[1][..8].copy_from_slice(&0x4000_0000_0000_0000u64.to_le_bytes());
        state.sse = Some(SseState { xmm, mxcsr: 0x9f80 });
        let mut memory = Memory::at(&code, state.rip);
        let stop_rip = state.rip + code.len() as u64;
        let result = run_with_divsd_register_controls(
            &mut state,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: Some(stop_rip),
                context: AccessContext::default(),
            },
            DivsdControls {
                sse2_available: true,
                cr0_em: false,
                cr0_ts: false,
                cr4_osfxsr: true,
                cr4_osxmmexcpt: true,
            },
            || false,
        );
        assert_eq!(result.exit, RunExit::StopAddress);
        assert_eq!(result.instructions_executed, 1);
        let sse = state.sse.as_ref().unwrap();
        assert_eq!(
            u64::from_le_bytes(sse.xmm[0][..8].try_into().unwrap()),
            0x8000_0000_0000_0000
        );
        assert_eq!(
            u64::from_le_bytes(sse.xmm[0][8..].try_into().unwrap()),
            0x1234_5678_9abc_def0
        );
        assert_eq!(sse.mxcsr & 0x3f, 0x30);
        assert!(memory.accesses.is_empty());
    }

    #[test]
    fn divsd_and_divpd_profiles_are_separate_and_numerical_ud_is_preserved() {
        let divsd = [0xf2, 0x0f, 0x5e, 0xc1];
        let divpd = [0x66, 0x0f, 0x5e, 0xc1];
        let divsd_controls = DivsdControls {
            sse2_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        let divpd_controls = DivpdControls {
            sse2_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        for (code, use_divsd) in [(&divsd[..], false), (&divpd[..], true)] {
            let mut state = LongModeState::default();
            state.rip = 0x2b400;
            state.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr: 0x1f80,
            });
            let before = state.clone();
            let mut memory = Memory::at(code, state.rip);
            let config = RunConfig {
                instruction_budget: 1,
                stop_rip: None,
                context: AccessContext::default(),
            };
            let result = if use_divsd {
                run_with_divsd_register_controls(
                    &mut state,
                    &mut memory,
                    config,
                    divsd_controls,
                    || false,
                )
            } else {
                run_with_divpd_register_controls(
                    &mut state,
                    &mut memory,
                    config,
                    divpd_controls,
                    || false,
                )
            };
            assert_eq!(result.exit, RunExit::Unsupported { opcode: 0x5e });
            assert_eq!(result.instructions_executed, 0);
            assert_eq!(state, before);
        }

        let mut state = LongModeState::default();
        state.rip = 0x2b500;
        let mut xmm = [[0x5a; 16]; 16];
        xmm[0][..8].copy_from_slice(&0u64.to_le_bytes());
        xmm[1][..8].copy_from_slice(&0u64.to_le_bytes());
        state.sse = Some(SseState { xmm, mxcsr: 0x1f00 });
        let before_xmm = state.sse.as_ref().unwrap().xmm;
        let mut controls = divsd_controls;
        controls.cr4_osxmmexcpt = false;
        let mut memory = Memory::at(&divsd, state.rip);
        let result = run_with_divsd_register_controls(
            &mut state,
            &mut memory,
            RunConfig {
                instruction_budget: 1,
                stop_rip: None,
                context: AccessContext::default(),
            },
            controls,
            || false,
        );
        assert_eq!(
            result.exit,
            RunExit::Fault(ArchitecturalFault {
                vector: 6,
                error_code: None,
                linear_address: None,
            })
        );
        assert_eq!(state.sse.as_ref().unwrap().mxcsr & 1, 1);
        assert_eq!(state.sse.as_ref().unwrap().xmm, before_xmm);
        assert_eq!(state.rip, 0x2b500);
        assert_eq!(result.instructions_executed, 0);
    }

