    #[test]
    fn mulss_register_pairs_snapshot_all_xmm_aliases_atomically() {
        let controls = MulssControls {
            sse_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        for destination in 0u8..16 {
            for source in 0u8..16 {
                let mut code = vec![0xf3];
                if destination >= 8 || source >= 8 {
                    code.push(0x40 | ((destination >> 1) & 4) | (source >> 3));
                }
                code.extend([0x0f, 0x59, 0xc0 | ((destination & 7) << 3) | (source & 7)]);
                let mut state = LongModeState::default();
                state.rip = 0x2a000;
                let mut xmm = [[0x5a; 16]; 16];
                for register in &mut xmm {
                    register[..4].copy_from_slice(&0x4000_0000u32.to_le_bytes());
                    register[4..].fill(0xc0);
                }
                state.sse = Some(SseState { xmm, mxcsr: 0x1f80 });
                let rip = state.rip;
                let mut memory = Memory::at(&code, rip);
                let result = run_with_mulss_register_controls(
                    &mut state,
                    &mut memory,
                    RunConfig {
                        instruction_budget: 1,
                        stop_rip: Some(rip + code.len() as u64),
                        context: AccessContext::default(),
                    },
                    controls,
                    || false,
                );
                assert_eq!(result.exit, RunExit::StopAddress, "{destination},{source}");
                assert_eq!(result.instructions_executed, 1);
                let sse = state.sse.as_ref().unwrap();
                assert_eq!(
                    u32::from_le_bytes(sse.xmm[usize::from(destination)][..4].try_into().unwrap()),
                    0x4080_0000,
                    "{destination},{source}"
                );
                assert_eq!(
                    [0xc0; 12],
                    sse.xmm[usize::from(destination)][4..],
                    "{destination},{source}"
                );
                assert_eq!(sse.mxcsr, 0x1f80);
                assert!(memory.accesses.is_empty());
            }
        }
    }

