    #[test]
    fn subss_memory_rax_gates_fetch_address_precedence_and_read_failure_are_atomic() {
        use crate::memory::AccessKind;
        let code = [0xf3, 0x0f, 0x5c, 0x00];
        let controls = SubssMemoryRaxControls {
            sse_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        let run = |state: &mut LongModeState, memory: &mut Memory, controls| {
            run_with_subss_memory_rax_controls(
                state,
                memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(state.rip + 4),
                    context: AccessContext::default(),
                },
                controls,
                || false,
            )
        };
        for (controls, vector) in [
            (
                SubssMemoryRaxControls {
                    sse_available: false,
                    ..controls
                },
                6,
            ),
            (
                SubssMemoryRaxControls {
                    cr0_em: true,
                    ..controls
                },
                6,
            ),
            (
                SubssMemoryRaxControls {
                    cr4_osfxsr: false,
                    ..controls
                },
                6,
            ),
            (
                SubssMemoryRaxControls {
                    cr0_ts: true,
                    ..controls
                },
                7,
            ),
            (
                SubssMemoryRaxControls {
                    sse_available: false,
                    cr0_ts: true,
                    ..controls
                },
                6,
            ),
        ] {
            let mut state = LongModeState::default();
            state.rip = 0x5300;
            state.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr: 0x1f80,
            });
            let before = state.clone();
            let mut memory = Memory::at(&code, 0x5300);
            let result = run(&mut state, &mut memory, controls);
            assert_eq!(
                result.exit,
                RunExit::Fault(ArchitecturalFault {
                    vector,
                    error_code: None,
                    linear_address: None
                })
            );
            assert_eq!(memory.fetches, [0x5300, 0x5301, 0x5302, 0x5303]);
            assert!(memory.accesses.is_empty());
            assert_eq!(state, before);
        }
        let mut absent = LongModeState::default();
        absent.rip = 0x5300;
        let mut memory = Memory::at(&code, 0x5300);
        assert_eq!(
            run(&mut absent, &mut memory, controls).exit,
            RunExit::Unsupported { opcode: 0x5c }
        );
        assert_eq!(memory.fetches, [0x5300, 0x5301, 0x5302, 0x5303]);
        assert!(memory.accesses.is_empty());

        for mxcsr in [0x1f00, 0x1fc0, 0x9f80, 0x11f80] {
            let mut state = LongModeState::default();
            state.rip = 0x5300;
            state.gpr[Register::Rax as usize] = 0x2000;
            state.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr,
            });
            let before = state.clone();
            let mut memory = Memory::at(&code, 0x5300);
            assert_eq!(
                run(&mut state, &mut memory, controls).exit,
                RunExit::Unsupported { opcode: 0x5c }
            );
            assert_eq!(memory.fetches, [0x5300, 0x5301, 0x5302, 0x5303]);
            assert!(memory.accesses.is_empty());
            assert_eq!(state, before);
        }

        let mut ac = LongModeState::default();
        ac.rip = 0x5300;
        ac.rflags |= 1 << 18;
        ac.gpr[Register::Rax as usize] = u64::MAX;
        ac.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x1f80,
        });
        let before = ac.clone();
        let mut memory = Memory::at(&code, 0x5300);
        assert_eq!(
            run(&mut ac, &mut memory, controls).exit,
            RunExit::Unsupported { opcode: 0x5c }
        );
        assert_eq!(ac, before);
        assert!(memory.accesses.is_empty());

        let mut unaligned = LongModeState::default();
        unaligned.rip = 0x5300;
        unaligned.gpr[Register::Rax as usize] = 0x2001;
        unaligned.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x1f80,
        });
        let mut unaligned_memory = Memory::at(&code, 0x5300);
        unaligned_memory.data_base = 0x2000;
        unaligned_memory.bytes[1..5].copy_from_slice(&0x3f80_0000u32.to_le_bytes());
        assert_eq!(
            run(&mut unaligned, &mut unaligned_memory, controls).exit,
            RunExit::StopAddress
        );
        assert_eq!(unaligned_memory.accesses, [(AccessKind::Read, 0x2001, 4)]);

        let mut unconfigured = LongModeState::default();
        unconfigured.rip = 0x5300;
        unconfigured.gpr[Register::Rax as usize] = 0x2000;
        unconfigured.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x1f80,
        });
        let mut unconfigured_memory = Memory::at(&code, 0x5300);
        assert_eq!(
            step(
                &mut unconfigured,
                &mut unconfigured_memory,
                AccessContext::default()
            )
            .unwrap(),
            StepOutcome::Unsupported { opcode: 0x5c },
        );
        assert!(unconfigured_memory.accesses.is_empty());

        for address in [0x0000_7fff_ffff_fffd, u64::MAX - 1] {
            let mut state = LongModeState::default();
            state.rip = 0x5300;
            state.gpr[Register::Rax as usize] = address;
            state.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr: 0x1f80,
            });
            let before = state.clone();
            let mut memory = Memory::at(&code, 0x5300);
            assert_eq!(
                run(&mut state, &mut memory, controls).exit,
                RunExit::Fault(ArchitecturalFault {
                    vector: 13,
                    error_code: Some(0),
                    linear_address: None
                })
            );
            assert_eq!(state, before);
            assert!(memory.accesses.is_empty());
        }

        let mut state = LongModeState::default();
        state.rip = 0x5300;
        state.gpr[Register::Rax as usize] = 0x2000;
        state.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x1f80,
        });
        let before = state.clone();
        let mut memory = Memory::at(&code, 0x5300);
        memory.data_base = 0x2000;
        memory.error = Some(MemoryError::Unmapped {
            address: 0x2000,
            access: AccessKind::Read,
        });
        assert!(matches!(
            run(&mut state, &mut memory, controls).exit,
            RunExit::MemoryError(_)
        ));
        assert_eq!(state, before);
        assert_eq!(memory.accesses, [(AccessKind::Read, 0x2000, 4)]);
    }

    #[test]
    fn mulss_memory_rax_reads_unaligned_m32_once_and_rolls_back_failures() {
        use crate::memory::AccessKind;

        let code = [0xf3, 0x0f, 0x59, 0x00];
        let controls = MulssControls {
            sse_available: true,
            cr0_em: false,
            cr0_ts: false,
            cr4_osfxsr: true,
            cr4_osxmmexcpt: true,
        };
        let run_profile = |state: &mut LongModeState, memory: &mut Memory, controls| {
            run_with_mulss_memory_rax_controls(
                state,
                memory,
                RunConfig {
                    instruction_budget: 1,
                    stop_rip: Some(state.rip + 4),
                    context: AccessContext::default(),
                },
                controls,
                || false,
            )
        };

        let mut state = LongModeState::default();
        state.rip = 0x5300;
        state.gpr[Register::Rax as usize] = 0x2001;
        state.sse = Some(SseState {
            xmm: [[0xa5; 16]; 16],
            mxcsr: 0x1f80,
        });
        state.sse.as_mut().unwrap().xmm[0][..4].copy_from_slice(&2.0f32.to_bits().to_le_bytes());
        state.sse.as_mut().unwrap().xmm[0][4..].copy_from_slice(&[
            0xef, 0xbe, 0xad, 0xde, 0x78, 0x56, 0x34, 0x12, 0xa5, 0xa5, 0xc3, 0xc3,
        ]);
        let xmm1 = state.sse.as_ref().unwrap().xmm[1];
        let high96 = state.sse.as_ref().unwrap().xmm[0][4..].to_vec();
        let mut memory = Memory::at(&code, 0x5300);
        memory.data_base = 0x2000;
        memory.bytes[1..5].copy_from_slice(&0.5f32.to_bits().to_le_bytes());
        let result = run_profile(&mut state, &mut memory, controls);
        assert_eq!(result.exit, RunExit::StopAddress);
        assert_eq!(result.instructions_executed, 1);
        assert_eq!(
            u32::from_le_bytes(state.sse.as_ref().unwrap().xmm[0][..4].try_into().unwrap()),
            1.0f32.to_bits()
        );
        assert_eq!(&state.sse.as_ref().unwrap().xmm[0][4..], high96);
        assert_eq!(state.sse.as_ref().unwrap().xmm[1], xmm1);
        assert_eq!(state.sse.as_ref().unwrap().mxcsr, 0x1f80);
        assert_eq!(state.rip, 0x5304);
        assert_eq!(memory.accesses, [(AccessKind::Read, 0x2001, 4)]);

        let mut rollback = LongModeState::default();
        rollback.rip = 0x5300;
        rollback.gpr[Register::Rax as usize] = 0x2000;
        rollback.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x1f80,
        });
        let before = rollback.clone();
        let mut failed = Memory::at(&code, 0x5300);
        failed.data_base = 0x2000;
        failed.error = Some(MemoryError::Unmapped {
            address: 0x2000,
            access: AccessKind::Read,
        });
        assert!(matches!(
            run_profile(&mut rollback, &mut failed, controls).exit,
            RunExit::MemoryError(_)
        ));
        assert_eq!(rollback, before);
        assert_eq!(failed.accesses, [(AccessKind::Read, 0x2000, 4)]);

        for (candidate, vector) in [
            (
                MulssControls {
                    sse_available: false,
                    ..controls
                },
                6,
            ),
            (
                MulssControls {
                    cr0_em: true,
                    ..controls
                },
                6,
            ),
            (
                MulssControls {
                    cr4_osfxsr: false,
                    ..controls
                },
                6,
            ),
            (
                MulssControls {
                    cr0_ts: true,
                    ..controls
                },
                7,
            ),
        ] {
            let mut gated = LongModeState::default();
            gated.rip = 0x5300;
            gated.gpr[Register::Rax as usize] = 0x2000;
            gated.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr: 0x1f80,
            });
            let before = gated.clone();
            let mut untouched = Memory::at(&code, 0x5300);
            assert_eq!(
                run_profile(&mut gated, &mut untouched, candidate).exit,
                RunExit::Fault(ArchitecturalFault {
                    vector,
                    error_code: None,
                    linear_address: None
                })
            );
            assert_eq!(untouched.fetches, [0x5300, 0x5301, 0x5302, 0x5303]);
            assert!(untouched.accesses.is_empty());
            assert_eq!(gated, before);
        }

        for mxcsr in [0x1f40, 0x1f00, 0x9f80, 0x11f80] {
            let mut invalid_mxcsr = LongModeState::default();
            invalid_mxcsr.rip = 0x5300;
            invalid_mxcsr.gpr[Register::Rax as usize] = 0x2000;
            invalid_mxcsr.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr,
            });
            let before = invalid_mxcsr.clone();
            let mut untouched = Memory::at(&code, 0x5300);
            let result = run_profile(&mut invalid_mxcsr, &mut untouched, controls);
            assert_eq!(
                result.exit,
                RunExit::Unsupported { opcode: 0x59 },
                "MXCSR={mxcsr:#x}"
            );
            assert_eq!(result.instructions_executed, 0);
            assert_eq!(invalid_mxcsr, before);
            assert_eq!(untouched.fetches, [0x5300, 0x5301, 0x5302, 0x5303]);
            assert!(untouched.accesses.is_empty());
        }

        let mut truncated_state = LongModeState::default();
        truncated_state.rip = 0x5300;
        truncated_state.gpr[Register::Rax as usize] = 0x2000;
        truncated_state.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x1f80,
        });
        let before = truncated_state.clone();
        let mut truncated = Memory::at(&code[..2], 0x5300);
        truncated.fetch_error = Some((
            0x5302,
            MemoryError::Unmapped {
                address: 0x5302,
                access: AccessKind::Read,
            },
        ));
        let unavailable = MulssControls {
            sse_available: false,
            cr0_ts: true,
            ..controls
        };
        let result = run_profile(&mut truncated_state, &mut truncated, unavailable);
        assert!(matches!(result.exit, RunExit::MemoryError(_)));
        assert_eq!(result.instructions_executed, 0);
        assert_eq!(truncated_state, before);
        assert_eq!(truncated.fetches, [0x5300, 0x5301, 0x5302]);
        assert!(truncated.accesses.is_empty());

        let mut ac = LongModeState::default();
        ac.rip = 0x5300;
        ac.rflags |= 1 << 18;
        ac.gpr[Register::Rax as usize] = 0x0000_8000_0000_0000;
        ac.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x1f80,
        });
        let before = ac.clone();
        let mut ac_memory = Memory::at(&code, 0x5300);
        assert_eq!(
            run_profile(&mut ac, &mut ac_memory, controls).exit,
            RunExit::Unsupported { opcode: 0x59 }
        );
        assert_eq!(ac, before);
        assert!(ac_memory.accesses.is_empty());

        for address in [0x0000_7fff_ffff_fffd, u64::MAX - 1] {
            let mut invalid = LongModeState::default();
            invalid.rip = 0x5300;
            invalid.gpr[Register::Rax as usize] = address;
            invalid.sse = Some(SseState {
                xmm: [[0x5a; 16]; 16],
                mxcsr: 0x1f80,
            });
            let before = invalid.clone();
            let mut untouched = Memory::at(&code, 0x5300);
            assert_eq!(
                run_profile(&mut invalid, &mut untouched, controls).exit,
                RunExit::Fault(ArchitecturalFault {
                    vector: 13,
                    error_code: Some(0),
                    linear_address: None
                })
            );
            assert_eq!(invalid, before);
            assert!(untouched.accesses.is_empty());
        }

        let mut unconfigured = LongModeState::default();
        unconfigured.rip = 0x5300;
        unconfigured.sse = Some(SseState {
            xmm: [[0x5a; 16]; 16],
            mxcsr: 0x1f80,
        });
        let mut memory = Memory::at(&code, 0x5300);
        assert_eq!(
            step(&mut unconfigured, &mut memory, AccessContext::default()).unwrap(),
            StepOutcome::Unsupported { opcode: 0x59 }
        );
        assert!(memory.accesses.is_empty());
    }

